window.songs=[{"order":2,"id":"02-le-bagne-pitie-pitie","title":"Le bagne: pitié, pitié","titleZh":"流放地：可怜，可怜","lines":[{"id":"les-miserables-cityprod-2017-02-001","lineIndex":1,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-02-002","lineIndex":2,"speaker":"","original":"C'est ta vie que tu traînes","ipa":"/sɛ ta vi kə ty tʁɛn/","zh":"你拖着的正是自己的命","en":"It's your life that you're dragging along","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-02-003","lineIndex":3,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-02-004","lineIndex":4,"speaker":"","original":"Au boulet de ta chaîne","ipa":"/o bulɛ də ta ʃɛn/","zh":"被铁球与锁链拖缚","en":"At the ball of your chain","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-02-005","lineIndex":5,"speaker":"","original":"On brûle, on crève","ipa":"/ɔ̃ bʁyl ɔ̃ kʁɛv/","zh":"我们煎熬，我们死去","en":"We burn, we die","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-02-006","lineIndex":6,"speaker":"","original":"C'est l'enfer là-dedans","ipa":"/sɛ lɑ̃fɛʁ ladədɑ̃/","zh":"那里简直就是地狱","en":"It's hell in there","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-02-007","lineIndex":7,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-02-008","lineIndex":8,"speaker":"","original":"On en a pour vingt ans","ipa":"/ɔ̃n ɑ̃n a puʁ vɛ̃t ɑ̃/","zh":"这一熬就是二十年","en":"We have twenty years","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-02-009","lineIndex":9,"speaker":"","original":"J'ai fait rien de mal","ipa":"/ʒe fɛ ʁjɛ̃ də mal/","zh":"我没有做错任何事","en":"I didn't do anything wrong","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-02-010","lineIndex":10,"speaker":"","original":"Doux Jésus, je t'implore","ipa":"/du ʒezy ʒə tɛ̃plɔʁ/","zh":"仁慈的耶稣啊，我求求你","en":"Sweet Jesus, I implore you","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-02-011","lineIndex":11,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-02-012","lineIndex":12,"speaker":"","original":"Doux Jésus fait le mort","ipa":"/du ʒezy fɛ lə mɔʁ/","zh":"慈悲的耶稣却装聋作哑","en":"Sweet Jesus plays dead","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-02-013","lineIndex":13,"speaker":"","original":"Je sais qu'elle m'aime","ipa":"/ʒə sɛ kɛl mɛm/","zh":"我知道她爱我","en":"I know she loves me","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-02-014","lineIndex":14,"speaker":"","original":"Qu'elle me sera fidèle.","ipa":"/kɛl mə səʁa fidɛl/","zh":"她会对我忠诚。","en":"That she will be faithful to me.","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-02-015","lineIndex":15,"speaker":"","original":"Qui sait? Qui sait?","ipa":"/ki sɛ ki sɛ/","zh":"谁知道？谁知道？","en":"Who knows? Who knows?","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-02-016","lineIndex":16,"speaker":"","original":"Si personne ne veut d'elle...","ipa":"/si pɛʁsɔn nə vø dɛl/","zh":"要是没有人肯要她……","en":"If no one wants her...","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-02-017","lineIndex":17,"speaker":"","original":"Quand je serai libre","ipa":"/kɑ̃ ʒə səʁe libʁ/","zh":"等我重获自由","en":"When I'm free","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-02-018","lineIndex":18,"speaker":"","original":"Je me vengerai sans pitié","ipa":"/ʒə mə vɑ̃ʒʁe sɑ̃ pitje/","zh":"我将毫不留情地报仇","en":"I will take revenge without mercy","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-02-019","lineIndex":19,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-02-020","lineIndex":20,"speaker":"","original":"Jusqu'où peut-on souffrir?","ipa":"/ʒysku pøtɔ̃ sufʁiʁ/","zh":"人能受苦到什么地步？","en":"How much can we suffer?","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-02-021","lineIndex":21,"speaker":"","original":"Pitié, seigneur","ipa":"/pitje sɛnjœʁ/","zh":"怜悯我吧，主啊","en":"Please, lord","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-02-022","lineIndex":22,"speaker":"","original":"Laisse-moi plutôt mourir","ipa":"/lɛsmwa plyto muʁiʁ/","zh":"不如让我去死","en":"Rather let me die","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-02-023","lineIndex":23,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-02-024","lineIndex":24,"speaker":"","original":"C'est ta vie que tu traînes","ipa":"/sɛ ta vi kə ty tʁɛn/","zh":"你拖着的就是你的生活","en":"It's your life that you're dragging along","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-02-025","lineIndex":25,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-02-026","lineIndex":26,"speaker":"","original":"Au boulet de ta chaîne","ipa":"/o bulɛ də ta ʃɛn/","zh":"被铁球与锁链拖缚","en":"At the ball of your chain","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-02-027","lineIndex":27,"speaker":"","original":"Qu'on m'amène le prisonnier 24.601","ipa":"/kɔ̃ mamɛn lə pʁizɔnje vɛ̃tkatʁ mil sisɑ̃ œ̃/","zh":"把囚犯 24.601 带来","en":"Bring me prisoner 24.601","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-02-028","lineIndex":28,"speaker":"","original":"Tu as fait ton temps","ipa":"/ty a fɛ tɔ̃ tɑ̃/","zh":"你的刑期已满","en":"You've done your time","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-02-029","lineIndex":29,"speaker":"","original":"Ta probation commence","ipa":"/ta pʁobasjɔ̃ kɔmɑ̃s/","zh":"你的假释开始了","en":"Your probation begins","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-02-030","lineIndex":30,"speaker":"","original":"Est-ce que tu comprends?","ipa":"/ɛs kə ty kɔ̃pʁɑ̃/","zh":"你明白吗？","en":"Do you understand?","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-02-031","lineIndex":31,"speaker":"","original":"Oui, que je suis libre","ipa":"/wi kə ʒə sɥi libʁ/","zh":"是的，我是自由的","en":"Yes, that I am free","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-02-032","lineIndex":32,"speaker":"","original":"Non!","ipa":"/nɔ̃/","zh":"不！","en":"No!","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-02-033","lineIndex":33,"speaker":"","original":"Ça veut dire qu'on te donne un passeport jaune","ipa":"/sa vø diʁ kɔ̃ tə dɔn œ̃ paspɔʁ ʒon/","zh":"这意味着要给你发一本黄护照","en":"That means we give you a yellow passport","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-02-034","lineIndex":34,"speaker":"","original":"Tu es un voleur!","ipa":"/ty ɛz œ̃ volœʁ/","zh":"你是小偷！","en":"You are a thief!","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-02-035","lineIndex":35,"speaker":"","original":"J'ai pris une miche de pain","ipa":"/ʒe pʁi yn miʃ də pɛ̃/","zh":"我偷了一条面包","en":"I took a loaf of bread","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-02-036","lineIndex":36,"speaker":"","original":"Par effraction","ipa":"/paʁ efʁaksjɔ̃/","zh":"破门而入","en":"Breaking and entering","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-02-037","lineIndex":37,"speaker":"","original":"J'ai cassé un carreau","ipa":"/ʒe kase œ̃ kaʁo/","zh":"我打破了一扇窗户","en":"I broke a window","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-02-038","lineIndex":38,"speaker":"","original":"Pour nourrir l'enfant de ma sœur","ipa":"/puʁ nuʁiʁ lɑ̃fɑ̃ də ma sœʁ/","zh":"为了喂养我姐姐的孩子","en":"To feed my sister's child","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-02-039","lineIndex":39,"speaker":"","original":"J'ai payé très cher","ipa":"/ʒe pɛje tʁɛ ʃɛʁ/","zh":"我已付出惨重代价","en":"I paid a lot","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-02-040","lineIndex":40,"speaker":"","original":"Tu paieras encore","ipa":"/ty pɛʁaz ɑ̃kɔʁ/","zh":"你还要继续偿还代价","en":"You will pay again","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-02-041","lineIndex":41,"speaker":"","original":"Si tu n'apprends pas à respecter la loi","ipa":"/si ty napʁɑ̃ paz a ʁɛspɛkte la lwa/","zh":"如果你不学会尊重法律","en":"If you don't learn to respect the law","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-02-042","lineIndex":42,"speaker":"","original":"Je sais le prix de ces dix-neuf années","ipa":"/ʒə sɛ lə pʁi də se diznœf ane/","zh":"我知道这十九年的代价","en":"I know the price of these nineteen years","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-02-043","lineIndex":43,"speaker":"","original":"Que la loi m'a volé","ipa":"/kə la lwa ma vole/","zh":"是法律从我身上夺走的","en":"That the law stole from me","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-02-044","lineIndex":44,"speaker":"","original":"Cinq ans pour tes méfaits","ipa":"/sɛ̃k ɑ̃ puʁ te mefɛ/","zh":"你的罪行，判五年","en":"Five years for your misdeeds","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-02-045","lineIndex":45,"speaker":"","original":"Le reste pour avoir voulu fuir","ipa":"/lə ʁɛst puʁ avwaʁ vuly fyiʁ/","zh":"其余则因为你企图逃跑","en":"The rest for wanting to escape","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-02-046","lineIndex":46,"speaker":"","original":"Oui, 24.601","ipa":"/wi vɛ̃tkatʁ mil sisɑ̃ œ̃/","zh":"是的，24.601","en":"Yes, 24, 601","note":"","sourceLineIndex":46},{"id":"les-miserables-cityprod-2017-02-047","lineIndex":47,"speaker":"","original":"Je m'appelle Jean Valjean","ipa":"/ʒə mapɛl ʒɑ̃ valʒɑ̃/","zh":"我叫冉阿让","en":"My name is Jean Valjean","note":"","sourceLineIndex":47},{"id":"les-miserables-cityprod-2017-02-048","lineIndex":48,"speaker":"","original":"Et moi Javert","ipa":"/e mwa ʒavɛʁ/","zh":"而我叫沙威","en":"And me Javert","note":"","sourceLineIndex":48},{"id":"les-miserables-cityprod-2017-02-049","lineIndex":49,"speaker":"","original":"N'oublie jamais mon nom","ipa":"/nubli ʒamɛ mɔ̃ nɔ̃/","zh":"永远不要忘记我的名字","en":"Never forget my name","note":"","sourceLineIndex":49},{"id":"les-miserables-cityprod-2017-02-050","lineIndex":50,"speaker":"","original":"Ne m'oublie jamais, 24.601","ipa":"/nə mubli ʒamɛ vɛ̃tkatʁ mil sisɑ̃ œ̃/","zh":"别忘了我，24.601","en":"Never forget me, 24.601","note":"","sourceLineIndex":50},{"id":"les-miserables-cityprod-2017-02-051","lineIndex":51,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":51},{"id":"les-miserables-cityprod-2017-02-052","lineIndex":52,"speaker":"","original":"C'est la mort que tu traînes","ipa":"/sɛ la mɔʁ kə ty tʁɛn/","zh":"你拖着的就是死亡","en":"It's death that you drag","note":"","sourceLineIndex":52},{"id":"les-miserables-cityprod-2017-02-053","lineIndex":53,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":53},{"id":"les-miserables-cityprod-2017-02-054","lineIndex":54,"speaker":"","original":"Au boulet de ta chaîne","ipa":"/o bulɛ də ta ʃɛn/","zh":"被铁球与锁链拖缚","en":"At the ball of your chain","note":"","sourceLineIndex":54}],"sourceOrder":2,"displayOrder":1},{"order":3,"id":"03-l-eveque-de-digne","title":"L'évêque de Digne","titleZh":"迪涅主教","lines":[{"id":"les-miserables-cityprod-2017-03-001","lineIndex":1,"speaker":"","original":"Répète donc un peu ta fable","ipa":"/ʁepɛt dɔ̃k œ̃ pø ta fabl/","zh":"再把你的谎话说一遍吧","en":"So repeat your fable a little","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-03-002","lineIndex":2,"speaker":"","original":"Si tu l'oses à Monseigneur","ipa":"/si ty lozz a mɔ̃sɛnjœʁ/","zh":"你若敢当着主教的面","en":"If you dare to Monsignor","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-03-003","lineIndex":3,"speaker":"","original":"Toi qui as partagé sa table","ipa":"/twa ki a paʁtaʒe sa tabl/","zh":"曾与他同桌共食的你","en":"You who shared his table","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-03-004","lineIndex":4,"speaker":"","original":"Toi qui fus l'hôte de Monseigneur","ipa":"/twa ki fy lot də mɔ̃sɛnjœʁ/","zh":"你曾作主教的座上宾","en":"You who were Monseigneur's guest","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-03-005","lineIndex":5,"speaker":"","original":"Et par charité chrétienne","ipa":"/e paʁ ʃaʁite kʁetjɛn/","zh":"又出于基督徒的慈悲","en":"And out of Christian charity","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-03-006","lineIndex":6,"speaker":"","original":"Quand il connut ton passé","ipa":"/kɑ̃t il kɔny tɔ̃ pase/","zh":"当他得知你的过去","en":"When he knew your past","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-03-007","lineIndex":7,"speaker":"","original":"Tu prétends qu'il t'a offert","ipa":"/ty pʁetɑ̃ kil ta ɔfɛʁ/","zh":"你却声称是他赠予你的","en":"You claim he gave you","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-03-008","lineIndex":8,"speaker":"","original":"Ces couverts d'argent","ipa":"/se kuvɛʁ daʁʒɑ̃/","zh":"这些银餐具","en":"These silver cutlery","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-03-009","lineIndex":9,"speaker":"","original":"Il dit vrai!","ipa":"/il di vʁɛ/","zh":"他说的是实话！","en":"He speaks the truth!","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-03-010","lineIndex":10,"speaker":"","original":"Mais mon ami vous êtes parti","ipa":"/mɛ mɔ̃n ami vuz ɛt paʁti/","zh":"可我亲爱的朋友，你走时","en":"But my friend you are gone","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-03-011","lineIndex":11,"speaker":"","original":"En laissant ces chandeliers","ipa":"/ɑ̃ lɛsɑ̃ se ʃɑ̃dəlje/","zh":"把这些银烛台忘在了这里","en":"By leaving these candlesticks","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-03-012","lineIndex":12,"speaker":"","original":"Je vous avais pourtant bien dit","ipa":"/ʒə vuz avɛ puʁtɑ̃ bjɛ̃ di/","zh":"我明明告诉过您","en":"However, I told you well","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-03-013","lineIndex":13,"speaker":"","original":"Qu'il fallait les emporter","ipa":"/kil falɛ lez ɑ̃pɔʁte/","zh":"要把它们一并带走","en":"That they had to be taken away","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-03-014","lineIndex":14,"speaker":"","original":"Messieurs, relâchez cet homme!","ipa":"/mesjø ʁəlaʃe sɛt ɔm/","zh":"先生们，释放这个人！","en":"Gentlemen, release this man!","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-03-015","lineIndex":15,"speaker":"","original":"Il a dit la vérité","ipa":"/il a di la veʁite/","zh":"他说的是实话","en":"He told the truth","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-03-016","lineIndex":16,"speaker":"","original":"Retournez servir la justice","ipa":"/ʁətuʁne sɛʁviʁ la ʒystis/","zh":"回去继续履行司法职责","en":"Return to serve justice","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-03-017","lineIndex":17,"speaker":"","original":"Allez, que Dieu vous bénisse","ipa":"/ale kə djø vu benis/","zh":"去吧，愿上帝保佑你","en":"Come on, God bless you","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-03-018","lineIndex":18,"speaker":"","original":"Et toi, Jean Valjean, mon frère","ipa":"/e twa ʒɑ̃ valʒɑ̃ mɔ̃ fʁɛʁ/","zh":"还有你，冉阿让，我的兄弟","en":"And you, Jean Valjean, my brother","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-03-019","lineIndex":19,"speaker":"","original":"Ne désespère plus de lui","ipa":"/nə dezɛspɛʁ ply də lɥi/","zh":"别再对祂绝望","en":"Don't despair of him anymore","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-03-020","lineIndex":20,"speaker":"","original":"Dieu t'envoie ces présents du ciel","ipa":"/djø tɑ̃vwa se pʁezɑ̃ dy sjɛl/","zh":"上帝把这些天赐的礼物送给你","en":"God sends you these gifts from heaven","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-03-021","lineIndex":21,"speaker":"","original":"Recommence une autre vie","ipa":"/ʁəkɔmɑ̃s yn otʁ vi/","zh":"重新开始另一种人生","en":"Start another life","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-03-022","lineIndex":22,"speaker":"","original":"C'est ton âme que j'achète","ipa":"/sɛ tɔ̃n am kə ʒaʃɛt/","zh":"我买的是你的灵魂","en":"It's your soul that I buy","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-03-023","lineIndex":23,"speaker":"","original":"C'est ton âme que je veux","ipa":"/sɛ tɔ̃n am kə ʒə vø/","zh":"我想要的是你的灵魂","en":"It's your soul that I want","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-03-024","lineIndex":24,"speaker":"","original":"Et au nom de tous les saints","ipa":"/e o nɔ̃ də tu le sɛ̃/","zh":"以众圣徒之名","en":"And in the name of all saints","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-03-025","lineIndex":25,"speaker":"","original":"Ce soir je la donne à Dieu","ipa":"/sə swaʁ ʒə la dɔn a djø/","zh":"今夜我把它交还给上帝","en":"Tonight I give it to God","note":"","sourceLineIndex":25}],"sourceOrder":3,"displayOrder":2},{"order":4,"id":"04-pourquoi-ai-je-permis-a-cet-homme","title":"Pourquoi ai-je permis à cet homme?","titleZh":"我为什么允许这个人？","lines":[{"id":"les-miserables-cityprod-2017-04-001","lineIndex":1,"speaker":"","original":"Je ne sais plus.","ipa":"/ʒə nə sɛ ply/","zh":"我不知道了。","en":"I don't know anymore.","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-04-002","lineIndex":2,"speaker":"","original":"Oh mon Dieu, je ne sais plus","ipa":"/ɔ mɔ̃ djø ʒə nə sɛ ply/","zh":"天哪，我不知道了","en":"Oh my God, I don't know anymore","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-04-003","lineIndex":3,"speaker":"","original":"Si on peut encore sauver","ipa":"/si ɔ̃ pøt ɑ̃kɔʁ sove/","zh":"若还能救回","en":"If we can still save","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-04-004","lineIndex":4,"speaker":"","original":"L'homme que je suis devenu.","ipa":"/lɔm kə ʒə sɥi dəvny/","zh":"如今的我。","en":"The man I have become.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-04-005","lineIndex":5,"speaker":"","original":"Est-ce bien cela que je veux?","ipa":"/ɛs bjɛ̃ səla kə ʒə vø/","zh":"这就是我想要的吗？","en":"Is this what I want?","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-04-006","lineIndex":6,"speaker":"","original":"La douceur d'un mot trompeur","ipa":"/la dusœʁ dœ̃ mo tʁɔ̃pœʁ/","zh":"欺人言语里那点温柔","en":"The sweetness of a deceptive word","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-04-007","lineIndex":7,"speaker":"","original":"Ne peut pas tarir le flot brûlant de ma haine.","ipa":"/nə pø pa taʁiʁ lə flo bʁylɑ̃ də ma ɛn/","zh":"也浇不灭我心中炽烈的仇恨。","en":"Cannot dry up the burning flow of my hatred.","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-04-008","lineIndex":8,"speaker":"","original":"Seul dans la nuit","ipa":"/sœl dɑ̃ la nɥi/","zh":"独自一人在夜里","en":"Alone in the night","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-04-009","lineIndex":9,"speaker":"","original":"Je crie pour personne.","ipa":"/ʒə kʁi puʁ pɛʁsɔn/","zh":"我向无人呼喊。","en":"I scream for no one.","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-04-010","lineIndex":10,"speaker":"","original":"Peut-on changer","ipa":"/pøtɔ̃ ʃɑ̃ʒe/","zh":"人真能改变","en":"Can we change","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-04-011","lineIndex":11,"speaker":"","original":"Soudain le destin d'un homme?","ipa":"/sudɛ̃ lə dɛstɛ̃ dœ̃n ɔm/","zh":"一个人注定的命运吗？","en":"Suddenly the destiny of a man?","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-04-012","lineIndex":12,"speaker":"","original":"S'il y a un autre chemin pour moi","ipa":"/sil i a œ̃n otʁ ʃəmɛ̃ puʁ mwa/","zh":"如果我还有别的出路的话","en":"If there is another way for me","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-04-013","lineIndex":13,"speaker":"","original":"Je l'ai manqué, il y a vingt ans déjà.","ipa":"/ʒə le mɑ̃ke il i a vɛ̃t ɑ̃ deʒa/","zh":"二十年前，我就错过了它。","en":"I missed it twenty years ago already.","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-04-014","lineIndex":14,"speaker":"","original":"Ma vie est une vie perdue à la naissance.","ipa":"/ma vi ɛt yn vi pɛʁdy a la nɛsɑ̃s/","zh":"我这一生，从出生起便已失落。","en":"My life is a life lost at birth.","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-04-015","lineIndex":15,"speaker":"","original":"Au premier faux pas, au nom de la justice","ipa":"/o pʁəmje fo pa o nɔ̃ də la ʒystis/","zh":"在第一次失误时，以正义的名义","en":"At the first misstep, in the name of justice","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-04-016","lineIndex":16,"speaker":"","original":"Chaînes aux pieds et menottes à la main","ipa":"/ʃɛnz o pjez e mənɔtz a la mɛ̃/","zh":"脚戴锁链，手戴镣铐","en":"Foot chains and handcuffs","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-04-017","lineIndex":17,"speaker":"","original":"Pour avoir pris un morceau de pain","ipa":"/puʁ avwaʁ pʁi œ̃ mɔʁso də pɛ̃/","zh":"因为拿了一块面包","en":"For having taken a piece of bread","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-04-018","lineIndex":18,"speaker":"","original":"Pourquoi ai-je permis à cet homme","ipa":"/puʁkwa ɛʒ pɛʁmi a sɛt ɔm/","zh":"为什么我允许这个男人","en":"Why did I allow this man","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-04-019","lineIndex":19,"speaker":"","original":"De me toucher de sa bonté?","ipa":"/də mə tuʃe də sa bɔ̃te/","zh":"用他的善良感动我？","en":"To touch me with his kindness?","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-04-020","lineIndex":20,"speaker":"","original":"Il m'a nourri, il m'a réchauffé;","ipa":"/il ma nuʁi il ma ʁeʃofe/","zh":"他给我食物，又为我取暖；","en":"He fed me, he warmed me;","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-04-021","lineIndex":21,"speaker":"","original":"Sa miséricorde","ipa":"/sa mizeʁikɔʁd/","zh":"这份怜悯","en":"His mercy","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-04-022","lineIndex":22,"speaker":"","original":"Est trop lourde à porter.","ipa":"/ɛ tʁo luʁd a pɔʁte/","zh":"重得令我难以承受。","en":"Is too heavy to carry.","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-04-023","lineIndex":23,"speaker":"","original":"Il dit que j'appartiens à Dieu.","ipa":"/il di kə ʒapaʁtjɛ̃z a djø/","zh":"他说我属于上帝。","en":"He says I belong to God.","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-04-024","lineIndex":24,"speaker":"","original":"Qu'est-ce qu'il en sait?","ipa":"/kɛs kil ɑ̃ sɛ/","zh":"他对此了解多少？","en":"What does he know about it?","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-04-025","lineIndex":25,"speaker":"","original":"Moi je veux faire payer aux hommes","ipa":"/mwa ʒə vø fɛʁ pɛje oz ɔm/","zh":"我想让男人付出代价","en":"I want to make men pay","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-04-026","lineIndex":26,"speaker":"","original":"Le prix d'une vie qu'ils m'ont volée","ipa":"/lə pʁi dyn vi kil mɔ̃ vole/","zh":"他们从我身上偷走了一条生命的代价","en":"The price of a life they stole from me","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-04-027","lineIndex":27,"speaker":"","original":"J'ai nourri ma vengeance","ipa":"/ʒe nuʁi ma vɑ̃ʒɑ̃s/","zh":"我酝酿着复仇","en":"I nursed my revenge","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-04-028","lineIndex":28,"speaker":"","original":"À de maigres repas.","ipa":"/a də mɛɡʁ ʁəpa/","zh":"靠着微薄的饭食。","en":"At meager meals.","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-04-029","lineIndex":29,"speaker":"","original":"J'ai bâti une muraille","ipa":"/ʒe bati yn myʁaj/","zh":"我建了一堵墙","en":"I built a wall","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-04-030","lineIndex":30,"speaker":"","original":"Entre le monde et moi.","ipa":"/ɑ̃tʁ lə mɔ̃d e mwa/","zh":"世界与我之间。","en":"Between the world and me.","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-04-031","lineIndex":31,"speaker":"","original":"Il aurait pu me dénoncer","ipa":"/il oʁɛ py mə denɔ̃se/","zh":"他本可以谴责我","en":"He could have denounced me","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-04-032","lineIndex":32,"speaker":"","original":"Me rendre au bagne et au fouet.","ipa":"/mə ʁɑ̃dʁ o baɲ e o fwɛ/","zh":"把我送回苦役营，交给鞭子。","en":"Go to the prison and the whip.","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-04-033","lineIndex":33,"speaker":"","original":"Mais il préfère que je sois libre","ipa":"/mɛz il pʁefɛʁ kə ʒə swa libʁ/","zh":"但他更喜欢我自由","en":"But he prefers me to be free","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-04-034","lineIndex":34,"speaker":"","original":"Pour laisser le doute s'insinuer en moi.","ipa":"/puʁ lɛse lə dut sɛ̃sinye ɑ̃ mwa/","zh":"让怀疑潜入我的内心。","en":"To let doubt creep into me.","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-04-035","lineIndex":35,"speaker":"","original":"Il m'a dit que j'avais une âme","ipa":"/il ma di kə ʒavɛz yn am/","zh":"他告诉我我有灵魂","en":"He told me I had a soul","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-04-036","lineIndex":36,"speaker":"","original":"Qu'est ce qu'il en sait?","ipa":"/kɛ sə kil ɑ̃ sɛ/","zh":"他对此了解多少？","en":"What does he know about it?","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-04-037","lineIndex":37,"speaker":"","original":"Mais je sens fondre le mur de glace","ipa":"/mɛ ʒə sɑ̃ fɔ̃dʁ lə myʁ də ɡlas/","zh":"但我感觉到冰墙正在融化","en":"But I feel the wall of ice melting","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-04-038","lineIndex":38,"speaker":"","original":"Mon cœur bat sous la carapace","ipa":"/mɔ̃ kœʁ ba su la kaʁapas/","zh":"我的心在硬壳之下跳动","en":"My heart beats under the shell","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-04-039","lineIndex":39,"speaker":"","original":"Toutes mes certitudes s'effondrent;","ipa":"/tut me sɛʁtityd sefɔ̃dʁ/","zh":"我所有的确定性都崩溃了；","en":"All my certainties collapse;","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-04-040","lineIndex":40,"speaker":"","original":"Et je pleure comme la terre tremble.","ipa":"/e ʒə plœʁ kɔm la tɛʁ tʁɑ̃bl/","zh":"我哭泣，如同大地震颤。","en":"And I cry like the earth shakes.","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-04-041","lineIndex":41,"speaker":"","original":"Je regarde dans le vide","ipa":"/ʒə ʁəɡaʁd dɑ̃ lə vid/","zh":"我凝视太空","en":"I stare into space","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-04-042","lineIndex":42,"speaker":"","original":"Un autre homme qui me ressemble.","ipa":"/œ̃n otʁ ɔm ki mə ʁəsɑ̃bl/","zh":"又一个和我长得很像的男人。","en":"Another man who looks like me.","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-04-043","lineIndex":43,"speaker":"","original":"Je vais épargner au monde","ipa":"/ʒə vɛz epaʁnje o mɔ̃d/","zh":"我要让这世界免受","en":"I will save the world","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-04-044","lineIndex":44,"speaker":"","original":"La colère de Jean Valjean.","ipa":"/la kolɛʁ də ʒɑ̃ valʒɑ̃/","zh":"冉阿让的愤怒。","en":"The anger of Jean Valjean.","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-04-045","lineIndex":45,"speaker":"","original":"Jean Valjean est mort ce soir;","ipa":"/ʒɑ̃ valʒɑ̃ ɛ mɔʁ sə swaʁ/","zh":"冉阿让今晚去世了；","en":"Jean Valjean died this evening;","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-04-046","lineIndex":46,"speaker":"","original":"Ici commence une autre histoire.","ipa":"/isi kɔmɑ̃s yn otʁ istwaʁ/","zh":"这里开始另一个故事。","en":"Here begins another story.","note":"","sourceLineIndex":46}],"sourceOrder":4,"displayOrder":3},{"order":5,"id":"05-quand-un-jour-est-passe","title":"Quand un jour est passé","titleZh":"一天过去了","lines":[{"id":"les-miserables-cityprod-2017-05-001","lineIndex":1,"speaker":"","original":"Quand un jour est passé, il est passé pour rien.","ipa":"/kɑ̃t œ̃ ʒuʁ ɛ pase il ɛ pase puʁ ʁiɛ̃/","zh":"一天过去了，就已经毫无意义了。","en":"When a day has passed, it has passed for nothing.","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-05-002","lineIndex":2,"speaker":"","original":"L'homme est aveugle et sourd aux peines de son prochain.","ipa":"/lɔm ɛt avøɡl e suʁ o pɛn də sɔ̃ pʁoʃɛ̃/","zh":"人对于邻居的悲伤是盲目的和充耳不闻的。","en":"Man is blind and deaf to the sorrows of his neighbor.","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-05-003","lineIndex":3,"speaker":"","original":"Nous les pauvres, on sait d'avance","ipa":"/nu le povʁ ɔ̃ sɛ davɑ̃s/","zh":"我们穷人提前知道","en":"We poor people know in advance","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-05-004","lineIndex":4,"speaker":"","original":"Que demain et les jours qui vont suivre","ipa":"/kə dəmɛ̃ e le ʒuʁ ki vɔ̃ sɥivʁ/","zh":"明天以及接下来的日子","en":"That tomorrow and the days that follow","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-05-005","lineIndex":5,"speaker":"","original":"Il n'y aura jamais pour nous qu'une différence:","ipa":"/il ni oʁa ʒamɛ puʁ nu kyn difeʁɑ̃s/","zh":"对我们来说只有一处不同：","en":"There will only ever be one difference for us:","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-05-006","lineIndex":6,"speaker":"","original":"Un jour de moins à vivre!","ipa":"/œ̃ ʒuʁ də mwɛ̃z a vivʁ/","zh":"少活一天！","en":"One less day to live!","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-05-007","lineIndex":7,"speaker":"","original":"Quand un jour est passé, il est passé sans joie.","ipa":"/kɑ̃t œ̃ ʒuʁ ɛ pase il ɛ pase sɑ̃ ʒwa/","zh":"一天过去了，日子过得毫无欢乐。","en":"When a day has passed, it has passed without joy.","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-05-008","lineIndex":8,"speaker":"","original":"Il faut s'en retourner sous la pluie, dans le froid","ipa":"/il fo sɑ̃ ʁətuʁne su la plɥi dɑ̃ lə fʁwa/","zh":"你必须顶着雨、顶着严寒回去","en":"You have to go back in the rain, in the cold","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-05-009","lineIndex":9,"speaker":"","original":"Implorer le bourgeois qui t'ignore","ipa":"/ɛ̃ploʁe lə buʁʒwa ki tinjɔʁ/","zh":"恳求那些无视你的资产阶级","en":"Implore the bourgeois who ignores you","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-05-010","lineIndex":10,"speaker":"","original":"Bien calfeutré dans son opulence","ipa":"/bjɛ̃ kalføtʁe dɑ̃ sɔ̃n opylɑ̃s/","zh":"密封在其富裕之中","en":"Well sealed in its opulence","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-05-011","lineIndex":11,"speaker":"","original":"Et qui te jette une pièce et qui s'endort","ipa":"/e ki tə ʒɛt yn pjɛs e ki sɑ̃dɔʁ/","zh":"谁扔给你一枚硬币然后就睡着了","en":"And who tosses you a coin and falls asleep","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-05-012","lineIndex":12,"speaker":"","original":"En ayant bonne conscience!","ipa":"/ɑ̃n ɛjɑ̃ bɔn kɔ̃sjɑ̃s/","zh":"问心无愧！","en":"With a clear conscience!","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-05-013","lineIndex":13,"speaker":"","original":"Quand un jour est passé, un autre jour se lève.","ipa":"/kɑ̃t œ̃ ʒuʁ ɛ pase œ̃n otʁ ʒuʁ sə lɛv/","zh":"当一天过去后，另一天即将来临。","en":"When one day has passed, another day dawns.","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-05-014","lineIndex":14,"speaker":"","original":"Il faudra bien qu'un jour, le malheur se mette en grève;","ipa":"/il fodʁa bjɛ̃ kœ̃ ʒuʁ lə malœʁ sə mɛt ɑ̃ ɡʁɛv/","zh":"有一天，不幸将要罢工；","en":"One day, misfortune will have to go on strike;","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-05-015","lineIndex":15,"speaker":"","original":"Et qu'un ouragan éclate; et qu'il vienne enfin secouer le monde","ipa":"/e kœ̃n uʁaɡɑ̃ eklat e kil vjɛn ɑ̃fɛ̃ səkwe lə mɔ̃d/","zh":"飓风爆发；他终于来震撼世界了","en":"And a hurricane breaks out; and he finally comes to shake the world","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-05-016","lineIndex":16,"speaker":"","original":"Pour nourrir de sa colère ceux qui ont tant d'arriérés de misère","ipa":"/puʁ nuʁiʁ də sa kolɛʁ sø ki ɔ̃ tɑ̃ daʁjeʁe də mizɛʁ/","zh":"用他的愤怒来养活那些欠下如此多贫困的人","en":"To feed with his anger those who have so much arrears of poverty","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-05-017","lineIndex":17,"speaker":"","original":"Ceux qui n'ont jamais eu leur part","ipa":"/sø ki nɔ̃ ʒamɛz y lœʁ paʁ/","zh":"那些从未拥有过自己份额的人","en":"Those who never had their share","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-05-018","lineIndex":18,"speaker":"","original":"De bonheur en retard.","ipa":"/də bɔnœʁ ɑ̃ ʁətaʁ/","zh":"迟来的幸福。","en":"Late happiness.","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-05-019","lineIndex":19,"speaker":"","original":"Quand un jour est passé, on a que ce qu'on mérite;","ipa":"/kɑ̃t œ̃ ʒuʁ ɛ pase ɔ̃n a kə sə kɔ̃ meʁit/","zh":"一天过去了，我们只得到了我们应得的；","en":"When a day has passed, we only get what we deserve;","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-05-020","lineIndex":20,"speaker":"","original":"Les feignants auront rien à mettre dans la marmite.","ipa":"/le fɛnjɑ̃z oʁɔ̃ ʁjɛ̃n a mɛtʁ dɑ̃ la maʁmit/","zh":"懒惰的人就没有东西可以放进锅里。","en":"The lazy ones will have nothing to put in the pot.","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-05-021","lineIndex":21,"speaker":"","original":"Il faut nourrir les marmots","ipa":"/il fo nuʁiʁ le maʁmo/","zh":"你必须养活孩子","en":"You have to feed the kids","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-05-022","lineIndex":22,"speaker":"","original":"Qu'on a faits sans toujours les vouloir.","ipa":"/kɔ̃n a fɛ sɑ̃ tuʒuʁ le vulwaʁ/","zh":"我们这样做并不总是想要它们。","en":"That we did without always wanting them.","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-05-023","lineIndex":23,"speaker":"","original":"Mais ça va tant qu'on a un boulot","ipa":"/mɛ sa va tɑ̃ kɔ̃n a œ̃ bulo/","zh":"不过只要有工作就好了","en":"But it's okay as long as we have a job","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-05-024","lineIndex":24,"speaker":"","original":"Un coup à boire!","ipa":"/œ̃ ku a bwaʁ/","zh":"喝一杯！","en":"A drink!","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-05-025","lineIndex":25,"speaker":"","original":"Nous on a cette chance!","ipa":"/nuz ɔ̃n a sɛt ʃɑ̃s/","zh":"我们有这个机会！","en":"We have this chance!","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-05-026","lineIndex":26,"speaker":"","original":"As-tu vu la sale gueule que tire le contremaître?","ipa":"/aty vy la sal ɡœl kə tiʁ lə kɔ̃tʁəmɛtʁ/","zh":"你看工头那副难看的嘴脸了吗？","en":"Did you see the dirty face the foreman pulls?","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-05-027","lineIndex":27,"speaker":"","original":"Et ses mains baladeuses qui vous collent comme la poisse?","ipa":"/e se mɛ̃ baladøz ki vu kɔl kɔm la pwas/","zh":"还有他那双到处乱摸、黏着人不放的手？","en":"And his wandering hands that stick to you like bad luck?","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-05-028","lineIndex":28,"speaker":"","original":"C'est la faute à Fantine qui veut rien lui permettre.","ipa":"/sɛ la fot a fɑ̃tin ki vø ʁjɛ̃ lɥi pɛʁmɛtʁ/","zh":"都怪芳汀，什么都不肯让他得逞。","en":"It's Fantine's fault who doesn't want to allow him anything.","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-05-029","lineIndex":29,"speaker":"","original":"Ben, que ça lui plaise ou pas, va falloir qu'elle y passe!","ipa":"/bɛn kə sa lɥi plɛz u pa va falwaʁ kɛl i pas/","zh":"哼，不管她愿不愿意，她早晚得遭这一回！","en":"Well, whether she likes it or not, she's going to have to do it!","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-05-030","lineIndex":30,"speaker":"","original":"Le patron, lui, ne sait pas que son chiourme est toujours en chaleur.","ipa":"/lə patʁɔ̃ lɥi nə sɛ pa kə sɔ̃ ʃjuʁm ɛ tuʒuʁz ɑ̃ ʃalœʁ/","zh":"老板可不知道，他的监工满脑子都是这种念头。","en":"The boss doesn't know that his foreman is still in heat.","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-05-031","lineIndex":31,"speaker":"","original":"Si Fantine ne fait pas gaffe, y aura pas long","ipa":"/si fɑ̃tin nə fɛ pa ɡaf i oʁa pa lɔ̃/","zh":"要是芳汀不当心，用不了多久","en":"If Fantine doesn't watch out, it won't be long","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-05-032","lineIndex":32,"speaker":"","original":"Qu'il lui arrive un malheur.","ipa":"/kil lɥi aʁiv œ̃ malœʁ/","zh":"她就要遭殃。","en":"Let something bad happen to her.","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-05-033","lineIndex":33,"speaker":"","original":"Quand un jour est passé, on est plus vieux d'un jour.","ipa":"/kɑ̃t œ̃ ʒuʁ ɛ pase ɔ̃n ɛ ply vjø dœ̃ ʒuʁ/","zh":"一天过去了，你又老了一天。","en":"When a day has passed, you are a day older.","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-05-034","lineIndex":34,"speaker":"","original":"Et on gagne juste assez pour pas crier au secours.","ipa":"/e ɔ̃ ɡaɲ ʒyst ase puʁ pa kʁie o səkuʁ/","zh":"我们的收入刚好够不至于呼救。","en":"And we earn just enough not to cry for help.","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-05-035","lineIndex":35,"speaker":"","original":"Avant la soupe et le vin","ipa":"/avɑ̃ la sup e lə vɛ̃/","zh":"在汤和酒之前","en":"Before the soup and the wine","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-05-036","lineIndex":36,"speaker":"","original":"Il faut payer le propriétaire","ipa":"/il fo pɛje lə pʁɔpʁietɛʁ/","zh":"你必须付钱给主人","en":"You have to pay the owner","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-05-037","lineIndex":37,"speaker":"","original":"Et gratter jusqu'à la fin","ipa":"/e ɡʁate ʒyska la fɛ̃/","zh":"并从头开始直到最后","en":"And scratch until the end","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-05-038","lineIndex":38,"speaker":"","original":"Chaque miette de chaque sou d'un salaire","ipa":"/ʃak mjɛt də ʃak su dœ̃ salɛʁ/","zh":"每一分钱的薪水","en":"Every crumb of every penny of a salary","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-05-039","lineIndex":39,"speaker":"","original":"Dont il ne va rien à rester","ipa":"/dɔ̃t il nə va ʁjɛ̃n a ʁɛste/","zh":"其中将一无所有","en":"Of which there will be nothing left","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-05-040","lineIndex":40,"speaker":"","original":"Quand un jour est passé.","ipa":"/kɑ̃t œ̃ ʒuʁ ɛ pase/","zh":"当一天过去了。","en":"When a day has passed.","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-05-041","lineIndex":41,"speaker":"","original":"Qu'est-ce que tu caches, ma jolie, de la sorte?","ipa":"/kɛskə ty kaʃ ma ʒoli də la sɔʁt/","zh":"亲爱的，你到底想隐藏什么？","en":"What are you hiding, my dear, like that?","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-05-042","lineIndex":42,"speaker":"","original":"Alors, Fantine, quelles sont les nouvelles?","ipa":"/alɔʁ fɑ̃tin kɛl sɔ̃ le nuvɛl/","zh":"那么，芳汀，有什么消息吗？","en":"So, Fantine, what's the news?","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-05-043","lineIndex":43,"speaker":"","original":"Oh!.. Chère Fantine, Cosette est très malade;","ipa":"/ɔ ʃɛʁ fɑ̃tin kozɛt ɛ tʁɛ malad/","zh":"噢！……亲爱的芳汀，珂赛特病得很重；","en":"Oh!.. Dear Fantine, Cosette is very ill;","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-05-044","lineIndex":44,"speaker":"","original":"Envoyez quarante francs ou la petite est morte!","ipa":"/ɑ̃vwaje kaʁɑ̃t fʁɑ̃ u la pətit ɛ mɔʁt/","zh":"寄四十法郎，不然小家伙就死了！","en":"Send forty francs or the little one is dead!","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-05-045","lineIndex":45,"speaker":"","original":"Rends-moi ma lettre, mêle-toi de tes affaires.","ipa":"/ʁɑ̃mwa ma lɛtʁ mɛltwa də tez afɛʁ/","zh":"把信还给我，管好你自己的事吧。","en":"Give me back my letter, mind your own business.","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-05-046","lineIndex":46,"speaker":"","original":"Toi qui as un mari qui ne te suffit plus.","ipa":"/twa ki az œ̃ maʁi ki nə tə syfi ply/","zh":"你的丈夫已经不能满足你的需要了。","en":"You who have a husband who is no longer enough for you.","note":"","sourceLineIndex":46},{"id":"les-miserables-cityprod-2017-05-047","lineIndex":47,"speaker":"","original":"Occupe-toi de ta vie et laisse-moi la mienne.","ipa":"/ɔkyptwa də ta vi e lɛsmwa la mjɛn/","zh":"照顾好你的生活，把我的生活留给我。","en":"Take care of your life and leave mine to me.","note":"","sourceLineIndex":47},{"id":"les-miserables-cityprod-2017-05-048","lineIndex":48,"speaker":"","original":"Qui êtes-vous pour me faire des leçons de vertu?","ipa":"/ki ɛtvu puʁ mə fɛʁ de ləsɔ̃ də vɛʁty/","zh":"你是谁，竟敢给我上道德课？","en":"Who are you to give me lessons in virtue?","note":"","sourceLineIndex":48},{"id":"les-miserables-cityprod-2017-05-049","lineIndex":49,"speaker":"","original":"Séparez-les, je vous l'ordonne","ipa":"/sepaʁele ʒə vu lɔʁdɔn/","zh":"把他们分开，我命令你","en":"Separate them, I command you","note":"","sourceLineIndex":49},{"id":"les-miserables-cityprod-2017-05-050","lineIndex":50,"speaker":"","original":"Je ne conduis pas un troupeau","ipa":"/ʒə nə kɔ̃dɥi paz œ̃ tʁupo/","zh":"我不带领羊群","en":"I don't lead a herd","note":"","sourceLineIndex":50},{"id":"les-miserables-cityprod-2017-05-051","lineIndex":51,"speaker":"","original":"C'est une usine que je mène.","ipa":"/sɛt yn yzin kə ʒə mɛn/","zh":"这是我经营的工厂。","en":"It's a factory that I run.","note":"","sourceLineIndex":51},{"id":"les-miserables-cityprod-2017-05-052","lineIndex":52,"speaker":"","original":"Allons, mesdames, reprenez-vous;","ipa":"/alɔ̃ medam ʁəpʁənevu/","zh":"来吧，女士们，振作起来；","en":"Come on, ladies, pull yourself together;","note":"","sourceLineIndex":52},{"id":"les-miserables-cityprod-2017-05-053","lineIndex":53,"speaker":"","original":"Je suis le maire de cette ville","ipa":"/ʒə sɥi lə mɛʁ də sɛt vil/","zh":"我是这个城市的市长","en":"I am the mayor of this city","note":"","sourceLineIndex":53},{"id":"les-miserables-cityprod-2017-05-054","lineIndex":54,"speaker":"","original":"Je ne tolère pas ces querelles;","ipa":"/ʒə nə tolɛʁ pa se kʁɛl/","zh":"我不能容忍这些争吵；","en":"I do not tolerate these quarrels;","note":"","sourceLineIndex":54},{"id":"les-miserables-cityprod-2017-05-055","lineIndex":55,"speaker":"","original":"Je vous charge de ramener l'ordre;","ipa":"/ʒə vu ʃaʁʒ də ʁamne lɔʁdʁ/","zh":"我责成你恢复秩序；","en":"I charge you to restore order;","note":"","sourceLineIndex":55},{"id":"les-miserables-cityprod-2017-05-056","lineIndex":56,"speaker":"","original":"Et que chacun fasse son travail!","ipa":"/e kə ʃakœ̃ fas sɔ̃ tʁavaj/","zh":"并让每个人都做好自己的工作！","en":"And let everyone do their job!","note":"","sourceLineIndex":56},{"id":"les-miserables-cityprod-2017-05-057","lineIndex":57,"speaker":"","original":"Qui a déclenché cette pagaille?","ipa":"/ki a deklɑ̃ʃe sɛt paɡaj/","zh":"是谁引发了这场混乱？","en":"Who started this mess?","note":"","sourceLineIndex":57},{"id":"les-miserables-cityprod-2017-05-058","lineIndex":58,"speaker":"","original":"Moi je n'y suis pour rien, tout ça c'est bien sa faute.","ipa":"/mwa ʒə ni sɥi puʁ ʁiɛ̃ tu sa sɛ bjɛ̃ sa fot/","zh":"我与这件事无关，都是他的错。","en":"I have nothing to do with it, it's all his fault.","note":"","sourceLineIndex":58},{"id":"les-miserables-cityprod-2017-05-059","lineIndex":59,"speaker":"","original":"Elle a une gosse qu'elle cache, on imagine pourquoi.","ipa":"/ɛl a yn ɡɔs kɛl kaʃ ɔ̃n imaʒin puʁkwa/","zh":"她有一个孩子，她藏着，我们可以想象为什么。","en":"She has a child that she is hiding, we can imagine why.","note":"","sourceLineIndex":59},{"id":"les-miserables-cityprod-2017-05-060","lineIndex":60,"speaker":"","original":"Y a un homme qu'elle doit payer. Et on devine comment elle s'y prend","ipa":"/i a œ̃n ɔm kɛl dwa pɛje e ɔ̃ dəvin kɔmɑ̃ ɛl si pʁɑ̃/","zh":"她必须付钱给一个男人。我们可以猜测她是怎么做到的","en":"There's a man she has to pay. And we can guess how she does it","note":"","sourceLineIndex":60},{"id":"les-miserables-cityprod-2017-05-061","lineIndex":61,"speaker":"","original":"Pour se faire, n'est-ce pas ma poule! Des suppléments.","ipa":"/puʁ sə fɛʁ nɛs pa ma pul de syplemɑ̃/","zh":"靠什么挣的，亲爱的？靠“额外收入”呗。","en":"To do so, isn’t that my hen! Supplements.","note":"","sourceLineIndex":61},{"id":"les-miserables-cityprod-2017-05-062","lineIndex":62,"speaker":"","original":"Monsieur le maire appréciera!","ipa":"/məsjø lə mɛʁ apʁesiʁa/","zh":"市长一定会感激的！","en":"The mayor will appreciate it!","note":"","sourceLineIndex":62},{"id":"les-miserables-cityprod-2017-05-063","lineIndex":63,"speaker":"","original":"Oui c'est vrai, j'ai une fille qui n'a que moi sur terre;","ipa":"/wi sɛ vʁɛ ʒe yn fij ki na kə mwa syʁ tɛʁ/","zh":"是的，我有个女儿；在这世上，她只有我。","en":"Yes it's true, I have a daughter who only has me on earth;","note":"","sourceLineIndex":63},{"id":"les-miserables-cityprod-2017-05-064","lineIndex":64,"speaker":"","original":"Je l'ai donnée en garde pour pouvoir me placer.","ipa":"/ʒə le dɔne ɑ̃ ɡaʁd puʁ puvwaʁ mə plase/","zh":"为了找份安身的工作，我只好把她托人照看。","en":"I gave her custody so I could get a seat.","note":"","sourceLineIndex":64},{"id":"les-miserables-cityprod-2017-05-065","lineIndex":65,"speaker":"","original":"J'envoie tout ce que je gagne pour élever ma Cosette.","ipa":"/ʒɑ̃vwa tu sə kə ʒə ɡaɲ puʁ elve ma kozɛt/","zh":"我把赚到的一切都用来抚养我的珂赛特。","en":"I send everything I earn to raise my Cosette.","note":"","sourceLineIndex":65},{"id":"les-miserables-cityprod-2017-05-066","lineIndex":66,"speaker":"","original":"Je suis une femme honnête, monsieur, vous comprenez!","ipa":"/ʒə sɥiz yn fam ɔnɛt məsjø vu kɔ̃pʁəne/","zh":"我是一个诚实的女人，先生，您懂的！","en":"I am an honest woman, sir, you understand!","note":"","sourceLineIndex":66},{"id":"les-miserables-cityprod-2017-05-067","lineIndex":67,"speaker":"","original":"Quand un jour est passé, on n'a que ce qu'on sème;","ipa":"/kɑ̃t œ̃ ʒuʁ ɛ pase ɔ̃ na kə sə kɔ̃ sɛm/","zh":"一天过去了，我们只剩下自己所种的；","en":"When a day has passed, we only have what we sow;","note":"","sourceLineIndex":67},{"id":"les-miserables-cityprod-2017-05-068","lineIndex":68,"speaker":"","original":"Et la brebis galeuse contamine le troupeau.","ipa":"/e la bʁəbi ɡaløz kɔ̃tamin lə tʁupo/","zh":"害群之马污染了羊群。","en":"And the black sheep contaminates the flock.","note":"","sourceLineIndex":68},{"id":"les-miserables-cityprod-2017-05-069","lineIndex":69,"speaker":"","original":"Pendant qu'on trime pour gagner notre pain","ipa":"/pɑ̃dɑ̃ kɔ̃ tʁim puʁ ɡanje notʁ pɛ̃/","zh":"当我们努力挣钱养家糊口时","en":"While we toil to earn our bread","note":"","sourceLineIndex":69},{"id":"les-miserables-cityprod-2017-05-070","lineIndex":70,"speaker":"","original":"Elle se roule dans les lits des palaces;","ipa":"/ɛl sə ʁul dɑ̃ le li de palas/","zh":"她在宫殿的床上打滚；","en":"She rolls around in the beds of palaces;","note":"","sourceLineIndex":70},{"id":"les-miserables-cityprod-2017-05-071","lineIndex":71,"speaker":"","original":"Il faut chasser cette catin","ipa":"/il fo ʃase sɛt katɛ̃/","zh":"我们得把这个妓女赶走","en":"We have to chase this whore away","note":"","sourceLineIndex":71},{"id":"les-miserables-cityprod-2017-05-072","lineIndex":72,"speaker":"","original":"Ou c'est nous qui perdrons notre place.","ipa":"/u sɛ nu ki pɛʁdʁɔ̃ notʁ plas/","zh":"否则我们就会失去我们的位置。","en":"Or we will be the ones to lose our place.","note":"","sourceLineIndex":72},{"id":"les-miserables-cityprod-2017-05-073","lineIndex":73,"speaker":"","original":"C'est nous qu'on fera payer","ipa":"/sɛ nu kɔ̃ fəʁa pɛje/","zh":"我们将成为付出代价的人","en":"We will be the ones to pay","note":"","sourceLineIndex":73},{"id":"les-miserables-cityprod-2017-05-074","lineIndex":74,"speaker":"","original":"À la fin de la journée","ipa":"/a la fɛ̃ də la ʒuʁne/","zh":"一天结束时","en":"At the end of the day","note":"","sourceLineIndex":74},{"id":"les-miserables-cityprod-2017-05-075","lineIndex":75,"speaker":"","original":"J'aurais dû voir ta vraie nature","ipa":"/ʒoʁɛ dy vwaʁ ta vʁɛ natyʁ/","zh":"我应该看清你的真实本性","en":"I should have seen your true nature","note":"","sourceLineIndex":75},{"id":"les-miserables-cityprod-2017-05-076","lineIndex":76,"speaker":"","original":"La chienne derrière la jeune fille pure","ipa":"/la ʃjɛn dɛʁjɛʁ la ʒøn fij pyʁ/","zh":"那清纯少女外表下的“贱女人”","en":"The bitch behind the pure young girl","note":"","sourceLineIndex":76},{"id":"les-miserables-cityprod-2017-05-077","lineIndex":77,"speaker":"","original":"Bien trop sérieuse pour être honnête.","ipa":"/bjɛ̃ tʁo seʁjøz puʁ ɛtʁ ɔnɛt/","zh":"装得太正经，反倒不像老实人。","en":"Much too serious to be honest.","note":"","sourceLineIndex":77},{"id":"les-miserables-cityprod-2017-05-078","lineIndex":78,"speaker":"","original":"Voilà la vertueuse Fantine","ipa":"/vwala la vɛʁtyøz fɑ̃tin/","zh":"瞧瞧这位“贞洁”的芳汀","en":"Here is the virtuous Fantine","note":"","sourceLineIndex":78},{"id":"les-miserables-cityprod-2017-05-079","lineIndex":79,"speaker":"","original":"La sainte nitouche de cette usine;","ipa":"/la sɛ̃t nituʃ də sɛt yzin/","zh":"这家工厂里的“圣女”啊。","en":"The holy shit of this factory;","note":"","sourceLineIndex":79},{"id":"les-miserables-cityprod-2017-05-080","lineIndex":80,"speaker":"","original":"Pendant que tu bradais tes charmes","ipa":"/pɑ̃dɑ̃ kə ty bʁadɛ te ʃaʁm/","zh":"当你出卖自己的魅力时","en":"While you were selling off your charms","note":"","sourceLineIndex":80},{"id":"les-miserables-cityprod-2017-05-081","lineIndex":81,"speaker":"","original":"Tu m'achetais avec tes larmes.","ipa":"/ty maʃtɛ avɛk te laʁm/","zh":"你用泪水买下了我。","en":"You bought me with your tears.","note":"","sourceLineIndex":81},{"id":"les-miserables-cityprod-2017-05-082","lineIndex":82,"speaker":"","original":"Tu joues les pucelles en plein jour","ipa":"/ty ʒw le pysɛlz ɑ̃ plɛ̃ ʒuʁ/","zh":"你光天化日之下扮处女","en":"You play the virgin in broad daylight","note":"","sourceLineIndex":82},{"id":"les-miserables-cityprod-2017-05-083","lineIndex":83,"speaker":"","original":"Et la nuit tu vends de l'amour","ipa":"/e la nɥi ty vɑ̃ də lamuʁ/","zh":"晚上你出卖爱情","en":"And at night you sell love","note":"","sourceLineIndex":83},{"id":"les-miserables-cityprod-2017-05-084","lineIndex":84,"speaker":"","original":"Si t'y es pas passé, t'es bien le seul en ville!","ipa":"/si ti ɛ pa pase tɛ bjɛ̃ lə sœl ɑ̃ vil/","zh":"如果您没有去过那里，那么您可能是镇上唯一的人！","en":"If you haven't been there, you're probably the only one in town!","note":"","sourceLineIndex":84},{"id":"les-miserables-cityprod-2017-05-085","lineIndex":85,"speaker":"","original":"Fais-les lui ravaler! Ses larmes de crocodile","ipa":"/fɛle lɥi ʁavale se laʁm də kʁokodil/","zh":"让他吞掉它们！她的鳄鱼眼泪","en":"Make him swallow them! Her crocodile tears","note":"","sourceLineIndex":85},{"id":"les-miserables-cityprod-2017-05-086","lineIndex":86,"speaker":"","original":"Débarrasse-nous d'elle","ipa":"/debaʁasnu dɛl/","zh":"摆脱她","en":"Get rid of her","note":"","sourceLineIndex":86},{"id":"les-miserables-cityprod-2017-05-087","lineIndex":87,"speaker":"","original":"Débarrasse-nous d'elle!","ipa":"/debaʁasnu dɛl/","zh":"摆脱她！","en":"Get rid of her!","note":"","sourceLineIndex":87},{"id":"les-miserables-cityprod-2017-05-088","lineIndex":88,"speaker":"","original":"Non, ma belle, c'est fini!","ipa":"/nɔ̃ ma bɛl sɛ fini/","zh":"不，亲爱的，一切都结束了！","en":"No, my dear, it's over!","note":"","sourceLineIndex":88}],"sourceOrder":5,"displayOrder":4},{"order":6,"id":"06-j-avais-reve","title":"J'avais rêvé","titleZh":"我梦见了","lines":[{"id":"les-miserables-cityprod-2017-06-001","lineIndex":1,"speaker":"","original":"Doux Seigneur","ipa":"/du sɛnjœʁ/","zh":"慈悲的主啊","en":"Sweet Lord","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-06-002","lineIndex":2,"speaker":"","original":"Que vous ai-je fait","ipa":"/kə vuz ɛʒ fɛ/","zh":"我究竟做错了什么","en":"What have I done to you","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-06-003","lineIndex":3,"speaker":"","original":"Pour que plus je tombe","ipa":"/puʁ kə ply ʒə tɔ̃b/","zh":"才会让我越是跌倒","en":"So that the more I fall","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-06-004","lineIndex":4,"speaker":"","original":"Et plus vous me laissiez tomber?","ipa":"/e ply vu mə lɛsje tɔ̃be/","zh":"您便越将我弃之不顾？","en":"And the more you let me fall?","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-06-006","lineIndex":5,"speaker":"","original":"J'avais rêvé d'un cœur si grand","ipa":"/ʒavɛ ʁɛve dœ̃ kœʁ si ɡʁɑ̃/","zh":"我曾梦见一颗如此宽广的心","en":"I had dreamed of a heart so big","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-06-007","lineIndex":6,"speaker":"","original":"Que le mien y trouve place","ipa":"/kə lə mjɛ̃ i tʁuv plas/","zh":"能容下我的心","en":"May mine find a place there","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-06-008","lineIndex":7,"speaker":"","original":"Pour un bonheur à partager.","ipa":"/puʁ œ̃ bɔnœʁ a paʁtaʒe/","zh":"共同分享幸福。","en":"For a happiness to share.","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-06-009","lineIndex":8,"speaker":"","original":"Doux Seigneur","ipa":"/du sɛnjœʁ/","zh":"亲爱的主","en":"Sweet Lord","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-06-010","lineIndex":9,"speaker":"","original":"Que vous ai-je fait?","ipa":"/kə vuz ɛʒ fɛ/","zh":"我对你做了什么？","en":"What have I done to you?","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-06-011","lineIndex":10,"speaker":"","original":"J'avais rêvé d'une autre vie","ipa":"/ʒavɛ ʁɛve dyn otʁ vi/","zh":"我梦想着另一种生活","en":"I dreamed of another life","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-06-012","lineIndex":11,"speaker":"","original":"Quand ma vie passait","ipa":"/kɑ̃ ma vi pasɛ/","zh":"当我的生命过去","en":"When my life passed","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-06-013","lineIndex":12,"speaker":"","original":"Comme un rêve.","ipa":"/kɔm œ̃ ʁɛv/","zh":"就像一场梦。","en":"Like a dream.","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-06-014","lineIndex":13,"speaker":"","original":"J'étais prête","ipa":"/ʒetɛ pʁɛt/","zh":"我已准备好","en":"I was ready","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-06-015","lineIndex":14,"speaker":"","original":"À toutes les folies","ipa":"/a tut le foli/","zh":"投身一切疯狂","en":"To all the madness","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-06-016","lineIndex":15,"speaker":"","original":"À toutes les passions","ipa":"/a tut le pasjɔ̃/","zh":"也投身所有","en":"To all passions","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-06-017","lineIndex":16,"speaker":"","original":"Qui se lèvent.","ipa":"/ki sə lɛv/","zh":"涌现的激情。","en":"Who get up.","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-06-018","lineIndex":17,"speaker":"","original":"J'étais si jeune, où est le mal?","ipa":"/ʒetɛ si ʒøn u ɛ lə mal/","zh":"我还那么年轻，有什么坏处呢？","en":"I was so young, what's the harm?","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-06-019","lineIndex":18,"speaker":"","original":"Je voulais rire","ipa":"/ʒə vulɛ ʁiʁ/","zh":"我想笑","en":"I wanted to laugh","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-06-020","lineIndex":19,"speaker":"","original":"Aimer et vivre","ipa":"/ɛme e vivʁ/","zh":"去爱和生活","en":"To love and live","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-06-021","lineIndex":20,"speaker":"","original":"Danser jusqu'à la fin du bal","ipa":"/dɑ̃se ʒyska la fɛ̃ dy bal/","zh":"跳舞直到舞会结束","en":"Dancing until the end of the ball","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-06-022","lineIndex":21,"speaker":"","original":"Ivre du bonheur d'être libre.","ipa":"/ivʁ dy bɔnœʁ dɛtʁ libʁ/","zh":"陶醉在自由的幸福之中。","en":"Drunk with the happiness of being free.","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-06-023","lineIndex":22,"speaker":"","original":"Mais les loups rôdent dans la nuit;","ipa":"/mɛ le lu ʁod dɑ̃ la nɥi/","zh":"但狼群却在夜间徘徊；","en":"But wolves prowl in the night;","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-06-024","lineIndex":23,"speaker":"","original":"Et l'un d'eux flairait ma trace.","ipa":"/e lœ̃ dø flɛʁɛ ma tʁas/","zh":"其中一只闻到了我的踪迹。","en":"And one of them smelled my trail.","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-06-025","lineIndex":24,"speaker":"","original":"Moi, j'ai comblé l'appétit","ipa":"/mwa ʒe kɔ̃ble lapeti/","zh":"我满足了","en":"I satisfied my appetite","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-06-026","lineIndex":25,"speaker":"","original":"Du premier voleur qui passe.","ipa":"/dy pʁəmje volœʁ ki pas/","zh":"第一个路过的恶徒的欲望。","en":"From the first thief who passes.","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-06-027","lineIndex":26,"speaker":"","original":"Il a accoutumé ma vie","ipa":"/il a akutyme ma vi/","zh":"他让我习惯了","en":"He accustomed my life","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-06-028","lineIndex":27,"speaker":"","original":"À la chaleur de sa présence.","ipa":"/a la ʃalœʁ də sa pʁezɑ̃s/","zh":"他在身边时那一点温度。","en":"To the warmth of his presence.","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-06-029","lineIndex":28,"speaker":"","original":"Et puis un jour il est parti","ipa":"/e pɥiz œ̃ ʒuʁ il ɛ paʁti/","zh":"然后有一天他离开了","en":"And then one day he left","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-06-030","lineIndex":29,"speaker":"","original":"En m'ayant volé mon enfance.","ipa":"/ɑ̃ mɛjɑ̃ vole mɔ̃n ɑ̃fɑ̃s/","zh":"偷走我的童年。","en":"By stealing my childhood.","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-06-032","lineIndex":30,"speaker":"Parfois je rêve de lui encore","original":"Il me supplie et il regrette.","ipa":"/il mə sypli e il ʁəɡʁɛt/","zh":"他求我，他后悔了。","en":"He begs me and he regrets.","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-06-033","lineIndex":31,"speaker":"","original":"Mais le rêve s'éteint à l'aurore","ipa":"/mɛ lə ʁɛv setɛ̃t a loʁɔʁ/","zh":"但梦想在黎明时就破灭了","en":"But the dream dies at dawn","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-06-034","lineIndex":32,"speaker":"","original":"Comme les lampions d'un soir de fête.","ipa":"/kɔm le lɑ̃pjɔ̃ dœ̃ swaʁ də fɛt/","zh":"就像节日晚上的灯笼一样。","en":"Like the lanterns of a festive evening.","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-06-035","lineIndex":33,"speaker":"","original":"J'avais rêvé d'une autre vie.","ipa":"/ʒavɛ ʁɛve dyn otʁ vi/","zh":"我曾梦想过另一种生活。","en":"I had dreamed of another life.","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-06-036","lineIndex":34,"speaker":"","original":"À peine commencée elle s'achève.","ipa":"/a pɛn kɔmɑ̃se ɛl saʃɛv/","zh":"刚刚开始，就结束了。","en":"Barely begun, it ends.","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-06-037","lineIndex":35,"speaker":"","original":"J'avais rêvé d'une autre vie","ipa":"/ʒavɛ ʁɛve dyn otʁ vi/","zh":"我曾经梦想过另一种生活","en":"I had dreamed of another life","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-06-038","lineIndex":36,"speaker":"","original":"Mais la vie a tué","ipa":"/mɛ la vi a tye/","zh":"可生活却杀死了","en":"But life has killed","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-06-039","lineIndex":37,"speaker":"","original":"Mes rêves.","ipa":"/me ʁɛv/","zh":"我的梦想。","en":"My dreams.","note":"","sourceLineIndex":39}],"sourceOrder":6,"displayOrder":5},{"order":7,"id":"07-tu-viens-cheri","title":"Tu viens chéri!","titleZh":"亲爱的你来了！","lines":[{"id":"les-miserables-cityprod-2017-07-001","lineIndex":1,"speaker":"","original":"Ça sent la femme, un parfum dans l'air.","ipa":"/sa sɑ̃ la fam œ̃ paʁfœ̃ dɑ̃ lɛʁ/","zh":"空气中弥漫着女人的味道，淡淡的香水味。","en":"It smells like a woman, a perfume in the air.","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-07-002","lineIndex":2,"speaker":"","original":"Je vais jeter l'ancre dans cette terre hospitalière.","ipa":"/ʒə vɛ ʒəte lɑ̃kʁ dɑ̃ sɛt tɛʁ ɔspitaljɛʁ/","zh":"我将在这片热情好客的土地上抛锚。","en":"I will drop anchor in this hospitable land.","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-07-003","lineIndex":3,"speaker":"","original":"Je viens, chéries, sortez vos dentelles.","ipa":"/ʒə vjɛ̃ ʃeʁi sɔʁte vo dɑ̃tɛl/","zh":"我来了，姑娘们，亮出你们的花边来。","en":"I'm coming, darlings, take out your lace.","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-07-004","lineIndex":4,"speaker":"","original":"Quelques jours en mer, pour l'appétit, y'a rien de tel.","ipa":"/kɛlkə ʒuʁz ɑ̃ mɛʁ puʁ lapeti ja ʁiɛ̃ də tɛl/","zh":"在海上呆了几天，对于胃口来说，没有什么比这更好的了。","en":"A few days at sea, for the appetite, there's nothing like it.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-07-005","lineIndex":5,"speaker":"","original":"Elles touchent mon pompon et je monte au ciel.","ipa":"/ɛl tuʃ mɔ̃ pɔ̃pɔ̃ e ʒə mɔ̃t o sjɛl/","zh":"她们一碰我那“绒球”，我就飘上天。","en":"They touch my pompom and I go to heaven.","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-07-006","lineIndex":6,"speaker":"","original":"Tu viens, chéri! Je vais te faire voir:","ipa":"/ty vjɛ̃ ʃeʁi ʒə vɛ tə fɛʁ vwaʁ/","zh":"来吧，亲爱的！我让你见识见识：","en":"You're coming, darling! I'll show you:","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-07-007","lineIndex":7,"speaker":"","original":"C'est mieux qu'à Paris sous le tunnel de Saint-Lazare.","ipa":"/sɛ mjø ka paʁi su lə tynɛl də sɛ̃lazaʁ/","zh":"比巴黎圣拉扎尔隧道下的还要好。","en":"It's better than in Paris under the Saint-Lazare tunnel.","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-07-008","lineIndex":8,"speaker":"","original":"Tu viens, chéri! On est toujours prêtes:","ipa":"/ty vjɛ̃ ʃeʁi ɔ̃n ɛ tuʒuʁ pʁɛt/","zh":"来吧，亲爱的！我们随时奉陪：","en":"You're coming, darling! We are always ready:","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-07-009","lineIndex":9,"speaker":"","original":"Contre un mur ou sur un lit, on se met comme tu le souhaites.","ipa":"/kɔ̃tʁ œ̃ myʁ u syʁ œ̃ li ɔ̃ sə mɛ kɔm ty lə suɛt/","zh":"靠着墙也好，上床也好，随你想要的来。","en":"Against a wall or on a bed, position yourself as you wish.","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-07-010","lineIndex":10,"speaker":"","original":"Mais tu craches avant la galipette!","ipa":"/mɛ ty kʁaʃz avɑ̃ la ɡalipɛt/","zh":"不过办事前得先掏钱！","en":"But you spit before the somersault!","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-07-011","lineIndex":11,"speaker":"","original":"Viens là, ma chère! Fais voir ce joli collier.","ipa":"/vjɛ̃ la ma ʃɛʁ fɛ vwaʁ sə ʒoli kɔlje/","zh":"过来，亲爱的！让我看看这条漂亮项链。","en":"Come here, my dear! Show off this pretty necklace.","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-07-012","lineIndex":12,"speaker":"","original":"Ce pendentif...","ipa":"/sə pɑ̃dɑ̃tif/","zh":"这个吊坠...","en":"This pendant...","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-07-013","lineIndex":13,"speaker":"","original":"Madame, voulez-vous l'acheter?","ipa":"/madam vulevu laʃte/","zh":"女士，您要买吗？","en":"Madam, do you want to buy it?","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-07-014","lineIndex":14,"speaker":"","original":"Ça vaut cinq sous.","ipa":"/sa vo sɛ̃k su/","zh":"它值五苏。","en":"It's worth five cents.","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-07-015","lineIndex":15,"speaker":"","original":"La chaîne toute seule en vaut quinze.","ipa":"/la ʃɛn tut sœl ɑ̃ vo kɛ̃z/","zh":"单是这条链子就值十五苏。","en":"The chain alone is worth fifteen.","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-07-016","lineIndex":16,"speaker":"","original":"Je t'en donne dix;","ipa":"/ʒə tɑ̃ dɔn dis/","zh":"我给你十苏；","en":"I give you ten;","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-07-017","lineIndex":17,"speaker":"","original":"Je ne veux plus discuter.","ipa":"/ʒə nə vø ply diskyte/","zh":"我不想再争论了。","en":"I don't want to argue anymore.","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-07-018","lineIndex":18,"speaker":"","original":"Allons, décide!","ipa":"/alɔ̃ desid/","zh":"来吧，决定吧！","en":"Come on, decide!","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-07-019","lineIndex":19,"speaker":"","original":"Mon seul bijou!","ipa":"/mɔ̃ sœl biʒu/","zh":"我唯一的宝石！","en":"My only jewel!","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-07-020","lineIndex":20,"speaker":"","original":"Cesse de me suivre!","ipa":"/sɛs də mə sɥivʁ/","zh":"不要跟着我！","en":"Stop following me!","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-07-021","lineIndex":21,"speaker":"","original":"Donnez-m'en douze!","ipa":"/dɔnemɑ̃ duz/","zh":"给我十二苏！","en":"Give me twelve!","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-07-022","lineIndex":22,"speaker":"","original":"Pas plus de dix!","ipa":"/pa ply də dis/","zh":"最多十苏！","en":"No more than ten!","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-07-023","lineIndex":23,"speaker":"","original":"Ma chère, il faut","ipa":"/ma ʃɛʁ il fo/","zh":"亲爱的，我们都得","en":"My dear, we must","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-07-024","lineIndex":24,"speaker":"","original":"Tous qu'on survive.","ipa":"/tus kɔ̃ syʁviv/","zh":"想法子活下去。","en":"May we all survive.","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-07-025","lineIndex":25,"speaker":"","original":"Tu viens chéri! Qu'est-ce qu'on fait ce soir?","ipa":"/ty vjɛ̃ ʃeʁi kɛs kɔ̃ fɛ sə swaʁ/","zh":"来吧，亲爱的！今晚想怎么来？","en":"You come darling! What are we doing this evening?","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-07-026","lineIndex":26,"speaker":"","original":"L'amour dans ton pieu, ou vite fait bien fait dans le noir?","ipa":"/lamuʁ dɑ̃ tɔ̃ pjø u vit fɛ bjɛ̃ fɛ dɑ̃ lə nwaʁ/","zh":"在你床上缠绵，还是摸黑速战速决？","en":"Love in your stake, or quick and easy in the dark?","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-07-027","lineIndex":27,"speaker":"","original":"Une fille, deux filles, une heure ou un jour;","ipa":"/yn fij dø fij yn œʁ u œ̃ ʒuʁ/","zh":"一个女孩，两个女孩，一小时或一天；","en":"One girl, two girls, one hour or one day;","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-07-028","lineIndex":28,"speaker":"","original":"C'est toi qui choisis le menu de ta nuit d'amour","ipa":"/sɛ twa ki ʃwazi lə məny də ta nɥi damuʁ/","zh":"今晚的“菜单”，由你自己挑。","en":"You choose the menu for your night of love","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-07-029","lineIndex":29,"speaker":"","original":"Pour vingt sous, on fait l'aller-retour.","ipa":"/puʁ vɛ̃ su ɔ̃ fɛ laleʁətuʁ/","zh":"二十苏，来回一趟都行。","en":"For twenty cents, you can go there and back.","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-07-030","lineIndex":30,"speaker":"","original":"Les beaux cheveux! Les jolies boucles que voilà!","ipa":"/le bo ʃəvø le ʒoli bukl kə vwala/","zh":"多漂亮的头发！多好看的卷发啊！","en":"Beautiful hair! What pretty curls there are!","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-07-031","lineIndex":31,"speaker":"","original":"Quelle chance tu as!","ipa":"/kɛl ʃɑ̃s ty a/","zh":"你真幸运！","en":"How lucky you are!","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-07-032","lineIndex":32,"speaker":"","original":"Ça vaut un bon prix, ma chère. Tu me les vends?","ipa":"/sa vot œ̃ bɔ̃ pʁi ma ʃɛʁ ty mə le vɑ̃/","zh":"亲爱的，这能卖个好价钱。卖给我吗？","en":"It's worth a good price, my dear. Are you selling them to me?","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-07-033","lineIndex":33,"speaker":"","original":"Laissez-moi, allez-vous en!","ipa":"/lɛsemwa alevuz ɑ̃/","zh":"离开我，走开！","en":"Leave me, go away!","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-07-034","lineIndex":34,"speaker":"","original":"Réfléchis bien, je peux t'en donner dix francs.","ipa":"/ʁefleʃi bjɛ̃ ʒə pø tɑ̃ dɔne di fʁɑ̃/","zh":"仔细想想，我可以给你十法郎。","en":"Think carefully, I can give you ten francs for it.","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-07-035","lineIndex":35,"speaker":"","original":"Réfléchis bien!","ipa":"/ʁefleʃi bjɛ̃/","zh":"仔细想想！","en":"Think carefully!","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-07-036","lineIndex":36,"speaker":"","original":"Ma pauvre tête!","ipa":"/ma povʁ tɛt/","zh":"我可怜的头！","en":"My poor head!","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-07-037","lineIndex":37,"speaker":"ACHETEUSE DE CHEVEUX","original":"Réfléchis bien!","ipa":"/ʁefleʃi bjɛ̃/","zh":"仔细想想！","en":"Think carefully!","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-07-038","lineIndex":38,"speaker":"FANTINE","original":"C'est pour Cosette! Oui, coupez-les","ipa":"/sɛ puʁ kozɛt wi kupele/","zh":"是为了珂赛特！是的，把它们剪掉。","en":"It's for Cosette! Yes, cut them","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-07-039","lineIndex":39,"speaker":"FANTINE","original":"Dix francs déjà pour la soigner...","ipa":"/di fʁɑ̃ deʒa puʁ la swanje/","zh":"十法郎，已经够给她治病了……","en":"Ten francs already to take care of her...","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-07-040","lineIndex":40,"speaker":"ACHETEUSE DE CHEVEUX","original":"Viens là, chérie! Et fais voir ta bourse.","ipa":"/vjɛ̃ la ʃeʁi e fɛ vwaʁ ta buʁs/","zh":"过来，亲爱的！把你的钱袋给我看看。","en":"Come here, darling! And show your purse.","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-07-041","lineIndex":41,"speaker":"ACHETEUSE DE CHEVEUX","original":"Si tu me caches une passe, tu me rembourses ou je te tabasse.","ipa":"/si ty mə kaʃz yn pas ty mə ʁɑ̃buʁs u ʒə tə tabas/","zh":"要是你瞒着我私下接客，就赔钱；不然我揍你。","en":"If you hide a pass from me, you pay me back or I'll beat you up.","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-07-042","lineIndex":42,"speaker":"ACHETEUSE DE CHEVEUX","original":"Tu viens, chérie!","ipa":"/ty vjɛ̃ ʃeʁi/","zh":"你来了，亲爱的！","en":"You're coming, darling!","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-07-043","lineIndex":43,"speaker":"ACHETEUSE DE CHEVEUX","original":"Jolies, jolies","ipa":"/ʒoli ʒoli/","zh":"漂亮，漂亮","en":"Pretty, pretty","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-07-044","lineIndex":44,"speaker":"ACHETEUSE DE CHEVEUX","original":"Filles à vendre!","ipa":"/fijz a vɑ̃dʁ/","zh":"少女出售！","en":"Girls for sale!","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-07-045","lineIndex":45,"speaker":"ACHETEUSE DE CHEVEUX","original":"Viens là, chérie!","ipa":"/vjɛ̃ la ʃeʁi/","zh":"来这里吧，亲爱的！","en":"Come here, darling!","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-07-046","lineIndex":46,"speaker":"ACHETEUSE DE CHEVEUX","original":"Chacune à sa place.","ipa":"/ʃakyn a sa plas/","zh":"每个人都在自己的位置上。","en":"Everyone in their place.","note":"","sourceLineIndex":46},{"id":"les-miserables-cityprod-2017-07-047","lineIndex":47,"speaker":"ACHETEUSE DE CHEVEUX","original":"Pitié je te jure! C'est la crève que j'ai.","ipa":"/pitje ʒə tə ʒyʁ sɛ la kʁɛv kə ʒe/","zh":"求你了，我发誓！我是真病得厉害。","en":"Please, I swear! That's the problem I have.","note":"","sourceLineIndex":47},{"id":"les-miserables-cityprod-2017-07-048","lineIndex":48,"speaker":"ACHETEUSE DE CHEVEUX","original":"J'ai si mal au ventre, que j'arrive à peine à marcher.","ipa":"/ʒe si mal o vɑ̃tʁ kə ʒaʁiv a pɛn a maʁʃe/","zh":"我的肚子疼得几乎无法行走。","en":"My stomach hurts so much I can barely walk.","note":"","sourceLineIndex":48},{"id":"les-miserables-cityprod-2017-07-049","lineIndex":49,"speaker":"ACHETEUSE DE CHEVEUX","original":"Chérie va falloir que je te remplace.","ipa":"/ʃeʁi va falwaʁ kə ʒə tə ʁɑ̃plas/","zh":"亲爱的，我得找个人顶替你。","en":"Honey, I'm going to have to replace you.","note":"","sourceLineIndex":49},{"id":"les-miserables-cityprod-2017-07-050","lineIndex":50,"speaker":"ACHETEUSE DE CHEVEUX","original":"C'est épouvantail, c'est quoi? Dis-moi un peu?","ipa":"/sɛt epuvɑ̃taj sɛ kwa dimwa œ̃ pø/","zh":"这是什么，稻草人？告诉我一点？","en":"What is it, scarecrow? Tell me a little?","note":"","sourceLineIndex":50},{"id":"les-miserables-cityprod-2017-07-051","lineIndex":51,"speaker":"ACHETEUSE DE CHEVEUX","original":"C'est une paumée qui a vendu ses cheveux","ipa":"/sɛt yn pome ki a vɑ̃dy se ʃəvø/","zh":"她是个走投无路、卖掉头发的女人。","en":"She's a loser who sold her hair","note":"","sourceLineIndex":51},{"id":"les-miserables-cityprod-2017-07-052","lineIndex":52,"speaker":"ACHETEUSE DE CHEVEUX","original":"Elle a un gosse, lui envoie tout ce qu'elle peut.","ipa":"/ɛl a œ̃ ɡɔs lɥi ɑ̃vwa tu sə kɛl pø/","zh":"她有个孩子，能寄的全寄给了孩子。","en":"She has a kid, sends him everything she can.","note":"","sourceLineIndex":52},{"id":"les-miserables-cityprod-2017-07-053","lineIndex":53,"speaker":"ACHETEUSE DE CHEVEUX","original":"Je savais bien: y'a toujours un bonhomme.","ipa":"/ʒə savɛ bjɛ̃ ja tuʒuʁz œ̃ bɔnɔm/","zh":"我就知道，背后总有个男人。","en":"I knew well: there's always a guy.","note":"","sourceLineIndex":53},{"id":"les-miserables-cityprod-2017-07-054","lineIndex":54,"speaker":"ACHETEUSE DE CHEVEUX","original":"Tu viens, chérie! Viens te faire des copains.","ipa":"/ty vjɛ̃ ʃeʁi vjɛ̃ tə fɛʁ de kopɛ̃/","zh":"来吧，亲爱的！来认识几个“朋友”。","en":"You're coming, darling! Come make some friends.","note":"","sourceLineIndex":54},{"id":"les-miserables-cityprod-2017-07-055","lineIndex":55,"speaker":"ACHETEUSE DE CHEVEUX","original":"Chérie, tu viens!","ipa":"/ʃeʁi ty vjɛ̃/","zh":"亲爱的，你来啦！","en":"Honey, you're coming!","note":"","sourceLineIndex":55},{"id":"les-miserables-cityprod-2017-07-056","lineIndex":56,"speaker":"ACHETEUSE DE CHEVEUX","original":"Allez ma belle, viens là et pleure.","ipa":"/ale ma bɛl vjɛ̃ la e plœʁ/","zh":"来吧，姑娘，过来哭吧。","en":"Come on girl, come here and cry.","note":"","sourceLineIndex":56},{"id":"les-miserables-cityprod-2017-07-057","lineIndex":57,"speaker":"ACHETEUSE DE CHEVEUX","original":"Tu t'es faite piéger comme tes sœurs.","ipa":"/ty tɛ fɛt pjeʒe kɔm te sœʁ/","zh":"你和你的姐妹一样被困住了。","en":"You were trapped like your sisters.","note":"","sourceLineIndex":57},{"id":"les-miserables-cityprod-2017-07-058","lineIndex":58,"speaker":"ACHETEUSE DE CHEVEUX","original":"Nous on se couche pour une pièce de monnaie.","ipa":"/nuz ɔ̃ sə kuʃ puʁ yn pjɛs də mɔnɛ/","zh":"我们为一枚硬币就得躺下。","en":"We fold for a coin.","note":"","sourceLineIndex":58},{"id":"les-miserables-cityprod-2017-07-059","lineIndex":59,"speaker":"ACHETEUSE DE CHEVEUX","original":"Gagne ta vie","ipa":"/ɡaɲ ta vi/","zh":"谋生","en":"Earn your living","note":"","sourceLineIndex":59},{"id":"les-miserables-cityprod-2017-07-060","lineIndex":60,"speaker":"ACHETEUSE DE CHEVEUX","original":"En restant allongée.","ipa":"/ɑ̃ ʁɛstɑ̃ alɔ̃ʒe/","zh":"靠躺下谋生。","en":"By remaining lying down.","note":"","sourceLineIndex":60},{"id":"les-miserables-cityprod-2017-07-061","lineIndex":61,"speaker":"ACHETEUSE DE CHEVEUX","original":"Allons ma belle, vends lui ton trésor.","ipa":"/alɔ̃ ma bɛl vɑ̃ lɥi tɔ̃ tʁezɔʁ/","zh":"来吧，亲爱的，把你的宝藏卖给他吧。","en":"Come on, my dear, sell him your treasure.","note":"","sourceLineIndex":61},{"id":"les-miserables-cityprod-2017-07-062","lineIndex":62,"speaker":"ACHETEUSE DE CHEVEUX","original":"Allez ma belle, montre-lui d'abord!","ipa":"/ale ma bɛl mɔ̃tʁlɥi dabɔʁ/","zh":"来吧，姑娘，先给他看看！","en":"Come on girl, show him first!","note":"","sourceLineIndex":62},{"id":"les-miserables-cityprod-2017-07-063","lineIndex":63,"speaker":"ACHETEUSE DE CHEVEUX","original":"Les jeunes, les vioques, prends-les comme ils viennent.","ipa":"/le ʒøn le vjok pʁɑ̃le kɔm il vjɛn/","zh":"年轻的、年老的，来什么客人就接什么客人。","en":"The young people, the vioques, take them as they come.","note":"","sourceLineIndex":63},{"id":"les-miserables-cityprod-2017-07-064","lineIndex":64,"speaker":"ACHETEUSE DE CHEVEUX","original":"On voit les loquedus, les plus tordus de la race humaine.","ipa":"/ɔ̃ vwa le lokdy le ply tɔʁdy də la ʁas ymɛn/","zh":"形形色色、最古怪扭曲的人，我们都见过。","en":"We see the loquedus, the most twisted of the human race.","note":"","sourceLineIndex":64},{"id":"les-miserables-cityprod-2017-07-065","lineIndex":65,"speaker":"ACHETEUSE DE CHEVEUX","original":"Les pauvres, les riches et même les seigneurs.","ipa":"/le povʁ le ʁiʃz e mɛm le sɛnjœʁ/","zh":"穷人，富人，甚至领主。","en":"The poor, the rich and even the lords.","note":"","sourceLineIndex":65},{"id":"les-miserables-cityprod-2017-07-066","lineIndex":66,"speaker":"ACHETEUSE DE CHEVEUX","original":"Tous, sans leur caleçon, perdent un petit peu de leur grandeur.","ipa":"/tus sɑ̃ lœʁ kalsɔ̃ pɛʁdt œ̃ pəti pø də lœʁ ɡʁɑ̃dœʁ/","zh":"不论谁，脱了内裤，威风都会少几分。","en":"Everyone, without their underwear, loses a little bit of their size.","note":"","sourceLineIndex":66},{"id":"les-miserables-cityprod-2017-07-067","lineIndex":67,"speaker":"ACHETEUSE DE CHEVEUX","original":"Tout ce qui compte, c'est qu'ils soient bons payeurs.","ipa":"/tu sə ki kɔ̃t sɛ kil swa bɔ̃ pɛjœʁ/","zh":"重要的是他们报酬丰厚。","en":"All that matters is that they pay well.","note":"","sourceLineIndex":67},{"id":"les-miserables-cityprod-2017-07-068","lineIndex":68,"speaker":"ACHETEUSE DE CHEVEUX","original":"Tu viens, chéri! Avec un sourire","ipa":"/ty vjɛ̃ ʃeʁi avɛk œ̃ suʁiʁ/","zh":"来吧，亲爱的！带上笑脸","en":"You're coming, darling! With a smile","note":"","sourceLineIndex":68},{"id":"les-miserables-cityprod-2017-07-069","lineIndex":69,"speaker":"ACHETEUSE DE CHEVEUX","original":"On redit ces mots qui pour nous autres veulent plus rien dire.","ipa":"/ɔ̃ ʁədi se mo ki puʁ nuz otʁ vœl ply ʁjɛ̃ diʁ/","zh":"我们重复这些话，可对我们早已毫无意义。","en":"We repeat these words which for the rest of us no longer mean anything.","note":"","sourceLineIndex":69},{"id":"les-miserables-cityprod-2017-07-070","lineIndex":70,"speaker":"ACHETEUSE DE CHEVEUX","original":"Tu viens, marin, garde tes souliers.","ipa":"/ty vjɛ̃ maʁɛ̃ ɡaʁd te sulje/","zh":"来吧，水手，鞋子别脱。","en":"You come, sailor, keep your shoes on.","note":"","sourceLineIndex":70},{"id":"les-miserables-cityprod-2017-07-071","lineIndex":71,"speaker":"ACHETEUSE DE CHEVEUX","original":"Et paye-toi une fille qui ne peut rien te refuser.","ipa":"/e pɛjtwa yn fij ki nə pø ʁjɛ̃ tə ʁəfyze/","zh":"给自己找一个不能拒绝你任何事情的女孩。","en":"And get yourself a girl who can't refuse you anything.","note":"","sourceLineIndex":71},{"id":"les-miserables-cityprod-2017-07-072","lineIndex":72,"speaker":"FANTINE","original":"Tu viens, chéri! Je sombre en mon corps","ipa":"/ty vjɛ̃ ʃeʁi ʒə sɔ̃bʁ ɑ̃ mɔ̃ kɔʁ/","zh":"来吧，亲爱的！我在自己的躯体里沉没。","en":"You're coming, darling! I sink into my body","note":"","sourceLineIndex":72},{"id":"les-miserables-cityprod-2017-07-073","lineIndex":73,"speaker":"FANTINE","original":"Quand ils font jaillir en moi leur pitoyable effort.","ipa":"/kɑ̃t il fɔ̃ ʒajiʁ ɑ̃ mwa lœʁ pitwajabl efɔʁ/","zh":"当他们在我体内完成那可悲的欲望。","en":"When they bring forth in me their pitiful effort.","note":"","sourceLineIndex":73},{"id":"les-miserables-cityprod-2017-07-074","lineIndex":74,"speaker":"FANTINE","original":"Ils ne savent pas qu'ils font l'amour avec la mort.","ipa":"/il nə sav pa kil fɔ̃ lamuʁ avɛk la mɔʁ/","zh":"他们不知道，自己正与死亡做爱。","en":"They don't know that they are making love with death.","note":"","sourceLineIndex":74}],"sourceOrder":7,"displayOrder":6},{"order":8,"id":"08-le-proces-comment-faire","title":"Le procès: comment faire?","titleZh":"试用：怎么做？","lines":[{"id":"les-miserables-cityprod-2017-08-001","lineIndex":1,"speaker":"","original":"Il prend cet homme pour moi","ipa":"/il pʁɑ̃ sɛt ɔm puʁ mwa/","zh":"他把那个人错认成了我","en":"He takes this man for me","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-08-002","lineIndex":2,"speaker":"","original":"C'est peut-être ma chance.","ipa":"/sɛ pøtɛtʁ ma ʃɑ̃s/","zh":"也许这就是我的幸运。","en":"Maybe this is my luck.","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-08-003","lineIndex":3,"speaker":"","original":"Je n'ai rien d'autre à faire","ipa":"/ʒə ne ʁjɛ̃ dotʁ a fɛʁ/","zh":"我没有别的事可做","en":"I have nothing else to do","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-08-004","lineIndex":4,"speaker":"","original":"Que garder le silence.","ipa":"/kə ɡaʁde lə silɑ̃s/","zh":"只剩沉默以对。","en":"Than keep silent.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-08-005","lineIndex":5,"speaker":"","original":"Mais n'ai-je tant lutté","ipa":"/mɛ nɛʒ tɑ̃ lyte/","zh":"但我没有那么挣扎吗","en":"But didn't I struggle so much","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-08-006","lineIndex":6,"speaker":"","original":"Construit et inventé","ipa":"/kɔ̃stʁyi e ɛ̃vɑ̃te/","zh":"建造和发明","en":"Built and invented","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-08-007","lineIndex":7,"speaker":"","original":"Que pour céder la place","ipa":"/kə puʁ sede la plas/","zh":"不如让路","en":"Than to give way","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-08-008","lineIndex":8,"speaker":"","original":"À un remords qui passe?","ipa":"/a œ̃ ʁəmɔʁ ki pas/","zh":"短暂的悔恨？","en":"To a passing remorse?","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-08-009","lineIndex":9,"speaker":"","original":"Si je me tais, je me damne;","ipa":"/si ʒə mə tɛ ʒə mə dan/","zh":"我若沉默，便自我沉沦；","en":"If I remain silent, I damn myself;","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-08-010","lineIndex":10,"speaker":"","original":"Et si je parle, je me condamne.","ipa":"/e si ʒə paʁl ʒə mə kɔ̃dan/","zh":"我若开口，便自我定罪。","en":"And if I speak, I condemn myself.","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-08-011","lineIndex":11,"speaker":"","original":"Et tous ces gens qui travaillent à l'usine","ipa":"/e tu se ʒɑ̃ ki tʁavajt a lyzin/","zh":"还有所有在工厂工作的人","en":"And all these people who work at the factory","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-08-012","lineIndex":12,"speaker":"","original":"Et qui croient tous en moi","ipa":"/e ki kʁwa tus ɑ̃ mwa/","zh":"以及所有相信我的人","en":"And who all believe in me","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-08-013","lineIndex":13,"speaker":"","original":"Puis-je les abandonner?","ipa":"/pɥiʒ lez abɑ̃dɔne/","zh":"我可以放弃他们吗？","en":"Can I abandon them?","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-08-014","lineIndex":14,"speaker":"","original":"C'est au néant","ipa":"/sɛt o neɑ̃/","zh":"那便是把他们","en":"It's to nothingness","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-08-015","lineIndex":15,"speaker":"","original":"Que je les renvoie.","ipa":"/kə ʒə le ʁɑ̃vwa/","zh":"推回虚无。","en":"Let me send them back.","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-08-016","lineIndex":16,"speaker":"","original":"Si je me tais, je me damne;","ipa":"/si ʒə mə tɛ ʒə mə dan/","zh":"如果我保持沉默，我就该诅咒自己；","en":"If I remain silent, I damn myself;","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-08-017","lineIndex":17,"speaker":"","original":"Et si je parle, je me condamne.","ipa":"/e si ʒə paʁl ʒə mə kɔ̃dan/","zh":"如果我说话，我就是在谴责自己。","en":"And if I speak, I condemn myself.","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-08-018","lineIndex":18,"speaker":"","original":"Comment faire?","ipa":"/kɔmɑ̃ fɛʁ/","zh":"怎么做呢？","en":"How to do it?","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-08-019","lineIndex":19,"speaker":"","original":"Trahir cet homme accablé par erreur?","ipa":"/tʁaiʁ sɛt ɔm akable paʁ ɛʁœʁ/","zh":"背叛这个被错误压倒的男人？","en":"Betray this man overwhelmed by mistake?","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-08-020","lineIndex":20,"speaker":"","original":"Le laisser choir","ipa":"/lə lɛse ʃwaʁ/","zh":"任由他坠落","en":"Let it fall","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-08-021","lineIndex":21,"speaker":"","original":"Dans le puits du malheur?","ipa":"/dɑ̃ lə pɥi dy malœʁ/","zh":"陷入不幸的深渊？","en":"In the pit of misfortune?","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-08-022","lineIndex":22,"speaker":"","original":"Cet innocent dont le péché","ipa":"/sɛt inosɑ̃ dɔ̃ lə peʃe/","zh":"这个无辜者的罪过","en":"This innocent whose sin","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-08-023","lineIndex":23,"speaker":"","original":"Est seulement de me ressembler.","ipa":"/ɛ sølmɑ̃ də mə ʁəsɑ̃ble/","zh":"只是为了看起来像我。","en":"Is only to look like me.","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-08-024","lineIndex":24,"speaker":"","original":"Comment faire?","ipa":"/kɔmɑ̃ fɛʁ/","zh":"怎么做呢？","en":"How to do it?","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-08-025","lineIndex":25,"speaker":"","original":"Refuser de retourner en enfer","ipa":"/ʁəfyze də ʁətuʁne ɑ̃n ɑ̃fɛʁ/","zh":"拒绝回到地狱","en":"Refuse to return to hell","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-08-026","lineIndex":26,"speaker":"","original":"Parce que j'ai fait mon paradis sur terre.","ipa":"/paʁskə ʒe fɛ mɔ̃ paʁadi syʁ tɛʁ/","zh":"因为我在人间创造了我的天堂。","en":"Because I made my paradise on earth.","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-08-027","lineIndex":27,"speaker":"","original":"Tirer un trait sur mon passé","ipa":"/tiʁe œ̃ tʁɛ syʁ mɔ̃ pase/","zh":"在我的过去下划清界限","en":"Drawing a line under my past","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-08-028","lineIndex":28,"speaker":"","original":"Et dans l'oubli, me prélasser.","ipa":"/e dɑ̃ lubli mə pʁelase/","zh":"在遗忘中安逸度日。","en":"And in oblivion, I bask.","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-08-029","lineIndex":29,"speaker":"","original":"Comment faire?","ipa":"/kɔmɑ̃ fɛʁ/","zh":"怎么做呢？","en":"How to do it?","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-08-030","lineIndex":30,"speaker":"","original":"Comment pourrais-je","ipa":"/kɔmɑ̃ puʁɛʒ/","zh":"我怎么能","en":"How could I","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-08-031","lineIndex":31,"speaker":"","original":"Regarder dans la glace","ipa":"/ʁəɡaʁde dɑ̃ la ɡlas/","zh":"照照镜子","en":"Look in the mirror","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-08-032","lineIndex":32,"speaker":"","original":"Un homme qui n'ose pas","ipa":"/œ̃n ɔm ki nɔz pa/","zh":"一个不敢的人","en":"A man who does not dare","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-08-033","lineIndex":33,"speaker":"","original":"Se regarder en face?","ipa":"/sə ʁəɡaʁde ɑ̃ fas/","zh":"看看自己的脸吗？","en":"Look yourself in the face?","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-08-034","lineIndex":34,"speaker":"","original":"Si mon âme appartient à Dieu","ipa":"/si mɔ̃n am apaʁtjɛ̃ a djø/","zh":"如果我的灵魂属于上帝","en":"If my soul belongs to God","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-08-035","lineIndex":35,"speaker":"","original":"Il peut la reprendre quand il veut.","ipa":"/il pø la ʁəpʁɑ̃dʁ kɑ̃t il vø/","zh":"只要他愿意，他随时都可以收回。","en":"He can take it back whenever he wants.","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-08-036","lineIndex":36,"speaker":"","original":"Si c'est une épreuve qu'il m'envoie","ipa":"/si sɛt yn epʁøv kil mɑ̃vwa/","zh":"如果这是他发给我的测试","en":"If it is a test that he sends me","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-08-037","lineIndex":37,"speaker":"","original":"C'est qu'il a décidé pour moi.","ipa":"/sɛ kil a deside puʁ mwa/","zh":"他为我做了决定。","en":"He decided for me.","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-08-038","lineIndex":38,"speaker":"","original":"Comment faire?","ipa":"/kɔmɑ̃ fɛʁ/","zh":"怎么做呢？","en":"How to do it?","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-08-039","lineIndex":39,"speaker":"","original":"Rien à faire!","ipa":"/ʁiɛ̃n a fɛʁ/","zh":"无可逃避！","en":"Nothing to do!","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-08-040","lineIndex":40,"speaker":"","original":"Je suis Jean Valjean.","ipa":"/ʒə sɥi ʒɑ̃ valʒɑ̃/","zh":"我是冉阿让。","en":"I am Jean Valjean.","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-08-041","lineIndex":41,"speaker":"","original":"Voilà Javert, la vérité.","ipa":"/vwala ʒavɛʁ la veʁite/","zh":"沙威，这就是事实。","en":"This is Javert, the truth.","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-08-042","lineIndex":42,"speaker":"","original":"C'est un innocent qui est jugé","ipa":"/sɛt œ̃n inosɑ̃ ki ɛ ʒyʒe/","zh":"受审判的是一个无辜的人","en":"It is an innocent person who is judged","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-08-043","lineIndex":43,"speaker":"","original":"Regarde bien!","ipa":"/ʁəɡaʁd bjɛ̃/","zh":"仔细看！","en":"Look closely!","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-08-044","lineIndex":44,"speaker":"","original":"24-601!","ipa":"/vɛ̃tkatʁ sisɑ̃ œ̃/","zh":"24-601！","en":"24-601!","note":"","sourceLineIndex":44}],"sourceOrder":8,"displayOrder":7},{"order":9,"id":"09-la-mort-de-fantine","title":"La mort de fantine","titleZh":"芳汀之死","lines":[{"id":"les-miserables-cityprod-2017-09-001","lineIndex":1,"speaker":"","original":"Il fait si froid dehors;","ipa":"/il fɛ si fʁwa dəɔʁ/","zh":"外面很冷；","en":"It's so cold outside;","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-09-002","lineIndex":2,"speaker":"","original":"Les petites filles bien sages","ipa":"/le pətit fij bjɛ̃ saʒ/","zh":"好小姑娘们","en":"Good little girls","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-09-003","lineIndex":3,"speaker":"","original":"Attendent déjà au lit","ipa":"/atɑ̃d deʒa o li/","zh":"已经在床上等待了","en":"Already waiting in bed","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-09-004","lineIndex":4,"speaker":"","original":"Qu'arrive le marchand de sable.","ipa":"/kaʁiv lə maʁʃɑ̃ də sabl/","zh":"等待睡神到来。","en":"Here comes the sandman.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-09-005","lineIndex":5,"speaker":"","original":"Ma Cosette, la nuit descend son voile","ipa":"/ma kozɛt la nɥi dɛsɑ̃ sɔ̃ vwal/","zh":"我的珂赛特，夜幕正缓缓落下","en":"My Cosette, the night lowers its veil","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-09-006","lineIndex":6,"speaker":"","original":"Dans le ciel naît la première étoile.","ipa":"/dɑ̃ lə sjɛl nɛ la pʁəmjɛʁ etwal/","zh":"第一颗星星在天空中诞生。","en":"The first star is born in the sky.","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-09-007","lineIndex":7,"speaker":"","original":"Ferme tes yeux, pardonne-moi ma fille.","ipa":"/fɛʁm tez jø paʁdɔnmwa ma fij/","zh":"闭上眼睛，原谅我，我的女儿。","en":"Close your eyes, forgive me my daughter.","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-09-008","lineIndex":8,"speaker":"","original":"J'avais rêvé de faire ton nid","ipa":"/ʒavɛ ʁɛve də fɛʁ tɔ̃ ni/","zh":"我梦想着为你筑巢","en":"I dreamed of making your nest","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-09-009","lineIndex":9,"speaker":"","original":"Au sein d'une vraie famille.","ipa":"/o sɛ̃ dyn vʁɛ famij/","zh":"在一个真正的家庭里。","en":"Within a real family.","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-09-010","lineIndex":10,"speaker":"","original":"La misère n'est mère de personne","ipa":"/la mizɛʁ nɛ mɛʁ də pɛʁsɔn/","zh":"苦难不是任何人的母亲","en":"Misery is the mother of no one","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-09-011","lineIndex":11,"speaker":"","original":"Elle enfante l'horreur au cœur des hommes","ipa":"/ɛl ɑ̃fɑ̃t loʁœʁ o kœʁ dez ɔm/","zh":"她在男人心中生出恐惧","en":"She gives birth to horror in the hearts of men","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-09-012","lineIndex":12,"speaker":"","original":"Les ténèbres qui recouvrent la terre.","ipa":"/le tenɛbʁ ki ʁəkuvʁ la tɛʁ/","zh":"黑暗笼罩大地。","en":"The darkness that covers the earth.","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-09-013","lineIndex":13,"speaker":"","original":"Moi, je vais rester là à te bercer la nuit entière","ipa":"/mwa ʒə vɛ ʁɛste la a tə bɛʁse la nɥi ɑ̃tjɛʁ/","zh":"我会留在这里，整夜哄你入睡。","en":"Me, I'm going to stay there rocking you all night","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-09-014","lineIndex":14,"speaker":"","original":"Oh! Fantine","ipa":"/ɔ fɑ̃tin/","zh":"哦！芳汀","en":"Oh! Fantine","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-09-015","lineIndex":15,"speaker":"","original":"Je n'ai que peu de temps;","ipa":"/ʒə ne kə pø də tɑ̃/","zh":"我只有一点点时间；","en":"I only have a little time;","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-09-016","lineIndex":16,"speaker":"","original":"Mais Fantine, je te fais ce serment.","ipa":"/mɛ fɑ̃tin ʒə tə fɛ sə sɛʁmɑ̃/","zh":"但是芳汀，我向你发誓。","en":"But Fantine, I make this oath to you.","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-09-017","lineIndex":17,"speaker":"","original":"Oh! Monsieur","ipa":"/ɔ məsjø/","zh":"哦！先生","en":"Oh! Sir","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-09-018","lineIndex":18,"speaker":"","original":"Regardez-la jouer!","ipa":"/ʁəɡaʁdela ʒwe/","zh":"看看她玩得多开心！","en":"Watch her play!","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-09-019","lineIndex":19,"speaker":"","original":"Dors en paix","ipa":"/dɔʁz ɑ̃ pɛ/","zh":"安然入睡","en":"Sleep in peace","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-09-020","lineIndex":20,"speaker":"","original":"Dors en paix mon enfant.","ipa":"/dɔʁz ɑ̃ pɛ mɔ̃n ɑ̃fɑ̃/","zh":"安睡吧，我的孩子。","en":"Sleep in peace my child.","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-09-021","lineIndex":21,"speaker":"","original":"Ma Cosette...","ipa":"/ma kozɛt/","zh":"我的珂赛特...","en":"My Cosette...","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-09-022","lineIndex":22,"speaker":"","original":"Vous serez ma famille.","ipa":"/vu səʁe ma famij/","zh":"你将成为我的家人。","en":"You will be my family.","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-09-023","lineIndex":23,"speaker":"","original":"Elle aura...","ipa":"/ɛl oʁa/","zh":"她将会有...","en":"She will have...","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-09-024","lineIndex":24,"speaker":"","original":"Tout, comme ma propre fille.","ipa":"/tu kɔm ma pʁɔpʁ fij/","zh":"就像我自己的女儿一样。","en":"Just like my own daughter.","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-09-025","lineIndex":25,"speaker":"","original":"Bon monsieur","ipa":"/bɔ̃ məsjø/","zh":"好先生","en":"Good sir","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-09-026","lineIndex":26,"speaker":"","original":"Bon ange qui tombez du ciel.","ipa":"/bɔ̃n ɑ̃ʒ ki tɔ̃be dy sjɛl/","zh":"从天而降的善良天使。","en":"Good angel falling from heaven.","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-09-027","lineIndex":27,"speaker":"","original":"Vous la verrez bientôt","ipa":"/vu la vɛʁe bjɛ̃to/","zh":"你很快就会见到她","en":"You will see her soon","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-09-028","lineIndex":28,"speaker":"","original":"J'irai la rechercher moi-même","ipa":"/ʒiʁe la ʁəʃɛʁʃe mwamɛm/","zh":"我会亲自去把她找回来。","en":"I'll go look for it myself","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-09-029","lineIndex":29,"speaker":"","original":"La lumière brille","ipa":"/la lymjɛʁ bʁij/","zh":"光芒闪耀","en":"The light shines","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-09-030","lineIndex":30,"speaker":"","original":"Du fond de votre âme;","ipa":"/dy fɔ̃ də votʁ am/","zh":"从你的灵魂深处；","en":"From the bottom of your soul;","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-09-031","lineIndex":31,"speaker":"","original":"Vous ne travaillerez plus.","ipa":"/vu nə tʁavajʁe ply/","zh":"你将不再工作。","en":"You will no longer work.","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-09-032","lineIndex":32,"speaker":"","original":"Elle éclaire le cœur blessé d'une femme","ipa":"/ɛl eklɛʁ lə kœʁ blɛse dyn fam/","zh":"她照亮一个受伤女人的心。","en":"She lights up a woman's wounded heart","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-09-033","lineIndex":33,"speaker":"","original":"Vertueuse devant Dieu!","ipa":"/vɛʁtyøz dəvɑ̃ djø/","zh":"在神面前有德行！","en":"Virtuous before God!","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-09-034","lineIndex":34,"speaker":"","original":"Bon monsieur","ipa":"/bɔ̃ məsjø/","zh":"好先生","en":"Good sir","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-09-035","lineIndex":35,"speaker":"","original":"Que je vais être heureuse!","ipa":"/kə ʒə vɛz ɛtʁ øʁøz/","zh":"我会多么高兴啊！","en":"How happy I will be!","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-09-036","lineIndex":36,"speaker":"","original":"Je dirai à Cosette","ipa":"/ʒə diʁe a kozɛt/","zh":"我会告诉珂赛特","en":"I will tell Cosette","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-09-037","lineIndex":37,"speaker":"","original":"Qu'un saint est descendu sur terre","ipa":"/kœ̃ sɛ̃ ɛ dɛsɑ̃dy syʁ tɛʁ/","zh":"一位圣人降临人间","en":"That a saint came down to earth","note":"","sourceLineIndex":37}],"sourceOrder":9,"displayOrder":8},{"order":10,"id":"10-la-confrontation","title":"La confrontation","titleZh":"对抗","lines":[{"id":"les-miserables-cityprod-2017-10-001","lineIndex":1,"speaker":"","original":"Enfin, Valjean tu vas purger ta peine.","ipa":"/ɑ̃fɛ̃ valʒɑ̃ ty va pyʁʒe ta pɛn/","zh":"冉阿让，你终于要服刑了。","en":"Finally, Valjean you will serve your sentence.","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-10-002","lineIndex":2,"speaker":"","original":"Monsieur le maire au boulet de ta chaîne.","ipa":"/məsjø lə mɛʁ o bulɛ də ta ʃɛn/","zh":"市长先生，又要拖着你的铁球锁链。","en":"Mr. Mayor at the ball of your chain.","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-10-003","lineIndex":3,"speaker":"","original":"Avant de dire un mot de plus Javert","ipa":"/avɑ̃ də diʁ œ̃ mo də ply ʒavɛʁ/","zh":"沙威，在你再说一句之前","en":"Before saying another word Javert","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-10-004","lineIndex":4,"speaker":"","original":"Avant de m'enchaîner encore comme un esclave","ipa":"/avɑ̃ də mɑ̃ʃɛne ɑ̃kɔʁ kɔm œ̃n ɛsklav/","zh":"在再次像奴隶一样束缚我之前","en":"Before chaining me again like a slave","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-10-005","lineIndex":5,"speaker":"","original":"Écoute-moi bien. Accorde-moi une faveur.","ipa":"/ekutmwa bjɛ̃ akɔʁdmwa yn favœʁ/","zh":"仔细听我说。帮我一个忙。","en":"Listen to me carefully. Do me a favor.","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-10-006","lineIndex":6,"speaker":"","original":"Cette femme est morte","ipa":"/sɛt fam ɛ mɔʁt/","zh":"这个女人死了","en":"This woman is dead","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-10-007","lineIndex":7,"speaker":"","original":"Laissant une petite fille malade","ipa":"/lɛsɑ̃ yn pətit fij malad/","zh":"留下一个生病的小女孩","en":"Leaving a sick little girl","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-10-008","lineIndex":8,"speaker":"","original":"Et j'ai juré de lui porter secours.","ipa":"/e ʒe ʒyʁe də lɥi pɔʁte səkuʁ/","zh":"我发誓要去救她。","en":"And I swore to help her.","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-10-009","lineIndex":9,"speaker":"","original":"Au nom du ciel!","ipa":"/o nɔ̃ dy sjɛl/","zh":"以天堂之名！","en":"In the name of heaven!","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-10-010","lineIndex":10,"speaker":"","original":"J'ai besoin de trois jours.","ipa":"/ʒe bəzwɛ̃ də tʁwa ʒuʁ/","zh":"我需要三天。","en":"I need three days.","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-10-011","lineIndex":11,"speaker":"","original":"Je reviendrai. Tu as ma parole, je reviendrai.","ipa":"/ʒə ʁəvjɛ̃dʁe ty a ma paʁɔl ʒə ʁəvjɛ̃dʁe/","zh":"我会回来的。我向你保证，我会回来的。","en":"I will come back. You have my word, I will come back.","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-10-012","lineIndex":12,"speaker":"","original":"Parole de forçat!","ipa":"/paʁɔl də fɔʁsa/","zh":"罪犯的话！","en":"Convict's word!","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-10-013","lineIndex":13,"speaker":"","original":"Je t'ai traqué au long des années;","ipa":"/ʒə te tʁake o lɔ̃ dez ane/","zh":"这些年来我一直在跟踪你；","en":"I have stalked you throughout the years;","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-10-014","lineIndex":14,"speaker":"","original":"Un homme comme toi ne change pas","ipa":"/œ̃n ɔm kɔm twa nə ʃɑ̃ʒ pa/","zh":"像你这样的人不会改变","en":"A man like you doesn't change","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-10-015","lineIndex":15,"speaker":"","original":"Ne changera jamais.","ipa":"/nə ʃɑ̃ʒʁa ʒamɛ/","zh":"永远不会改变。","en":"Will never change.","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-10-016","lineIndex":16,"speaker":"","original":"Pense de moi ce que tu veux","ipa":"/pɑ̃s də mwa sə kə ty vø/","zh":"你爱怎么看我都行","en":"Think of me what you want","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-10-017","lineIndex":17,"speaker":"","original":"C'est une promesse","ipa":"/sɛt yn pʁomɛs/","zh":"这是一个承诺","en":"It's a promise","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-10-018","lineIndex":18,"speaker":"","original":"Que j'ai faite à une mourante.","ipa":"/kə ʒe fɛt a yn muʁɑ̃t/","zh":"是我向一个垂死的女人许下的。","en":"That I did to a dying woman.","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-10-019","lineIndex":19,"speaker":"","original":"Tu ne sais rien de ma vie","ipa":"/ty nə sɛ ʁjɛ̃ də ma vi/","zh":"你对我的生活一无所知","en":"You know nothing about my life","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-10-020","lineIndex":20,"speaker":"","original":"J'ai volé un bout de pain.","ipa":"/ʒe vole œ̃ bu də pɛ̃/","zh":"我偷了一块面包。","en":"I stole a piece of bread.","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-10-021","lineIndex":21,"speaker":"","original":"Tu ne sais rien de ce monde","ipa":"/ty nə sɛ ʁjɛ̃ də sə mɔ̃d/","zh":"你对这个世界一无所知","en":"You know nothing about this world","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-10-022","lineIndex":22,"speaker":"","original":"Ce n'est pas tout mal ou bien.","ipa":"/sə nɛ pa tu mal u bjɛ̃/","zh":"世间并非只有善与恶。","en":"It's not all bad or good.","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-10-023","lineIndex":23,"speaker":"","original":"Rien ne m'empêchera de faire mon devoir.","ipa":"/ʁiɛ̃ nə mɑ̃pɛʃʁa də fɛʁ mɔ̃ dəvwaʁ/","zh":"没有什么可以阻止我履行我的职责。","en":"Nothing will stop me from doing my duty.","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-10-024","lineIndex":24,"speaker":"","original":"Oui, je t'avertis Javert:","ipa":"/wi ʒə tavɛʁti ʒavɛʁ/","zh":"是的，我警告你沙威：","en":"Yes, I warn you Javert:","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-10-025","lineIndex":25,"speaker":"","original":"Je suis bien plus fort que toi.","ipa":"/ʒə sɥi bjɛ̃ ply fɔʁ kə twa/","zh":"我比你强多了。","en":"I am much stronger than you.","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-10-026","lineIndex":26,"speaker":"","original":"Je sais ce que je dois faire","ipa":"/ʒə sɛ sə kə ʒə dwa fɛʁ/","zh":"我知道我必须做什么","en":"I know what I have to do","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-10-027","lineIndex":27,"speaker":"","original":"Si tu t'opposes à moi.","ipa":"/si ty tɔpozz a mwa/","zh":"如果你反对我。","en":"If you oppose me.","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-10-028","lineIndex":28,"speaker":"","original":"Oui, je t'avertis Javert:","ipa":"/wi ʒə tavɛʁti ʒavɛʁ/","zh":"是的，我警告你沙威：","en":"Yes, I warn you Javert:","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-10-029","lineIndex":29,"speaker":"","original":"Même si je dois te tuer","ipa":"/mɛm si ʒə dwa tə tye/","zh":"就算我必须杀了你","en":"Even if I have to kill you","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-10-030","lineIndex":30,"speaker":"","original":"Nul ne m'empêchera de faire","ipa":"/nyl nə mɑ̃pɛʃʁa də fɛʁ/","zh":"没有人能阻止我","en":"No one will stop me from doing","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-10-031","lineIndex":31,"speaker":"","original":"Et jusqu'au bout, mon devoir.","ipa":"/e ʒysko bu mɔ̃ dəvwaʁ/","zh":"把我的职责履行到底。","en":"And until the end, my duty.","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-10-032","lineIndex":32,"speaker":"","original":"Les hommes comme moi ne changent pas","ipa":"/lez ɔm kɔm mwa nə ʃɑ̃ʒ pa/","zh":"像我这样的人不会改变","en":"Men like me don't change","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-10-033","lineIndex":33,"speaker":"","original":"Pas plus que les hommes comme toi.","ipa":"/pa ply kə lez ɔm kɔm twa/","zh":"只不过是像你这样的男人而已。","en":"No more than men like you.","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-10-034","lineIndex":34,"speaker":"","original":"Non, 24-601","ipa":"/nɔ̃ vɛ̃tkatʁ sisɑ̃ œ̃/","zh":"不，24-601","en":"No, 24-601","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-10-035","lineIndex":35,"speaker":"","original":"C'est moi qui sers la loi","ipa":"/sɛ mwa ki sɛʁ la lwa/","zh":"为法律服务的是我","en":"It's me who serves the law","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-10-036","lineIndex":36,"speaker":"","original":"Et le bon droit!","ipa":"/e lə bɔ̃ dʁwa/","zh":"也捍卫正义！","en":"And the right!","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-10-037","lineIndex":37,"speaker":"","original":"Je t'arrête, 24-601!","ipa":"/ʒə taʁɛt vɛ̃tkatʁ sisɑ̃ œ̃/","zh":"我会逮捕你，24-601！","en":"I'll arrest you, 24-601!","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-10-038","lineIndex":38,"speaker":"","original":"Maintenant ta chance a tourné","ipa":"/mɛ̃tnɑ̃ ta ʃɑ̃s a tuʁne/","zh":"现在你的运气变了","en":"Now your luck has changed","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-10-039","lineIndex":39,"speaker":"","original":"Jean Valjean est retrouvé.","ipa":"/ʒɑ̃ valʒɑ̃ ɛ ʁətʁuve/","zh":"冉阿让被发现。","en":"Jean Valjean is found.","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-10-040","lineIndex":40,"speaker":"","original":"Tu oses me parler de crime","ipa":"/ty oz mə paʁle də kʁim/","zh":"你竟然敢跟我谈论犯罪","en":"You dare to talk to me about crime","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-10-041","lineIndex":41,"speaker":"","original":"Et du prix qu'il faut payer.","ipa":"/e dy pʁi kil fo pɛje/","zh":"以及必须付出的代价。","en":"And the price that must be paid.","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-10-042","lineIndex":42,"speaker":"","original":"Chaque homme doit choisir sa voie","ipa":"/ʃak ɔm dwa ʃwaziʁ sa vwa/","zh":"每个人都必须选择自己的道路","en":"Each man must choose his path","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-10-043","lineIndex":43,"speaker":"","original":"Même s'il naît dans le péché.","ipa":"/mɛm sil nɛ dɑ̃ lə peʃe/","zh":"即使他生来就有罪。","en":"Even if he is born in sin.","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-10-044","lineIndex":44,"speaker":"","original":"Tu ne sais rien de Javert.","ipa":"/ty nə sɛ ʁjɛ̃ də ʒavɛʁ/","zh":"你对沙威一无所知。","en":"You don't know anything about Javert.","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-10-045","lineIndex":45,"speaker":"","original":"Je suis né dans une cellule","ipa":"/ʒə sɥi ne dɑ̃z yn sɛlyl/","zh":"我生在一间牢房里","en":"I was born in a cell","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-10-046","lineIndex":46,"speaker":"","original":"Parmi des déchets comme toi","ipa":"/paʁmi de deʃɛ kɔm twa/","zh":"在你这类垃圾之中","en":"Among trash like you","note":"","sourceLineIndex":46},{"id":"les-miserables-cityprod-2017-10-047","lineIndex":47,"speaker":"","original":"Entouré de hors la loi.","ipa":"/ɑ̃tuʁe də ɔʁ la lwa/","zh":"周围都是不法之徒。","en":"Surrounded by outlaws.","note":"","sourceLineIndex":47},{"id":"les-miserables-cityprod-2017-10-048","lineIndex":48,"speaker":"","original":"Je jure sur tout ce qui m'est cher.","ipa":"/ʒə ʒyʁ syʁ tu sə ki mɛ ʃɛʁ/","zh":"我以我所珍视的一切发誓。","en":"I swear on everything that is dear to me.","note":"","sourceLineIndex":48},{"id":"les-miserables-cityprod-2017-10-049","lineIndex":49,"speaker":"","original":"Tu ne m'échapperas plus jamais.","ipa":"/ty nə meʃapʁa ply ʒamɛ/","zh":"你再也不会逃离我了。","en":"You will never escape me again.","note":"","sourceLineIndex":49},{"id":"les-miserables-cityprod-2017-10-050","lineIndex":50,"speaker":"","original":"Cosette aura bientôt un père.","ipa":"/kozɛt oʁa bjɛ̃to œ̃ pɛʁ/","zh":"珂赛特很快就会有父亲了。","en":"Cosette will soon have a father.","note":"","sourceLineIndex":50},{"id":"les-miserables-cityprod-2017-10-051","lineIndex":51,"speaker":"","original":"Où que tu sois, je serai là.","ipa":"/u kə ty swa ʒə səʁe la/","zh":"无论你在哪里，我都会在那里。","en":"Wherever you are, I will be there.","note":"","sourceLineIndex":51},{"id":"les-miserables-cityprod-2017-10-052","lineIndex":52,"speaker":"","original":"Cosette n'aura que du bonheur.","ipa":"/kozɛt noʁa kə dy bɔnœʁ/","zh":"珂赛特只会幸福。","en":"Cosette will only be happy.","note":"","sourceLineIndex":52},{"id":"les-miserables-cityprod-2017-10-053","lineIndex":53,"speaker":"","original":"Je serai la, je te le jure!","ipa":"/ʒə səʁe la ʒə tə lə ʒyʁ/","zh":"我会在那里，我发誓！","en":"I'll be there, I swear!","note":"","sourceLineIndex":53}],"sourceOrder":10,"displayOrder":9},{"order":11,"id":"11-une-poupee-dans-la-vitrine","title":"Une poupée dans la vitrine","titleZh":"橱窗里的玩偶","lines":[{"id":"les-miserables-cityprod-2017-11-001","lineIndex":1,"speaker":"","original":"C'est une poupée dans la vitrine","ipa":"/sɛt yn pupe dɑ̃ la vitʁin/","zh":"橱窗里有个玩偶","en":"It's a doll in the window","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-11-002","lineIndex":2,"speaker":"","original":"Qui me regarde et qui s'ennuie.","ipa":"/ki mə ʁəɡaʁd e ki sɑ̃nɥi/","zh":"她望着我，也显得无聊。","en":"Who looks at me and is bored.","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-11-003","lineIndex":3,"speaker":"","original":"Je crois qu'elle se cherche une maman","ipa":"/ʒə kʁwa kɛl sə ʃɛʁʃ yn mamɑ̃/","zh":"我认为她正在寻找母亲","en":"I think she's looking for a mother","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-11-004","lineIndex":4,"speaker":"","original":"Et moi je veux qu'elle soit ma fille","ipa":"/e mwa ʒə vø kɛl swa ma fij/","zh":"我希望她成为我的女儿","en":"And I want her to be my daughter","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-11-005","lineIndex":5,"speaker":"","original":"Dans une maison pleine de jouets","ipa":"/dɑ̃z yn mɛzɔ̃ plɛn də ʒwɛ/","zh":"在一个装满玩具的房子里","en":"In a house full of toys","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-11-006","lineIndex":6,"speaker":"","original":"Où les petites filles de mon âge","ipa":"/u le pətit fij də mɔ̃n aʒ/","zh":"和我同龄的小女孩们","en":"Where little girls my age","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-11-007","lineIndex":7,"speaker":"","original":"Cousent les toilettes de leurs poupées","ipa":"/kuz le twalɛt də lœʁ pupe/","zh":"给玩偶缝制衣裳","en":"Sew their dolls' toilets","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-11-008","lineIndex":8,"speaker":"","original":"Et ne font jamais le ménage.","ipa":"/e nə fɔ̃ ʒamɛ lə menaʒ/","zh":"从不用做家务。","en":"And they never clean.","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-11-009","lineIndex":9,"speaker":"","original":"Je la vêtirai de dentelles","ipa":"/ʒə la vɛtiʁe də dɑ̃tɛl/","zh":"我会给她穿上蕾丝衣服","en":"I will dress her in lace","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-11-010","lineIndex":10,"speaker":"","original":"Elle aura des jupons de soie.","ipa":"/ɛl oʁa de ʒypɔ̃ də swa/","zh":"她会有丝绸衬裙。","en":"She will have silk petticoats.","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-11-011","lineIndex":11,"speaker":"","original":"Je veux que ma fille soit la plus belle","ipa":"/ʒə vø kə ma fij swa la ply bɛl/","zh":"我希望我的女儿是最美丽的","en":"I want my daughter to be the most beautiful","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-11-012","lineIndex":12,"speaker":"","original":"Et qu'elle soit fière","ipa":"/e kɛl swa fjɛʁ/","zh":"并让她感到骄傲","en":"And let her be proud","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-11-013","lineIndex":13,"speaker":"","original":"Qu'elle soit très fière de moi.","ipa":"/kɛl swa tʁɛ fjɛʁ də mwa/","zh":"愿她为我感到骄傲。","en":"May she be very proud of me.","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-11-014","lineIndex":14,"speaker":"","original":"C'est une poupée dans la vitrine;","ipa":"/sɛt yn pupe dɑ̃ la vitʁin/","zh":"这是橱窗里的一个娃娃；","en":"It's a doll in the window;","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-11-015","lineIndex":15,"speaker":"","original":"Je la regarde et elle m'appelle.","ipa":"/ʒə la ʁəɡaʁd e ɛl mapɛl/","zh":"我看着她，她在呼唤我。","en":"I look at her and she calls me.","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-11-016","lineIndex":16,"speaker":"","original":"Si seulement je savais écrire...","ipa":"/si sølmɑ̃ ʒə savɛz ekʁiʁ/","zh":"要是我知道怎么写就好了……","en":"If only I knew how to write...","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-11-017","lineIndex":17,"speaker":"","original":"Je la demanderais au Père Noël.","ipa":"/ʒə la dəmɑ̃dʁɛz o pɛʁ nɔɛl/","zh":"我会向圣诞老人求她。","en":"I would ask Santa Claus for it.","note":"","sourceLineIndex":17}],"sourceOrder":11,"displayOrder":10},{"order":12,"id":"12-maitre-thenardier","title":"Maître Thénardier","titleZh":"德纳第先生","lines":[{"id":"les-miserables-cityprod-2017-12-001","lineIndex":1,"speaker":"","original":"Entrez, monsieur","ipa":"/ɑ̃tʁe məsjø/","zh":"进来吧，先生","en":"Come in, sir","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-12-002","lineIndex":2,"speaker":"","original":"Vous tombez pile:","ipa":"/vu tɔ̃be pil/","zh":"您来得正好：","en":"You fall right:","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-12-003","lineIndex":3,"speaker":"","original":"Je sers le meilleur","ipa":"/ʒə sɛʁ lə mɛjœʁ/","zh":"我这儿供应全城最好的","en":"I serve the best","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-12-004","lineIndex":4,"speaker":"","original":"Casse-graine de la ville.","ipa":"/kasɡʁɛn də la vil/","zh":"吃食。","en":"City bust.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-12-005","lineIndex":5,"speaker":"","original":"Mes concurrents","ipa":"/me kɔ̃kyʁɑ̃/","zh":"我的竞争对手","en":"My competitors","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-12-006","lineIndex":6,"speaker":"","original":"Sont des fumistes","ipa":"/sɔ̃ de fymist/","zh":"都是些吹牛的骗子","en":"Are smokers","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-12-007","lineIndex":7,"speaker":"","original":"Ou des faisans","ipa":"/u de fəzɑ̃/","zh":"或者江湖老千","en":"Or pheasants","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-12-008","lineIndex":8,"speaker":"","original":"Qui arnaquent le touriste.","ipa":"/ki aʁnak lə tuʁist/","zh":"专骗外地客。","en":"Who scam the tourist.","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-12-009","lineIndex":9,"speaker":"","original":"Ça court pas les rues","ipa":"/sa kuʁ pa le ʁy/","zh":"他们不上街","en":"They don't run the streets","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-12-010","lineIndex":10,"speaker":"","original":"Les vrais, les balaises","ipa":"/le vʁɛ le balɛz/","zh":"真正有本事的","en":"The real ones, the brooms","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-12-011","lineIndex":11,"speaker":"","original":"Qui sont fiers de servir","ipa":"/ki sɔ̃ fjɛʁ də sɛʁviʁ/","zh":"谁为服务而自豪","en":"Who are proud to serve","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-12-012","lineIndex":12,"speaker":"","original":"L'hôtellerie française.","ipa":"/lotɛlʁi fʁɑ̃sɛz/","zh":"法国酒店业。","en":"The French hotel industry.","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-12-013","lineIndex":13,"speaker":"","original":"Maître Thénardier pige en un clin d’œil","ipa":"/mɛtʁ tenaʁdje piʒ ɑ̃n œ̃ klɛ̃ dœj/","zh":"德纳第先生一眼就能看穿","en":"Maître Thénardier gets it done in the blink of an eye","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-12-014","lineIndex":14,"speaker":"","original":"Le genre du client et le poids du portefeuille.","ipa":"/lə ʒɑ̃ʁ dy kliɑ̃ e lə pwa dy pɔʁtəfœj/","zh":"顾客是什么路数，全看钱包的分量。","en":"The type of customer, and the weight of the wallet.","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-12-015","lineIndex":15,"speaker":"","original":"Je les déboutonne","ipa":"/ʒə le debutɔn/","zh":"我用荤笑话撬开他们的钱包","en":"I unbutton them","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-12-016","lineIndex":16,"speaker":"","original":"D'une histoire cochonne:","ipa":"/dyn istwaʁ koʃɔn/","zh":"靠一段下流故事：","en":"From a dirty story:","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-12-017","lineIndex":17,"speaker":"","original":"Plus ils se bidonnent","ipa":"/plyz il sə bidɔn/","zh":"他们笑得越欢","en":"The more they mess around","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-12-018","lineIndex":18,"speaker":"","original":"Et plus il biberonnent.","ipa":"/e plyz il bibʁɔn/","zh":"酒就喝得越多。","en":"And the more they bottle.","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-12-019","lineIndex":19,"speaker":"","original":"Je me rancarde sur leurs problèmes","ipa":"/ʒə mə ʁɑ̃kaʁd syʁ lœʁ pʁɔblɛm/","zh":"我摸清他们的难处","en":"I resent their problems","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-12-020","lineIndex":20,"speaker":"","original":"C'est que dalle de faire semblant.","ipa":"/sɛ kə dal də fɛʁ sɑ̃blɑ̃/","zh":"装模作样根本不费事。","en":"It's a shame to pretend.","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-12-021","lineIndex":21,"speaker":"","original":"Mais on n'a rien pour peau de balle","ipa":"/mɛz ɔ̃ na ʁjɛ̃ puʁ po də bal/","zh":"但这点小情分可一文不值","en":"But we don't have anything to worry about","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-12-022","lineIndex":22,"speaker":"","original":"Et je leur facture un supplément.","ipa":"/e ʒə lœʁ faktyʁ œ̃ syplemɑ̃/","zh":"我还向他们收取额外费用。","en":"And I charge them extra.","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-12-023","lineIndex":23,"speaker":"","original":"Maître du manège, cocher du carrosse","ipa":"/mɛtʁ dy manɛʒ koʃe dy kaʁɔs/","zh":"旋转木马的主人，马车的车夫","en":"Master of the carousel, coachman of the carriage","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-12-024","lineIndex":24,"speaker":"","original":"Je leur chauffe la braise qui brûle au fond de leurs poches.","ipa":"/ʒə lœʁ ʃof la bʁɛz ki bʁyl o fɔ̃ də lœʁ poʃ/","zh":"我把他们口袋深处的钱都烫出来。","en":"I heat them the embers that burn at the bottom of their pockets.","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-12-025","lineIndex":25,"speaker":"","original":"Je leur sers un junglard qui tape sur l'enclume","ipa":"/ʒə lœʁ sɛʁz œ̃ ʒœ̃ɡlaʁ ki tap syʁ lɑ̃klym/","zh":"我端上一道硬得像铁砧、能把人牙齿硌坏的菜","en":"I serve them a junglard that hits the anvil","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-12-026","lineIndex":26,"speaker":"","original":"Et je gaule leurs bibelots quand ils ont chaud aux plumes.","ipa":"/e ʒə ɡol lœʁ biblo kɑ̃t ilz ɔ̃ ʃo o plym/","zh":"等他们酒意上头，我再顺走他们的小玩意儿。","en":"And I spoil their trinkets when they're feeling hot.","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-12-027","lineIndex":27,"speaker":"","original":"Pour la vie, on est compères, frères de lait, frères de flacon;","ipa":"/puʁ la vi ɔ̃n ɛ kɔ̃pɛʁ fʁɛʁ də lɛ fʁɛʁ də flakɔ̃/","zh":"一生中，我们是朋友、养兄弟、瓶子兄弟；","en":"For life, we are friends, foster brothers, bottle brothers;","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-12-028","lineIndex":28,"speaker":"","original":"Mais ils l'ont dans le baigneur, Seigneur! je les entube jusqu'au trognon.","ipa":"/mɛz il lɔ̃ dɑ̃ lə bɛnjœʁ sɛnjœʁ ʒə lez ɑ̃tyb ʒysko tʁonjɔ̃/","zh":"但愿上帝保佑，他们早被我从头骗到尾！","en":"But they have it in the bather, Lord! I suck them up to the core.","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-12-029","lineIndex":29,"speaker":"","original":"Maître Thénardier est un bon chrétien","ipa":"/mɛtʁ tenaʁdje ɛt œ̃ bɔ̃ kʁetjɛ̃/","zh":"德纳第先生是个好基督徒","en":"Master Thénardier is a good Christian","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-12-030","lineIndex":30,"speaker":"","original":"Qui passe tout son temps à servir son prochain.","ipa":"/ki pas tu sɔ̃ tɑ̃ a sɛʁviʁ sɔ̃ pʁoʃɛ̃/","zh":"他把所有的时间都花在为邻居服务上。","en":"Who spends all his time serving his neighbor.","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-12-031","lineIndex":31,"speaker":"","original":"Il crèche les manants, il lèche les seigneurs","ipa":"/il kʁɛʃ le manɑ̃ il lɛʃ le sɛnjœʁ/","zh":"他收留穷汉，逢迎老爷","en":"He licks the lords, he licks the lords","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-12-032","lineIndex":32,"speaker":"","original":"Réconforte et philosophe avec son cœur.","ipa":"/ʁekɔ̃fɔʁt e filozɔf avɛk sɔ̃ kœʁ/","zh":"还用一颗“真心”安慰人、讲哲理。","en":"Comforts and philosophizes with your heart.","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-12-033","lineIndex":33,"speaker":"","original":"Le compagnon de tout le monde, l'ami cher et attentif.","ipa":"/lə kɔ̃panjɔ̃ də tulmɔ̃d lami ʃɛʁ e atɑ̃tif/","zh":"人人的伙伴，体贴又亲切的朋友。","en":"Everyone's companion, dear and attentive friend.","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-12-034","lineIndex":34,"speaker":"","original":"Mais gare à vos tiroirs ce soir, je vais vous écorcher vif!","ipa":"/mɛ ɡaʁ a vo tiʁwaʁ sə swaʁ ʒə vɛ vuz ekɔʁʃe vif/","zh":"但今晚要小心你的抽屉，我要活剥你的皮！","en":"But watch out for your drawers tonight, I'm going to skin you alive!","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-12-035","lineIndex":35,"speaker":"","original":"Entrez, monsieur, la route donne soif;","ipa":"/ɑ̃tʁe məsjø la ʁut dɔn swaf/","zh":"请进，先生，赶路总会口渴；","en":"Come in, sir, the road makes you thirsty;","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-12-036","lineIndex":36,"speaker":"","original":"Ouvrez vos bottes, moi, j'ouvre un carafe.","ipa":"/uvʁe vo bɔt mwa ʒuvʁ œ̃ kaʁaf/","zh":"您脱靴子，我来开酒壶。","en":"Open your boots, I'll open a carafe.","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-12-037","lineIndex":37,"speaker":"","original":"Ce sac d'une tonne retarde votre course","ipa":"/sə sak dyn tɔn ʁətaʁd votʁ kuʁs/","zh":"这个一吨重的袋子会耽误你的跑步","en":"This one-ton bag delays your run","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-12-038","lineIndex":38,"speaker":"","original":"Moi je m'efforce d'alléger votre bourse.","ipa":"/mwa ʒə mefɔʁs daleʒe votʁ buʁs/","zh":"我正在努力减轻你的钱包负担。","en":"I am trying to lighten your purse.","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-12-039","lineIndex":39,"speaker":"","original":"La dinde est bien cuite, le gras dégouline","ipa":"/la dɛ̃d ɛ bjɛ̃ kɥit lə ɡʁa deɡulin/","zh":"火鸡煮得很好，油脂在滴落","en":"The turkey is well cooked, the fat is dripping","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-12-040","lineIndex":40,"speaker":"","original":"Et j'ai le carreau sur tout ce qui sort de ma cuisine.","ipa":"/e ʒe lə kaʁo syʁ tu sə ki sɔʁ də ma kɥizin/","zh":"我对厨房端出的每一样东西都收钱。","en":"And I'm worried about everything that comes out of my kitchen.","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-12-041","lineIndex":41,"speaker":"","original":"Je sers tous les restes, le vieux fait du neuf:","ipa":"/ʒə sɛʁ tu le ʁɛst lə vjø fɛ dy nœf/","zh":"我把所有的剩菜都端上来，旧的变成新的：","en":"I'm serving up all the leftovers, old makes new:","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-12-042","lineIndex":42,"speaker":"","original":"Passées au hachoir, mes bidoches sont \"pur bœuf\".","ipa":"/pasez o aʃwaʁ me bidoʃ sɔ̃ pyʁ bœf/","zh":"过了绞肉机，杂碎肉也成了“纯牛肉”。","en":"Passed through the mincer, my bidoches are “pure beef”.","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-12-043","lineIndex":43,"speaker":"","original":"Les rognons du chat, la vessie de génisse","ipa":"/le ʁonjɔ̃ dy ʃa la vɛsi də ʒenis/","zh":"猫的肾脏、小母牛的膀胱、","en":"The cat's kidneys, the heifer's bladder","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-12-044","lineIndex":44,"speaker":"","original":"Tout est bon, tout glisse fourré dans une saucisse.","ipa":"/tut ɛ bɔ̃ tu ɡlis fuʁe dɑ̃z yn sosis/","zh":"一切都很好，一切都塞进香肠里。","en":"Everything is good, everything slides stuffed into a sausage.","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-12-045","lineIndex":45,"speaker":"","original":"On fait la pension complète, nos suites sont prises à l'année","ipa":"/ɔ̃ fɛ la pɑ̃sjɔ̃ kɔ̃plɛt no sɥit sɔ̃ pʁizz a lane/","zh":"我们包吃包住，套房全年都订满了","en":"We do full board, our suites are taken all year round","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-12-046","lineIndex":46,"speaker":"","original":"À des prix raisonnables plus... les surprises et les petits à-côtés.","ipa":"/a de pʁi ʁɛzɔnabl ply le syʁpʁizz e le pətiz akote/","zh":"价格合理，还有惊喜和额外的东西。","en":"At reasonable prices plus... surprises and little extras.","note":"","sourceLineIndex":46},{"id":"les-miserables-cityprod-2017-12-047","lineIndex":47,"speaker":"","original":"Je facture les puces, les rats, les cafards.","ipa":"/ʒə faktyʁ le pys le ʁa le kafaʁ/","zh":"跳蚤、老鼠、蟑螂，也都得另收费。","en":"I charge for fleas, rats, cockroaches.","note":"","sourceLineIndex":47},{"id":"les-miserables-cityprod-2017-12-048","lineIndex":48,"speaker":"","original":"Je compte de combien leur ombre use le miroir.","ipa":"/ʒə kɔ̃t də kɔ̃bjɛ̃ lœʁ ɔ̃bʁ yz lə miʁwaʁ/","zh":"连他们照镜子磨损的那点镜面，我都计费。","en":"I count how much their shadow wears the mirror.","note":"","sourceLineIndex":48},{"id":"les-miserables-cityprod-2017-12-049","lineIndex":49,"speaker":"","original":"Avant leur départ, j'ajoute la valeur","ipa":"/avɑ̃ lœʁ depaʁ ʒaʒut la valœʁ/","zh":"在他们离开之前，我添加了价值","en":"Before they leave, I add the value","note":"","sourceLineIndex":49},{"id":"les-miserables-cityprod-2017-12-050","lineIndex":50,"speaker":"","original":"Des mouches que leur clebs a gobées dans le secteur.","ipa":"/de muʃ kə lœʁ klɛbz a ɡobe dɑ̃ lə sɛktœʁ/","zh":"连他们那条狗在店里吞掉的苍蝇，也要算进账单。","en":"Flies that their dogs have swallowed in the area.","note":"","sourceLineIndex":50},{"id":"les-miserables-cityprod-2017-12-051","lineIndex":51,"speaker":"","original":"On a tous nos petites ruses quand vient l'heure de l'addition.","ipa":"/ɔ̃n a tu no pətit ʁyz kɑ̃ vjɛ̃ lœʁ də ladisjɔ̃/","zh":"到了结账的时候，我们都有自己的小技巧。","en":"We all have our little tricks when it comes time for the bill.","note":"","sourceLineIndex":51},{"id":"les-miserables-cityprod-2017-12-052","lineIndex":52,"speaker":"","original":"Avec tout ce qu'ils sifflent, pendant qu'y s'empiffrent","ipa":"/avɛk tu sə kil sifl pɑ̃dɑ̃ ki sɑ̃pifʁ/","zh":"尽管他们一边吹口哨，一边填饱肚子","en":"With all that they whistle, while they stuff themselves","note":"","sourceLineIndex":52},{"id":"les-miserables-cityprod-2017-12-053","lineIndex":53,"speaker":"","original":"Les chiffres montent et montent jusqu'au plafond.","ipa":"/le ʃifʁ mɔ̃tt e mɔ̃t ʒysko plafɔ̃/","zh":"数字不断上升，直至达到天花板。","en":"The numbers go up and up to the ceiling.","note":"","sourceLineIndex":53},{"id":"les-miserables-cityprod-2017-12-054","lineIndex":54,"speaker":"","original":"Maître Thénardier est un bon chrétien","ipa":"/mɛtʁ tenaʁdje ɛt œ̃ bɔ̃ kʁetjɛ̃/","zh":"德纳第大师是一位虔诚的基督徒","en":"Master Thénardier is a good Christian","note":"","sourceLineIndex":54},{"id":"les-miserables-cityprod-2017-12-055","lineIndex":55,"speaker":"","original":"Qui passe tout son temps à servir son prochain.","ipa":"/ki pas tu sɔ̃ tɑ̃ a sɛʁviʁ sɔ̃ pʁoʃɛ̃/","zh":"他把所有的时间都花在为邻居服务上。","en":"Who spends all his time serving his neighbor.","note":"","sourceLineIndex":55},{"id":"les-miserables-cityprod-2017-12-056","lineIndex":56,"speaker":"","original":"Il crèche les manants, il lèche les seigneurs","ipa":"/il kʁɛʃ le manɑ̃ il lɛʃ le sɛnjœʁ/","zh":"他收留穷汉，逢迎老爷","en":"He licks the lords, he licks the lords","note":"","sourceLineIndex":56},{"id":"les-miserables-cityprod-2017-12-057","lineIndex":57,"speaker":"","original":"Réconforte et philosophe avec son cœur.","ipa":"/ʁekɔ̃fɔʁt e filozɔf avɛk sɔ̃ kœʁ/","zh":"还用一颗“真心”安慰人、讲哲理。","en":"Comforts and philosophizes with your heart.","note":"","sourceLineIndex":57},{"id":"les-miserables-cityprod-2017-12-058","lineIndex":58,"speaker":"","original":"Le compagnon de tout le monde, le copain toujours présent.","ipa":"/lə kɔ̃panjɔ̃ də tulmɔ̃d lə kopɛ̃ tuʒuʁ pʁezɑ̃/","zh":"每个人的伴侣，永远存在的朋友。","en":"Everyone's companion, the ever-present friend.","note":"","sourceLineIndex":58},{"id":"les-miserables-cityprod-2017-12-059","lineIndex":59,"speaker":"","original":"Ils sont si convaincus, ces cons, qu'y se cassent en me remerciant.","ipa":"/il sɔ̃ si kɔ̃vɛ̃ky se kɔ̃ ki sə kast ɑ̃ mə ʁəmɛʁsjɑ̃/","zh":"那帮傻子深信不疑，走时还要谢我。","en":"They are so convinced, these idiots, that they give up and thank me.","note":"","sourceLineIndex":59},{"id":"les-miserables-cityprod-2017-12-060","lineIndex":60,"speaker":"","original":"Moi qui priais le ciel pour pas vieillir toute seule","ipa":"/mwa ki pʁiɛ lə sjɛl puʁ pa vjɛjiʁ tut sœl/","zh":"祈求上天不要独自变老的我","en":"I who prayed to heaven not to grow old alone","note":"","sourceLineIndex":60},{"id":"les-miserables-cityprod-2017-12-061","lineIndex":61,"speaker":"","original":"Y'a des soirs ou je me dis que j'aurais mieux fait.. de fermer ma gueule...","ipa":"/ja de swaʁ u ʒə mə di kə ʒoʁɛ mjø fɛ də fɛʁme ma ɡœl/","zh":"有些夜晚我会想：当初还不如闭嘴……","en":"There are evenings when I tell myself that I would have done better... to shut my mouth...","note":"","sourceLineIndex":61},{"id":"les-miserables-cityprod-2017-12-062","lineIndex":62,"speaker":"","original":"Maître Thénardier valait pas que je gaspille","ipa":"/mɛtʁ tenaʁdje valɛ pa kə ʒə ɡaspij/","zh":"德纳第不值得我为他耗尽","en":"Maître Thénardier was not worth me wasting","note":"","sourceLineIndex":62},{"id":"les-miserables-cityprod-2017-12-063","lineIndex":63,"speaker":"","original":"Ma vertu et mes plus belles années de jeune fille.","ipa":"/ma vɛʁty e me ply bɛlz ane də ʒøn fij/","zh":"我的美德和我作为少女最美丽的岁月。","en":"My virtue and my most beautiful years as a young girl.","note":"","sourceLineIndex":63},{"id":"les-miserables-cityprod-2017-12-064","lineIndex":64,"speaker":"","original":"Il promet la lune mais comme tous les hommes","ipa":"/il pʁomɛ la lyn mɛ kɔm tu lez ɔm/","zh":"他许下海口，可跟所有男人一样","en":"He promises the moon but like all men","note":"","sourceLineIndex":64},{"id":"les-miserables-cityprod-2017-12-065","lineIndex":65,"speaker":"","original":"Quand vient le soir au lit ma fille y'a plus personne.","ipa":"/kɑ̃ vjɛ̃ lə swaʁ o li ma fij ja ply pɛʁsɔn/","zh":"可一到夜里上床，他就不见人影了，姑娘。","en":"When the evening comes to bed my daughter there is no one left.","note":"","sourceLineIndex":65},{"id":"les-miserables-cityprod-2017-12-066","lineIndex":66,"speaker":"","original":"Y se prend pour Dieu le Père","ipa":"/i sə pʁɑ̃ puʁ djø lə pɛʁ/","zh":"他认为他是天父上帝","en":"He thinks he is God the Father","note":"","sourceLineIndex":66},{"id":"les-miserables-cityprod-2017-12-067","lineIndex":67,"speaker":"","original":"Toujours bourré comme une oie;","ipa":"/tuʒuʁ buʁe kɔm yn wa/","zh":"整天醉得像只鹅；","en":"Always stuffed like a goose;","note":"","sourceLineIndex":67},{"id":"les-miserables-cityprod-2017-12-068","lineIndex":68,"speaker":"","original":"Je vous jure que quand je vais me le faire","ipa":"/ʒə vu ʒyʁ kə kɑ̃ ʒə vɛ mə lə fɛʁ/","zh":"我发誓，等我收拾他的时候","en":"I swear to you that when I'm going to do it to myself","note":"","sourceLineIndex":68},{"id":"les-miserables-cityprod-2017-12-069","lineIndex":69,"speaker":"","original":"Y va ressembler à du foie gras.","ipa":"/i va ʁəsɑ̃ble a dy fwa ɡʁa/","zh":"他会被我揍成一团鹅肝。","en":"It will look like foie gras.","note":"","sourceLineIndex":69},{"id":"les-miserables-cityprod-2017-12-070","lineIndex":70,"speaker":"","original":"Maître Thénardier","ipa":"/mɛtʁ tenaʁdje/","zh":"德纳迪埃大师","en":"Master Thénardier","note":"","sourceLineIndex":70},{"id":"les-miserables-cityprod-2017-12-071","lineIndex":71,"speaker":"","original":"Maître feignardier","ipa":"/mɛtʁ fɛnjaʁdje/","zh":"偷懒大师","en":"Master slacker","note":"","sourceLineIndex":71},{"id":"les-miserables-cityprod-2017-12-072","lineIndex":72,"speaker":"","original":"Réconforte et philosophe.","ipa":"/ʁekɔ̃fɔʁt e filozɔf/","zh":"安慰人、讲哲理。","en":"Comforting and philosophical.","note":"","sourceLineIndex":72},{"id":"les-miserables-cityprod-2017-12-073","lineIndex":73,"speaker":"","original":"Y'a que moi qui bosse.","ipa":"/ja kə mwa ki bɔs/","zh":"只有我一个人在工作。","en":"It's only me who works.","note":"","sourceLineIndex":73},{"id":"les-miserables-cityprod-2017-12-074","lineIndex":74,"speaker":"","original":"Ami sans malice, compagnon d'ivresse","ipa":"/ami sɑ̃ malis kɔ̃panjɔ̃ divʁɛs/","zh":"无恶意的朋友，醉酒的伴侣","en":"Friend without malice, companion of drunkenness","note":"","sourceLineIndex":74},{"id":"les-miserables-cityprod-2017-12-075","lineIndex":75,"speaker":"","original":"Hypocrite, menteur et mari de justesse.","ipa":"/ipɔkʁit mɑ̃tœʁ e maʁi də ʒystɛs/","zh":"伪君子、骗子，一个勉强算得上丈夫的男人。","en":"Hypocrite, liar and narrow husband.","note":"","sourceLineIndex":75},{"id":"les-miserables-cityprod-2017-12-076","lineIndex":76,"speaker":"","original":"À la santé de l'aubergiste, buvons au cabaretier.","ipa":"/a la sɑ̃te də lobɛʁʒist byvɔ̃z o kabaʁətje/","zh":"为客栈老板干杯，也为酒馆老板干杯！","en":"To the health of the innkeeper, let's drink to the innkeeper.","note":"","sourceLineIndex":76},{"id":"les-miserables-cityprod-2017-12-077","lineIndex":77,"speaker":"","original":"Encore une petite timbale!","ipa":"/ɑ̃kɔʁ yn pətit tɛ̃bal/","zh":"再来一小杯！","en":"Another little thing!","note":"","sourceLineIndex":77},{"id":"les-miserables-cityprod-2017-12-078","lineIndex":78,"speaker":"","original":"Qu'y se la mette dans le trou de balle!","ipa":"/ki sə la mɛt dɑ̃ lə tʁu də bal/","zh":"让他把这杯塞进屁股里去！","en":"Let's put it in the bullet hole!","note":"","sourceLineIndex":78},{"id":"les-miserables-cityprod-2017-12-079","lineIndex":79,"speaker":"","original":"Buvons tous à la santé de notre maître Thénardier!","ipa":"/byvɔ̃ tus a la sɑ̃te də notʁ mɛtʁ tenaʁdje/","zh":"大家为我们的德纳第先生干杯！","en":"Let us all drink to the health of our master Thénardier!","note":"","sourceLineIndex":79}],"sourceOrder":12,"displayOrder":11},{"order":13,"id":"13-la-transaction","title":"La transaction","titleZh":"交易","lines":[{"id":"les-miserables-cityprod-2017-13-001","lineIndex":1,"speaker":"","original":"Oui, monsieur, bon monsieur","ipa":"/wi məsjø bɔ̃ məsjø/","zh":"是的，先生，好先生","en":"Yes, sir, good sir","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-13-002","lineIndex":2,"speaker":"","original":"Vous venez nous enlever Cosette;","ipa":"/vu vəne nuz ɑ̃lve kozɛt/","zh":"你是来把珂赛特从我们身边带走的；","en":"You have come to take Cosette from us;","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-13-003","lineIndex":3,"speaker":"","original":"Ce diamant, ce saphir","ipa":"/sə djamɑ̃ sə safiʁ/","zh":"这颗钻石，这颗蓝宝石","en":"This diamond, this sapphire","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-13-004","lineIndex":4,"speaker":"","original":"Qui éclaire nos vies de son sourire.","ipa":"/ki eklɛʁ no vi də sɔ̃ suʁiʁ/","zh":"她的笑容照亮了我们的生活。","en":"Who lights up our lives with her smile.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-13-005","lineIndex":5,"speaker":"","original":"Ne parlons pas de dette","ipa":"/nə paʁlɔ̃ pa də dɛt/","zh":"我们先不谈债务","en":"Let's not talk about debt","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-13-006","lineIndex":6,"speaker":"","original":"Ne marchandons pas notre chère Cosette.","ipa":"/nə maʁʃɑ̃dɔ̃ pa notʁ ʃɛʁ kozɛt/","zh":"我们不要和亲爱的珂赛特讨价还价。","en":"Let's not bargain with our dear Cosette.","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-13-007","lineIndex":7,"speaker":"","original":"Pauvre Fantine, de là-haut","ipa":"/povʁ fɑ̃tin də lao/","zh":"可怜的芳汀，从上面","en":"Poor Fantine, from up there","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-13-008","lineIndex":8,"speaker":"","original":"Tu sais que pour elle rien n'était trop beau.","ipa":"/ty sɛ kə puʁ ɛl ʁiɛ̃ netɛ tʁo bo/","zh":"你知道，对她来说，没有什么是太好的。","en":"You know that for her nothing was too good.","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-13-009","lineIndex":9,"speaker":"","original":"On a tout partagé","ipa":"/ɔ̃n a tu paʁtaʒe/","zh":"我们分享了一切","en":"We shared everything","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-13-010","lineIndex":10,"speaker":"","original":"Tout comme si elle était notre enfant","ipa":"/tu kɔm si ɛl etɛ notʁ ɑ̃fɑ̃/","zh":"就像她是我们的孩子一样","en":"Just as if she were our child","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-13-011","lineIndex":11,"speaker":"","original":"Notre enfant, monsieur!","ipa":"/notʁ ɑ̃fɑ̃ məsjø/","zh":"我们的孩子，先生！","en":"Our child, sir!","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-13-012","lineIndex":12,"speaker":"","original":"Vos bons sentiments vous honorent","ipa":"/vo bɔ̃ sɑ̃timɑ̃ vu onoʁ/","zh":"你的好心令人敬重","en":"Your good feelings honor you","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-13-013","lineIndex":13,"speaker":"","original":"Je vais mettre du baume sur vos plaies.","ipa":"/ʒə vɛ mɛtʁ dy bom syʁ vo plɛ/","zh":"我愿替你抚慰这份伤痛。","en":"I'll put some balm on your wounds.","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-13-014","lineIndex":14,"speaker":"","original":"Oui, cessons là ces marchandages qui nous font honte.","ipa":"/wi sɛsɔ̃ la se maʁʃɑ̃daʒ ki nu fɔ̃ ɔ̃t/","zh":"是的，让我们停止这种让我们感到羞耻的讨价还价吧。","en":"Yes, let's stop this haggling that shames us.","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-13-015","lineIndex":15,"speaker":"","original":"Voilà, dites-moi, y a-t-il le compte?","ipa":"/vwala ditmwa i atil lə kɔ̃t/","zh":"给你，数数看，数目对吗？","en":"There, tell me, is there the account?","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-13-016","lineIndex":16,"speaker":"","original":"Ça irait largement","ipa":"/sa iʁɛ laʁʒəmɑ̃/","zh":"会很顺利","en":"It would go well","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-13-017","lineIndex":17,"speaker":"","original":"Si elle était pas malade si souvent.","ipa":"/si ɛl etɛ pa malad si suvɑ̃/","zh":"如果她不是经常生病就好了。","en":"If she wasn't sick so often.","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-13-018","lineIndex":18,"speaker":"","original":"Les potions coûtaient cher","ipa":"/le posjɔ̃ kutɛ ʃɛʁ/","zh":"药水很贵","en":"Potions were expensive","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-13-019","lineIndex":19,"speaker":"","original":"Sans compter l'angoisse, le désespoir.","ipa":"/sɑ̃ kɔ̃te lɑ̃ɡwas lə dezɛspwaʁ/","zh":"更不用说那种痛苦，那种绝望了。","en":"Not to mention the anguish, the despair.","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-13-020","lineIndex":20,"speaker":"","original":"Mais monsieur, on l'adore:","ipa":"/mɛ məsjø ɔ̃ ladɔʁ/","zh":"可先生，我们真疼爱她：","en":"But sir, we love it:","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-13-021","lineIndex":21,"speaker":"","original":"Bon chrétien fait d'abord son devoir.","ipa":"/bɔ̃ kʁetjɛ̃ fɛ dabɔʁ sɔ̃ dəvwaʁ/","zh":"一个好的基督徒首先尽到他的职责。","en":"A good Christian first does his duty.","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-13-022","lineIndex":22,"speaker":"","original":"Un détail, un dernier:","ipa":"/œ̃ detaj œ̃ dɛʁnje/","zh":"最后一个细节：","en":"One detail, one last:","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-13-023","lineIndex":23,"speaker":"","original":"Dans un monde plein de gens malhonnêtes","ipa":"/dɑ̃z œ̃ mɔ̃d plɛ̃ də ʒɑ̃ malɔnɛt/","zh":"在一个充满不诚实之人的世界里","en":"In a world full of dishonest people","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-13-024","lineIndex":24,"speaker":"","original":"Qui nous dit, qui nous prouve","ipa":"/ki nu di ki nu pʁuv/","zh":"谁告诉我们，谁向我们证明","en":"Who tells us, who proves to us","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-13-025","lineIndex":25,"speaker":"","original":"Que vos intentions sont bien correctes?","ipa":"/kə voz ɛ̃tɑ̃sjɔ̃ sɔ̃ bjɛ̃ koʁɛkt/","zh":"你的意图是正确的吗？","en":"That your intentions are correct?","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-13-026","lineIndex":26,"speaker":"","original":"Prenez ça pour le service:","ipa":"/pʁəne sa puʁ lə sɛʁvis/","zh":"这笔钱算是酬谢你们的照料：","en":"Take this for service:","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-13-027","lineIndex":27,"speaker":"","original":"Quinze cent francs pour vos sacrifices.","ipa":"/kɛ̃z sɑ̃ fʁɑ̃ puʁ vo sakʁifis/","zh":"一千五百法郎，补偿你们的“牺牲”。","en":"Fifteen hundred francs for your sacrifices.","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-13-028","lineIndex":28,"speaker":"","original":"Viens Cosette, dis adieu;","ipa":"/vjɛ̃ kozɛt di adjø/","zh":"来吧，珂赛特，告别；","en":"Come Cosette, say goodbye;","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-13-029","lineIndex":29,"speaker":"","original":"Ton enfance t'attend sous d'autres cieux.","ipa":"/tɔ̃n ɑ̃fɑ̃s tatɑ̃ su dotʁ sjø/","zh":"你的童年在另一个天空下等待着你。","en":"Your childhood awaits you under other skies.","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-13-030","lineIndex":30,"speaker":"","original":"Et vous deux, comptez bien","ipa":"/e vu dø kɔ̃te bjɛ̃/","zh":"你们两个好好数数","en":"And you two, count well","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-13-031","lineIndex":31,"speaker":"","original":"Ça vous fera vite passer votre chagrin.","ipa":"/sa vu fəʁa vit pase votʁ ʃaɡʁɛ̃/","zh":"它会让你很快地度过悲伤。","en":"It will make you pass your sorrow quickly.","note":"","sourceLineIndex":31}],"sourceOrder":13,"displayOrder":12},{"order":14,"id":"14-bonjour-paris","title":"Bonjour Paris","titleZh":"巴黎你好","lines":[{"id":"les-miserables-cityprod-2017-14-001","lineIndex":1,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-14-002","lineIndex":2,"speaker":"","original":"Un sous, un bout de pain.","ipa":"/œ̃ su œ̃ bu də pɛ̃/","zh":"一分钱，一块面包。","en":"A penny, a piece of bread.","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-14-003","lineIndex":3,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-14-004","lineIndex":4,"speaker":"","original":"Pour tous ceux qui n'ont rien.","ipa":"/puʁ tus sø ki nɔ̃ ʁiɛ̃/","zh":"对于每一个一无所有的人。","en":"For everyone who has nothing.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-14-005","lineIndex":5,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-14-006","lineIndex":6,"speaker":"","original":"Un sous pour vous c'est peu.","ipa":"/œ̃ su puʁ vu sɛ pø/","zh":"一分钱对你来说并不算多。","en":"A penny is not much for you.","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-14-007","lineIndex":7,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-14-008","lineIndex":8,"speaker":"","original":"Vous prêtez au bon Dieu!","ipa":"/vu pʁɛtez o bɔ̃ djø/","zh":"你借给仁慈的主！","en":"You lend to the good Lord!","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-14-009","lineIndex":9,"speaker":"","original":"Bonjour Paris, c'est moi Gavroche!","ipa":"/bɔ̃ʒuʁ paʁi sɛ mwa ɡavʁɔʃ/","zh":"你好巴黎，我是加弗罗什！","en":"Hello Paris, it’s me Gavroche!","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-14-010","lineIndex":10,"speaker":"","original":"Je suis plus un mioche, qu'on se le dise.","ipa":"/ʒə sɥi plyz œ̃ mjɔʃ kɔ̃ sə lə diz/","zh":"可以这么说，我不再是一个小孩子了。","en":"I'm no longer a brat, let it be said.","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-14-011","lineIndex":11,"speaker":"","original":"Je vis dans la rue avec les cloches;","ipa":"/ʒə vi dɑ̃ la ʁy avɛk le kloʃ/","zh":"我跟流浪汉一起住在街头；","en":"I live in the street with the bells;","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-14-012","lineIndex":12,"speaker":"","original":"Je vais ni à l'école, ni à l'église","ipa":"/ʒə vɛ ni a lekɔl ni a leɡliz/","zh":"我不去学校也不去教堂","en":"I don't go to school or church","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-14-013","lineIndex":13,"speaker":"","original":"J'ai pas de blé, mais je me fais pas de bile:","ipa":"/ʒe pa də ble mɛ ʒə mə fɛ pa də bil/","zh":"我没钱，可我不发愁：","en":"I don't have any wheat, but I don't worry:","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-14-014","lineIndex":14,"speaker":"","original":"Y'a de l'oseille dans tout Paris.","ipa":"/ja də lozɛj dɑ̃ tu paʁi/","zh":"巴黎到处都有钱可捞。","en":"There's sorrel all over Paris.","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-14-015","lineIndex":15,"speaker":"","original":"Ici, tu sais, chacun fait son persil;","ipa":"/isi ty sɛ ʃakœ̃ fɛ sɔ̃ pɛʁsil/","zh":"在这儿，人人都自己想法子赚钱；","en":"Here, you know, everyone makes their own parsley;","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-14-016","lineIndex":16,"speaker":"","original":"Un jour on fauche, l'autre on mendie.","ipa":"/œ̃ ʒuʁ ɔ̃ foʃ lotʁ ɔ̃ mɑ̃di/","zh":"今天顺手牵羊，明天沿街乞讨。","en":"One day we mow, the other we beg.","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-14-017","lineIndex":17,"speaker":"","original":"On est libres, on décide. Suivez-moi, suivez le guide!","ipa":"/ɔ̃n ɛ libʁ ɔ̃ desid sɥivemwa sɥive lə ɡid/","zh":"我们自由，我们自己作主。跟着我，跟着向导走！","en":"We are free, we decide. Follow me, follow the guide!","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-14-018","lineIndex":18,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-14-019","lineIndex":19,"speaker":"","original":"Un sous, un bout de pain.","ipa":"/œ̃ su œ̃ bu də pɛ̃/","zh":"一分钱，一块面包。","en":"A penny, a piece of bread.","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-14-020","lineIndex":20,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-14-021","lineIndex":21,"speaker":"","original":"Pour tous ceux qui n'ont rien.","ipa":"/puʁ tus sø ki nɔ̃ ʁiɛ̃/","zh":"对于每一个一无所有的人。","en":"For everyone who has nothing.","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-14-022","lineIndex":22,"speaker":"","original":"Où est-ce que tu te crois?","ipa":"/u ɛs kə ty tə kʁwa/","zh":"你认为你在哪里？","en":"Where do you think you are?","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-14-023","lineIndex":23,"speaker":"","original":"C'est chacune sa gâche.","ipa":"/sɛ ʃakyn sa ɡaʃ/","zh":"这儿各人顾各人的营生。","en":"It’s each their own waste.","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-14-024","lineIndex":24,"speaker":"","original":"Si tu es nouvelle, ici","ipa":"/si ty ɛ nuvɛl isi/","zh":"如果你是新来的","en":"If you're new here","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-14-025","lineIndex":25,"speaker":"","original":"Y'a pas de place pour toi!","ipa":"/ja pa də plas puʁ twa/","zh":"没有你的空间了！","en":"There's no room for you!","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-14-026","lineIndex":26,"speaker":"","original":"Écoute, vielle sorcière!","ipa":"/ekut vjɛl sɔʁsjɛʁ/","zh":"听着，老巫婆！","en":"Listen, old witch!","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-14-027","lineIndex":27,"speaker":"","original":"Écoute, vielle chouette!","ipa":"/ekut vjɛl ʃwɛt/","zh":"听着，老猫头鹰！","en":"Listen, old owl!","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-14-028","lineIndex":28,"speaker":"","original":"Moi je donne au moins","ipa":"/mwa ʒə dɔn o mwɛ̃/","zh":"我至少给","en":"I at least give","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-14-029","lineIndex":29,"speaker":"","original":"Un peu de plaisir à qui m'achète.","ipa":"/œ̃ pø də plɛziʁ a ki maʃɛt/","zh":"买我的人都会感到一点高兴。","en":"A little pleasure to whoever buys me.","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-14-030","lineIndex":30,"speaker":"","original":"Ce que tu donnes surtout","ipa":"/sə kə ty dɔn syʁtu/","zh":"最重要的是你所给予的","en":"What you give above all","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-14-031","lineIndex":31,"speaker":"","original":"C'est la petite vérole","ipa":"/sɛ la pətit veʁɔl/","zh":"这是天花","en":"It's smallpox","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-14-032","lineIndex":32,"speaker":"","original":"Que tu colles de l'un à l'autre","ipa":"/kə ty kɔl də lœ̃n a lotʁ/","zh":"你从这个人传给那个人","en":"That you stick from one to the other","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-14-033","lineIndex":33,"speaker":"","original":"Des gnasses que tu racoles.","ipa":"/de njas kə ty ʁakol/","zh":"你招徕的那些女人。","en":"The chicks you are soliciting.","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-14-034","lineIndex":34,"speaker":"","original":"Lâche cette vieille guenon! L'a le grelot qui grince!","ipa":"/laʃ sɛt vjɛj ɡənɔ̃ la lə ɡʁəlo ki ɡʁɛ̃s/","zh":"放开这个老猴精！她那破嗓子都哑了！","en":"Let go of this old monkey! The bell is squeaking!","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-14-035","lineIndex":35,"speaker":"","original":"Elle fait plus un rond depuis qu'elle a chopé la chaude-pince.","ipa":"/ɛl fɛ plyz œ̃ ʁɔ̃ dəpɥi kɛl a ʃope la ʃodpɛ̃s/","zh":"自从染上脏病，她就一个钱也挣不到了。","en":"She's been moving more and more since she got the hot rod.","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-14-036","lineIndex":36,"speaker":"","original":"Quand est-ce qu'on croquera un bout du gâteau?","ipa":"/kɑ̃t ɛs kɔ̃ kʁokʁa œ̃ bu dy ɡato/","zh":"什么时候也让我们分一块蛋糕？","en":"When will we eat a piece of the cake?","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-14-037","lineIndex":37,"speaker":"","original":"Faudra qu'y partagent un beau jour parce que trop c'est trop!","ipa":"/fodʁa ki paʁtaʒt œ̃ bo ʒuʁ paʁskə tʁo sɛ tʁo/","zh":"总有一天他们得拿出来分，因为我们受够了！","en":"We'll have to share it one fine day because enough is enough!","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-14-038","lineIndex":38,"speaker":"","original":"Ça viendra, ça viendra, ça viendra","ipa":"/sa vjɛ̃dʁa sa vjɛ̃dʁa sa vjɛ̃dʁa/","zh":"那一天会来的，会来的，会来的","en":"It will come, it will come, it will come","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-14-039","lineIndex":39,"speaker":"","original":"Ça viendra, ça viendra, ça viendra.","ipa":"/sa vjɛ̃dʁa sa vjɛ̃dʁa sa vjɛ̃dʁa/","zh":"该来的，该来的，该来的。","en":"It will come, it will come, it will come.","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-14-040","lineIndex":40,"speaker":"","original":"Heureusement que chez les gens de la haute, y en a un qui regarde en bas.","ipa":"/øʁøzmɑ̃ kə ʃe le ʒɑ̃ də la ot i ɑ̃n a œ̃ ki ʁəɡaʁd ɑ̃ ba/","zh":"幸好，上流人里还有一个肯低头看看下面。","en":"Fortunately, among the people at the top, there is one who looks down.","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-14-041","lineIndex":41,"speaker":"","original":"Un seul, le général Lamarque, la voix de ceux qui n'en ont pas.","ipa":"/œ̃ sœl lə ʒeneʁal lamaʁk la vwa də sø ki nɑ̃n ɔ̃ pa/","zh":"只有拉马克将军，是无声者的声音。","en":"Only one, General Lamarque, the voice of those who do not have one.","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-14-042","lineIndex":42,"speaker":"","original":"Briffer nos moutards, crécher sous un toit;","ipa":"/bʁife no mutaʁ kʁeʃe suz œ̃ twa/","zh":"让孩子吃饱，能在屋檐下安身；","en":"Sniff our kids, sleep under a roof;","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-14-043","lineIndex":43,"speaker":"","original":"Et si Dieu le veut, enfin ne plus crever de froid.","ipa":"/e si djø lə vø ɑ̃fɛ̃ nə ply kʁəve də fʁwa/","zh":"若上天垂怜，终于不必再冻死。","en":"And God willing, finally no longer die of cold.","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-14-044","lineIndex":44,"speaker":"","original":"Par le nom du seigneur.","ipa":"/paʁ lə nɔ̃ dy sɛnjœʁ/","zh":"以主之名。","en":"By the name of the lord.","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-14-045","lineIndex":45,"speaker":"","original":"En son nom","ipa":"/ɑ̃ sɔ̃ nɔ̃/","zh":"以他的名义","en":"In his name","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-14-046","lineIndex":46,"speaker":"","original":"En son nom","ipa":"/ɑ̃ sɔ̃ nɔ̃/","zh":"以他的名义","en":"In his name","note":"","sourceLineIndex":46},{"id":"les-miserables-cityprod-2017-14-047","lineIndex":47,"speaker":"","original":"En son nom.","ipa":"/ɑ̃ sɔ̃ nɔ̃/","zh":"以他的名义。","en":"In his name.","note":"","sourceLineIndex":47},{"id":"les-miserables-cityprod-2017-14-048","lineIndex":48,"speaker":"","original":"Lamarque s'éteint; il est malade; il n'en a plus pour très longtemps.","ipa":"/lamaʁk setɛ̃ il ɛ malad il nɑ̃n a ply puʁ tʁɛ lɔ̃tɑ̃/","zh":"拉马克将军正在衰竭；他病得很重，时日无多。","en":"Lamarque goes out; he is ill; He doesn't have much longer.","note":"","sourceLineIndex":48},{"id":"les-miserables-cityprod-2017-14-049","lineIndex":49,"speaker":"","original":"Avec l'émeute déjà qui gronde, Paris ressemble à un volcan","ipa":"/avɛk lemøt deʒa ki ɡʁɔ̃d paʁi ʁəsɑ̃bl a œ̃ vɔlkɑ̃/","zh":"骚乱已经酝酿，巴黎看起来就像一座火山","en":"With the riot already brewing, Paris looks like a volcano","note":"","sourceLineIndex":49},{"id":"les-miserables-cityprod-2017-14-050","lineIndex":50,"speaker":"","original":"Prêt à vomir la lave de sa colère","ipa":"/pʁɛ a vomiʁ la lav də sa kolɛʁ/","zh":"随时要喷出愤怒的熔岩","en":"Ready to vomit the lava of his anger","note":"","sourceLineIndex":50},{"id":"les-miserables-cityprod-2017-14-051","lineIndex":51,"speaker":"","original":"Enfin révolutionnaire.","ipa":"/ɑ̃fɛ̃ ʁevolysjɔnɛʁ/","zh":"化作革命的火山。","en":"Finally, a revolutionary.","note":"","sourceLineIndex":51},{"id":"les-miserables-cityprod-2017-14-052","lineIndex":52,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":52},{"id":"les-miserables-cityprod-2017-14-053","lineIndex":53,"speaker":"","original":"Un sous, un bout de pain.","ipa":"/œ̃ su œ̃ bu də pɛ̃/","zh":"一分钱，一块面包。","en":"A penny, a piece of bread.","note":"","sourceLineIndex":53},{"id":"les-miserables-cityprod-2017-14-054","lineIndex":54,"speaker":"","original":"Pitié, pitié","ipa":"/pitje pitje/","zh":"怜悯啊，怜悯啊","en":"Pity, pity","note":"","sourceLineIndex":54},{"id":"les-miserables-cityprod-2017-14-055","lineIndex":55,"speaker":"","original":"Pour ceux qui n'ont plus rien.","ipa":"/puʁ sø ki nɔ̃ ply ʁjɛ̃/","zh":"对于那些一无所有的人。","en":"For those who have nothing left.","note":"","sourceLineIndex":55}],"sourceOrder":14,"displayOrder":13},{"order":15,"id":"15-sous-les-etoiles","title":"Sous les étoiles","titleZh":"星空下","lines":[{"id":"les-miserables-cityprod-2017-15-001","lineIndex":1,"speaker":"","original":"Noir, plus noir que la nuit","ipa":"/nwaʁ ply nwaʁ kə la nɥi/","zh":"黑，比黑夜还黑","en":"Black, blacker than the night","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-15-002","lineIndex":2,"speaker":"","original":"Est cet homme qui s'enfuit","ipa":"/ɛ sɛt ɔm ki sɑ̃fyi/","zh":"正是这个逃跑的男人。","en":"Is this man who runs away","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-15-003","lineIndex":3,"speaker":"","original":"Sous les étoiles.","ipa":"/su lez etwal/","zh":"星空下。","en":"Under the stars.","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-15-004","lineIndex":4,"speaker":"","original":"Sous les étoiles","ipa":"/su lez etwal/","zh":"星空下","en":"Under the stars","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-15-005","lineIndex":5,"speaker":"","original":"Dieu m'en soit témoin:","ipa":"/djø mɑ̃ swa temwɛ̃/","zh":"愿上帝为我作证：","en":"God be my witness:","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-15-006","lineIndex":6,"speaker":"","original":"Je ne faiblirai point","ipa":"/ʒə nə fɛbliʁe pwɛ̃/","zh":"我绝不会退缩","en":"I will not weaken","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-15-007","lineIndex":7,"speaker":"","original":"Tant qu'il ne sera pas","ipa":"/tɑ̃ kil nə səʁa pa/","zh":"除非他已","en":"As long as it is not","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-15-008","lineIndex":8,"speaker":"","original":"À genoux devant moi.","ipa":"/a ʒənu dəvɑ̃ mwa/","zh":"跪在我面前。","en":"On your knees in front of me.","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-15-009","lineIndex":9,"speaker":"","original":"Il suit la voie du démon","ipa":"/il sɥi la vwa dy demɔ̃/","zh":"他追随魔鬼的道路","en":"He follows the path of the devil","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-15-010","lineIndex":10,"speaker":"","original":"Et moi, au nom du Seigneur","ipa":"/e mwa o nɔ̃ dy sɛnjœʁ/","zh":"而我，以主的名义","en":"And I, in the name of the Lord","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-15-011","lineIndex":11,"speaker":"","original":"Je fais resplendir l'ordre en plein azur","ipa":"/ʒə fɛ ʁɛsplɑ̃diʁ lɔʁdʁ ɑ̃ plɛ̃n azyʁ/","zh":"我要让秩序在青天之下闪耀","en":"I make order shine in the blue","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-15-012","lineIndex":12,"speaker":"","original":"En pleine lumière.","ipa":"/ɑ̃ plɛn lymjɛʁ/","zh":"在光天化日之中。","en":"In full light.","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-15-013","lineIndex":13,"speaker":"","original":"Pour ceux qui sombrent","ipa":"/puʁ sø ki sɔ̃bʁ/","zh":"对于那些沉沦的人","en":"For those who sink","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-15-014","lineIndex":14,"speaker":"","original":"Avec Lucifer","ipa":"/avɛk lysife/","zh":"与路西法一起","en":"With Lucifer","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-15-015","lineIndex":15,"speaker":"","original":"Les flammes, l'enfer.","ipa":"/le flam lɑ̃fɛʁ/","zh":"火焰，地狱。","en":"The flames, hell.","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-15-016","lineIndex":16,"speaker":"","original":"Pures, dans leur multitude","ipa":"/pyʁ dɑ̃ lœʁ myltityd/","zh":"无数纯净的星辰","en":"Pure, in their multitude","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-15-017","lineIndex":17,"speaker":"","original":"Régnent les étoiles","ipa":"/ʁenj lez etwal/","zh":"在天际主宰一切","en":"The stars reign","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-15-018","lineIndex":18,"speaker":"","original":"Soldats de l'ombre.","ipa":"/sɔlda də lɔ̃bʁ/","zh":"影子士兵。","en":"Shadow soldiers.","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-15-019","lineIndex":19,"speaker":"","original":"Postées dans l'espace","ipa":"/pɔste dɑ̃ lɛspas/","zh":"守望在苍穹中","en":"Posted in space","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-15-020","lineIndex":20,"speaker":"","original":"Vous êtes les sentinelles","ipa":"/vuz ɛt le sɑ̃tinɛl/","zh":"你们是哨兵","en":"You are the sentinels","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-15-021","lineIndex":21,"speaker":"","original":"Qui nous regardent","ipa":"/ki nu ʁəɡaʁd/","zh":"注视着我们","en":"Who are watching us","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-15-022","lineIndex":22,"speaker":"","original":"Et qui gardent le ciel","ipa":"/e ki ɡaʁd lə sjɛl/","zh":"守卫着天空","en":"And who guard the sky","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-15-023","lineIndex":23,"speaker":"","original":"Et qui gardent le ciel.","ipa":"/e ki ɡaʁd lə sjɛl/","zh":"以及守护天空的人。","en":"And who guard the sky.","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-15-024","lineIndex":24,"speaker":"","original":"Chacune sa place dans la nuit","ipa":"/ʃakyn sa plas dɑ̃ la nɥi/","zh":"每个人在夜晚都有自己的位置","en":"Each has its place in the night","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-15-025","lineIndex":25,"speaker":"","original":"Chacune sa course en silence","ipa":"/ʃakyn sa kuʁs ɑ̃ silɑ̃s/","zh":"每个人都默默地奔跑","en":"Each one runs in silence","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-15-026","lineIndex":26,"speaker":"","original":"Que rien ne peut faire","ipa":"/kə ʁjɛ̃ nə pø fɛʁ/","zh":"没有什么能够令它","en":"That nothing can do","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-15-027","lineIndex":27,"speaker":"","original":"Dévier de son but","ipa":"/devje də sɔ̃ byt/","zh":"偏离既定轨道","en":"Deviate from your goal","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-15-028","lineIndex":28,"speaker":"","original":"De sa vigilance.","ipa":"/də sa viʒilɑ̃s/","zh":"也不能使它松懈警惕。","en":"Of his vigilance.","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-15-029","lineIndex":29,"speaker":"","original":"Pour qui se damne avec Lucifer","ipa":"/puʁ ki sə dan avɛk lysife/","zh":"至于同路西法一道堕入地狱的人","en":"For those who are damned with Lucifer","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-15-030","lineIndex":30,"speaker":"","original":"Les flammes, l'enfer!","ipa":"/le flam lɑ̃fɛʁ/","zh":"火焰，地狱！","en":"Flames, hell!","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-15-031","lineIndex":31,"speaker":"","original":"Ces mots sont inscrits","ipa":"/se mo sɔ̃t ɛ̃skʁi/","zh":"这些话写着","en":"These words are written","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-15-032","lineIndex":32,"speaker":"","original":"À l'encre éternelle","ipa":"/a lɑ̃kʁ etɛʁnɛl/","zh":"用永恒的墨水","en":"With eternal ink","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-15-033","lineIndex":33,"speaker":"","original":"Sur les portes du paradis.","ipa":"/syʁ le pɔʁt dy paʁadi/","zh":"在天堂的大门上。","en":"On the gates of paradise.","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-15-034","lineIndex":34,"speaker":"","original":"Et ceux qui s'égarent","ipa":"/e sø ki seɡaʁ/","zh":"而那些误入歧途的人","en":"And those who go astray","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-15-035","lineIndex":35,"speaker":"","original":"Ceux qui vacillent","ipa":"/sø ki vasij/","zh":"那些动摇的人","en":"Those who waver","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-15-036","lineIndex":36,"speaker":"","original":"Paieront le prix.","ipa":"/pɛʁɔ̃ lə pʁi/","zh":"会付出代价的。","en":"Will pay the price.","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-15-037","lineIndex":37,"speaker":"","original":"Ô Dieu de justice","ipa":"/o djø də ʒystis/","zh":"正义的上帝啊","en":"O God of justice","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-15-038","lineIndex":38,"speaker":"","original":"Montre-moi la voie;","ipa":"/mɔ̃tʁmwa la vwa/","zh":"给我指路；","en":"Show me the way;","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-15-039","lineIndex":39,"speaker":"","original":"Et pour ta gloire","ipa":"/e puʁ ta ɡlwaʁ/","zh":"为了你的荣耀","en":"And for your glory","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-15-040","lineIndex":40,"speaker":"","original":"Je planterai moi-même","ipa":"/ʒə plɑ̃tʁe mwamɛm/","zh":"我会亲手刺下","en":"I will plant myself","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-15-041","lineIndex":41,"speaker":"","original":"Ton glaive, je le jure","ipa":"/tɔ̃ ɡlɛv ʒə lə ʒyʁ/","zh":"你的利剑，我发誓","en":"Your sword, I swear","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-15-042","lineIndex":42,"speaker":"","original":"Je le jure aux étoiles.","ipa":"/ʒə lə ʒyʁ oz etwal/","zh":"我对着星星发誓。","en":"I swear to the stars.","note":"","sourceLineIndex":42}],"sourceOrder":15,"displayOrder":14},{"order":16,"id":"16-le-cafe-des-amis-de-l-abc","title":"Le café des amis de l'abc","titleZh":"ABC 朋友咖啡馆","lines":[{"id":"les-miserables-cityprod-2017-16-001","lineIndex":1,"speaker":"","original":"Enjolras!","ipa":"/ɑ̃ʒɔlʁa/","zh":"安灼拉！","en":"Enjolras!","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-16-002","lineIndex":2,"speaker":"","original":"Au pont au change, toutes les sections s'apprêtent.","ipa":"/o pɔ̃t o ʃɑ̃ʒ tut le sɛksjɔ̃ sapʁɛt/","zh":"换钱桥那边，各个小组都在准备。","en":"At the change bridge, all sections are getting ready.","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-16-003","lineIndex":3,"speaker":"","original":"On se rassemble à la barrière du Maine.","ipa":"/ɔ̃ sə ʁasɑ̃bl a la baʁjɛʁ dy mɛn/","zh":"我们在缅因关卡集合。","en":"We gather at the Maine barrier.","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-16-004","lineIndex":4,"speaker":"","original":"Les sculpteurs, les marbriers brûlent de marcher avec nous.","ipa":"/le skyltœʁ le maʁbʁie bʁyl də maʁʃe avɛk nu/","zh":"雕塑家和大理石工人都渴望与我们同行。","en":"The sculptors and marble workers are eager to walk with us.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-16-005","lineIndex":5,"speaker":"","original":"Et les maçons de Montreuil seront tous au rendez-vous.","ipa":"/e le masɔ̃ də mɔ̃tʁœj səʁɔ̃ tus o ʁɑ̃devu/","zh":"来自蒙特勒伊的泥瓦匠都会在那里。","en":"And the masons from Montreuil will all be there.","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-16-006","lineIndex":6,"speaker":"","original":"Amis, c'est l'heure.","ipa":"/ami sɛ lœʁ/","zh":"朋友们，是时候了。","en":"Friends, it's time.","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-16-007","lineIndex":7,"speaker":"","original":"Si proche que c'est l'ennemi qui s'inquiète.","ipa":"/si pʁɔʃ kə sɛ lɛnmi ki sɛ̃kjɛt/","zh":"我们离得这样近，连敌人都开始不安。","en":"So close that the enemy is the one who worries.","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-16-008","lineIndex":8,"speaker":"","original":"Ne laissons pas","ipa":"/nə lɛsɔ̃ pa/","zh":"别让","en":"Let's not let","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-16-009","lineIndex":9,"speaker":"","original":"Le vin nous monte à la tête.","ipa":"/lə vɛ̃ nu mɔ̃t a la tɛt/","zh":"酒冲昏我们的头脑。","en":"The wine go to our heads.","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-16-010","lineIndex":10,"speaker":"","original":"C'est facile de tirer de l'estrade d'un café Mais les gardes nationaux ont de vrais pistolets.","ipa":"/sɛ fasil də tiʁe də lɛstʁad dœ̃ kafe mɛ le ɡaʁd nasjonoz ɔ̃ də vʁɛ pistolɛ/","zh":"站在咖啡馆的讲台上高谈阔论很容易但国民警卫队拿的是真枪。","en":"It's easy to speak from a café platform but the National Guards have real pistols.","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-16-012","lineIndex":11,"speaker":"","original":"Il faut que la fournaise, qui chauffe dans les esprits","ipa":"/il fo kə la fuʁnɛz ki ʃof dɑ̃ lez ɛspʁi/","zh":"必须让在人心中燃烧的熔炉","en":"The furnace burning in people's minds must","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-16-013","lineIndex":12,"speaker":"","original":"Se répande comme la poudre dans les rues de Paris.","ipa":"/sə ʁepɑ̃d kɔm la pudʁ dɑ̃ le ʁy də paʁi/","zh":"像火药般蔓延到巴黎的街巷。","en":"spread like gunpowder through the streets of Paris.","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-16-014","lineIndex":13,"speaker":"","original":"Le peuple en armes, la vague qui déferle Quand le progrès n'a pas de temps à perdre.","ipa":"/lə pøpl ɑ̃n aʁm la vaɡ ki defɛʁl kɑ̃ lə pʁɔɡʁɛ na pa də tɑ̃ a pɛʁdʁ/","zh":"武装起来的人民，如奔涌的浪潮因为进步不容片刻耽搁。","en":"The people in arms, the surging wave when progress has no time to lose.","note":"","sourceLineIndex":14}],"sourceOrder":16,"displayOrder":15},{"order":17,"id":"17-rouge-la-flamme-de-la-colere","title":"Rouge la flamme de la colère","titleZh":"愤怒的火焰被染红","lines":[{"id":"les-miserables-cityprod-2017-17-001","lineIndex":1,"speaker":"","original":"Tu es en retard!","ipa":"/ty ɛz ɑ̃ ʁətaʁ/","zh":"你迟到了！","en":"You're late!","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-17-002","lineIndex":2,"speaker":"","original":"Qu'est-ce qui t'arrive?","ipa":"/kɛs ki taʁiv/","zh":"你怎么了？","en":"What's happening to you?","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-17-003","lineIndex":3,"speaker":"","original":"Marius, mais tu souris aux anges!","ipa":"/maʁjys mɛ ty suʁi oz ɑ̃ʒ/","zh":"马吕斯，但你正在对天使微笑！","en":"Marius, but you are smiling to the angels!","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-17-004","lineIndex":4,"speaker":"","original":"Bois un coup et dis-nous ce qui va pas.","ipa":"/bwaz œ̃ ku e dinu sə ki va pa/","zh":"喝一杯并告诉我们出了什么问题。","en":"Have a drink and tell us what's wrong.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-17-005","lineIndex":5,"speaker":"","original":"Un ange peut-être! Un ange, dis-tu?","ipa":"/œ̃n ɑ̃ʒ pøtɛtʁ œ̃n ɑ̃ʒ dity/","zh":"也许是天使！你说天使？","en":"An angel perhaps! An angel, you say?","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-17-006","lineIndex":6,"speaker":"","original":"C'était un ange, voilà pourquoi","ipa":"/setɛt œ̃n ɑ̃ʒ vwala puʁkwa/","zh":"那是一位天使，难怪如此","en":"She was an angel, that's why","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-17-007","lineIndex":7,"speaker":"","original":"Sa lumière porte mon âme aux nues.","ipa":"/sa lymjɛʁ pɔʁt mɔ̃n am o ny/","zh":"她的光芒把我的灵魂托上云端。","en":"Her light lifts my soul to the skies.","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-17-008","lineIndex":8,"speaker":"","original":"Je suis sur le cul de ma bouteille","ipa":"/ʒə sɥi syʁ lə ky də ma butɛj/","zh":"我都惊得快坐到酒瓶底了","en":"I'm floored by my bottle","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-17-009","lineIndex":9,"speaker":"","original":"Marius a pris un coup de soleil:","ipa":"/maʁjys a pʁi œ̃ ku də solɛj/","zh":"马吕斯这是中了爱情的“日头”。","en":"Marius has caught the sun:","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-17-010","lineIndex":10,"speaker":"","original":"Il nous sort les violons, ouh la la!","ipa":"/il nu sɔʁ le vjolɔ̃ u la la/","zh":"他都拉起伤感的小提琴了，哎呀！","en":"He's bringing out the violins, oh là là!","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-17-011","lineIndex":11,"speaker":"","original":"Nous on se prépare à l'attaque","ipa":"/nuz ɔ̃ sə pʁepaʁ a latak/","zh":"我们正在准备进攻","en":"We are preparing for the attack","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-17-013","lineIndex":12,"speaker":"Et voilà Don Juan qui débarque","original":"On est mieux ici qu'à l'Opéra.","ipa":"/ɔ̃n ɛ mjø isi ka lopeʁa/","zh":"我们在这里比在歌剧院更好。","en":"We are better here than at the Opera.","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-17-014","lineIndex":13,"speaker":"","original":"L'Opéra est fermé, mais venues des ténèbres D'autres voix vont chanter le grand air d'un pays qui s'enfièvre.","ipa":"/lopeʁa ɛ fɛʁme mɛ vəny de tenɛbʁ dotʁ vwa vɔ̃ ʃɑ̃te lə ɡʁɑ̃t ɛʁ dœ̃ pɛi ki sɑ̃fjɛvʁ/","zh":"歌剧院已经关门，可有声音自黑暗中传来要唱出一个沸腾国家的宏大咏叹。","en":"The Opera is closed, but out of the darkness other voices will sing the grand aria of a country aflame.","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-17-016","lineIndex":14,"speaker":"","original":"Celui qui n'est pas prêt à payer de sa vie Peut retourner se faire choyer dans sa famille.","ipa":"/səlyi ki nɛ pa pʁɛ a pɛje də sa vi pø ʁətuʁne sə fɛʁ ʃwaje dɑ̃ sa famij/","zh":"还没有准备好付出生命代价的人可以回家继续享受家人的娇宠。","en":"The one who is not ready to pay with his life can go back to be pampered by his family.","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-17-018","lineIndex":15,"speaker":"","original":"Amis, l'heure a sonné de reprendre la Bastille.","ipa":"/ami lœʁ a sɔne də ʁəpʁɑ̃dʁ la bastij/","zh":"朋友们，夺回巴士底狱的时候到了。","en":"Friends, the time has come to retake the Bastille.","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-17-019","lineIndex":16,"speaker":"","original":"Rouge - la flamme de la colère","ipa":"/ʁuʒ la flam də la kolɛʁ/","zh":"红色—愤怒的火焰","en":"Red - the flame of anger","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-17-020","lineIndex":17,"speaker":"","original":"Noire - la nuit de l'ignorance","ipa":"/nwaʁ la nɥi də linjoʁɑ̃s/","zh":"黑色—无知的夜晚","en":"Black - the night of ignorance","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-17-021","lineIndex":18,"speaker":"","original":"Rouge - un monde en train de naître","ipa":"/ʁuʒ œ̃ mɔ̃d ɑ̃ tʁɛ̃ də nɛtʁ/","zh":"红色—一个正在诞生的世界","en":"Red - a world being born","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-17-022","lineIndex":19,"speaker":"","original":"Noire - la mort de l'innocence.","ipa":"/nwaʁ la mɔʁ də linosɑ̃s/","zh":"黑色—纯真之死。","en":"Black - the death of innocence.","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-17-023","lineIndex":20,"speaker":"","original":"Ah! Si vous l'aviez vue, vous sauriez la douceur","ipa":"/a si vu lavje vy vu soʁje la dusœʁ/","zh":"啊！若你们见过她，就会明白那种甜美—","en":"Ah! If you had seen her, you would know the sweetness","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-17-024","lineIndex":21,"speaker":"","original":"D'être atteint en plein cœur et sur l'heure de chérir sa blessure.","ipa":"/dɛtʁ atɛ̃ ɑ̃ plɛ̃ kœʁ e syʁ lœʁ də ʃeʁiʁ sa blɛsyʁ/","zh":"被正中内心的那一刻，立刻便珍爱起这道伤。","en":"of being struck in the heart and at once cherishing the wound.","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-17-025","lineIndex":22,"speaker":"","original":"Ah! Si vous l'aviez vue, quand elle m'a regardé","ipa":"/a si vu lavje vy kɑ̃t ɛl ma ʁəɡaʁde/","zh":"啊！如果你见过她，当她看着我时","en":"Ah! If you had seen her, when she looked at me","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-17-026","lineIndex":23,"speaker":"","original":"Vous sauriez que la braise d'un éclair de passion","ipa":"/vu soʁje kə la bʁɛz dœ̃n eklɛʁ də pasjɔ̃/","zh":"你会知道激情一闪的余烬","en":"You would know that the embers of a flash of passion","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-17-027","lineIndex":24,"speaker":"","original":"Peut enflammer le monde comme une révolution.","ipa":"/pøt ɑ̃flame lə mɔ̃d kɔm yn ʁevolysjɔ̃/","zh":"可以像革命一样点燃世界。","en":"Can ignite the world like a revolution.","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-17-028","lineIndex":25,"speaker":"","original":"Rouge -","ipa":"/ʁuʒ/","zh":"红色 -","en":"Red -","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-17-029","lineIndex":26,"speaker":"","original":"Une flamme brûle en mon cœur","ipa":"/yn flam bʁyl ɑ̃ mɔ̃ kœʁ/","zh":"一团火焰在我心中燃烧","en":"A flame burns in my heart","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-17-030","lineIndex":27,"speaker":"","original":"Noir -","ipa":"/nwaʁ/","zh":"黑色 -","en":"Black -","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-17-031","lineIndex":28,"speaker":"","original":"L'enfer d'une heure sans elle","ipa":"/lɑ̃fɛʁ dyn œʁ sɑ̃z ɛl/","zh":"没有她的一小时如同炼狱","en":"The hell of an hour without her","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-17-032","lineIndex":29,"speaker":"","original":"Rouge -","ipa":"/ʁuʒ/","zh":"红色 -","en":"Red -","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-17-033","lineIndex":30,"speaker":"","original":"L'amour en train de naître","ipa":"/lamuʁ ɑ̃ tʁɛ̃ də nɛtʁ/","zh":"爱的诞生","en":"Love being born","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-17-034","lineIndex":31,"speaker":"","original":"Noir -","ipa":"/nwaʁ/","zh":"黑色 -","en":"Black -","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-17-035","lineIndex":32,"speaker":"","original":"La mort d'une étincelle.","ipa":"/la mɔʁ dyn etɛ̃sɛl/","zh":"火花之死。","en":"The death of a spark.","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-17-036","lineIndex":33,"speaker":"","original":"Marius, descends de ton nuage, range ton cadeau tombé du ciel;","ipa":"/maʁjys dɛsɑ̃ də tɔ̃ nyaʒ ʁɑ̃ʒ tɔ̃ kado tɔ̃be dy sjɛl/","zh":"马吕斯，从云端下来，先收起这份天赐的礼物；","en":"Marius, come down from your cloud; put away your gift fallen from heaven.","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-17-037","lineIndex":34,"speaker":"","original":"Écoute la voix qui nous appelle. Fais patienter ton petit cœur;","ipa":"/ekut la vwa ki nuz apɛl fɛ pasjɑ̃te tɔ̃ pəti kœʁ/","zh":"听听那召唤我们的声音。让你那颗小心暂且等一等；","en":"Listen to the voice calling us. Make your little heart wait;","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-17-038","lineIndex":35,"speaker":"","original":"C'est pour une grande cause qu'on se bat","ipa":"/sɛ puʁ yn ɡʁɑ̃d koz kɔ̃ sə ba/","zh":"我们是为了伟大的事业而奋斗","en":"It is for a great cause that we are fighting","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-17-039","lineIndex":36,"speaker":"","original":"Et nos petites vies ne comptent pas.","ipa":"/e no pətit vi nə kɔ̃t pa/","zh":"而我们的小命并不重要。","en":"And our little lives don't matter.","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-17-040","lineIndex":37,"speaker":"","original":"Rouge - la flamme de la colère!","ipa":"/ʁuʒ la flam də la kolɛʁ/","zh":"红色—愤怒的火焰！","en":"Red - the flame of anger!","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-17-041","lineIndex":38,"speaker":"","original":"Noire - la nuit de l'ignorance","ipa":"/nwaʁ la nɥi də linjoʁɑ̃s/","zh":"黑色—无知的夜晚","en":"Black - the night of ignorance","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-17-042","lineIndex":39,"speaker":"","original":"Rouge - un monde en train de naître","ipa":"/ʁuʒ œ̃ mɔ̃d ɑ̃ tʁɛ̃ də nɛtʁ/","zh":"红色—一个正在诞生的世界","en":"Red - a world being born","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-17-043","lineIndex":40,"speaker":"","original":"Noire - la mort de l'espérance.","ipa":"/nwaʁ la mɔʁ də lɛspeʁɑ̃s/","zh":"黑色—希望的死亡。","en":"Black - the death of hope.","note":"","sourceLineIndex":43}],"sourceOrder":17,"displayOrder":16},{"order":18,"id":"18-rue-plumet-dans-ma-vie","title":"Rue Plumet: dans ma vie","titleZh":"普吕梅街：在我的生命中","lines":[{"id":"les-miserables-cityprod-2017-18-001","lineIndex":1,"speaker":"COSETTE","original":"C'est drôle! Ce doux frisson qui malgré moi m'agite!","ipa":"/sɛ dʁol sə du fʁisɔ̃ ki malɡʁe mwa maʒit/","zh":"很有趣！这种甜蜜的快感让我不由自主地激动不已！","en":"It's funny! This sweet thrill which, despite myself, agitates me!","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-18-002","lineIndex":2,"speaker":"COSETTE","original":"Tu es folle! On ne tombe pas amoureuse aussi vite!","ipa":"/ty ɛ fɔl ɔ̃ nə tɔ̃b paz amuʁøz osi vit/","zh":"你疯了！你不会那么快坠入爱河！","en":"You are crazy! You don't fall in love that quickly!","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-18-003","lineIndex":3,"speaker":"COSETTE","original":"Qu'est-ce qui t'arrive, enfin, Cosette!","ipa":"/kɛs ki taʁiv ɑ̃fɛ̃ kozɛt/","zh":"珂赛特，你到底怎么了！","en":"What on earth is happening to you, Cosette!","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-18-004","lineIndex":4,"speaker":"COSETTE","original":"Ta solitude te joue des tours.","ipa":"/ta solityd tə ʒu de tuʁ/","zh":"你的孤独在捉弄你。","en":"Your loneliness plays tricks on you.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-18-005","lineIndex":5,"speaker":"COSETTE","original":"Et tu vois des mirages qui ressemblent à l'amour!","ipa":"/e ty vwa de miʁaʒ ki ʁəsɑ̃blt a lamuʁ/","zh":"你会看到看起来像爱情的海市蜃楼！","en":"And you see mirages that look like love!","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-18-006","lineIndex":6,"speaker":"COSETTE","original":"Dans ma vie","ipa":"/dɑ̃ ma vi/","zh":"在我的生活中","en":"In my life","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-18-007","lineIndex":7,"speaker":"COSETTE","original":"Je ne manque de rien, mais il manque quelqu'un qui devine.","ipa":"/ʒə nə mɑ̃k də ʁjɛ̃ mɛz il mɑ̃k kɛlkœ̃ ki dəvin/","zh":"我什么都不缺，却少了一个懂我的人。","en":"I lack nothing, except someone who understands me.","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-18-008","lineIndex":8,"speaker":"COSETTE","original":"Que soudain je ne suis plus la petite fille qui rêvait devant une poupée dans la vitrine.","ipa":"/kə sudɛ̃ ʒə nə sɥi ply la pətit fij ki ʁɛvɛ dəvɑ̃ yn pupe dɑ̃ la vitʁin/","zh":"突然间，我已不再是那个在橱窗前望着洋娃娃做梦的小女孩。","en":"Suddenly, I am no longer the little girl who dreamed before a doll in the shop window.","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-18-009","lineIndex":9,"speaker":"COSETTE","original":"Et j'attends tout d'un prince dont je ne sais rien","ipa":"/e ʒatɑ̃ tu dœ̃ pʁɛ̃s dɔ̃ ʒə nə sɛ ʁjɛ̃/","zh":"我把一切希望寄托在一个我全然不知的王子身上","en":"And I expect everything from a prince I know nothing about","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-18-010","lineIndex":10,"speaker":"COSETTE","original":"Et je rêve de découvrir le monde en prenant sa main.","ipa":"/e ʒə ʁɛv də dekuvʁiʁ lə mɔ̃d ɑ̃ pʁənɑ̃ sa mɛ̃/","zh":"我梦想着牵着他的手去发现世界。","en":"And I dream of discovering the world by taking his hand.","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-18-011","lineIndex":11,"speaker":"COSETTE","original":"Est-ce qu'il sait que j'existe?","ipa":"/ɛs kil sɛ kə ʒɛɡzist/","zh":"他知道我的存在吗？","en":"Does he know I exist?","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-18-012","lineIndex":12,"speaker":"COSETTE","original":"Est-ce qu'il m'a remarquée?","ipa":"/ɛs kil ma ʁəmaʁke/","zh":"他注意到我了吗？","en":"Did he notice me?","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-18-013","lineIndex":13,"speaker":"COSETTE","original":"Ou n'est-il qu'un doux songe et je vais m'éveiller.","ipa":"/u nɛtil kœ̃ du sɔ̃ʒ e ʒə vɛ mevɛje/","zh":"或者这只是一场美梦，我会醒来。","en":"Or is it just a sweet dream and I will wake up.","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-18-014","lineIndex":14,"speaker":"COSETTE","original":"Dans ma vie","ipa":"/dɑ̃ ma vi/","zh":"在我的生活中","en":"In my life","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-18-015","lineIndex":15,"speaker":"COSETTE","original":"Je ne me sens plus seule; J'ai enfin un secret.","ipa":"/ʒə nə mə sɑ̃ ply sœl ʒe ɑ̃fɛ̃ œ̃ səkʁɛ/","zh":"我不再觉得孤单；我终于有了一个秘密。","en":"I no longer feel alone; at last I have a secret.","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-18-016","lineIndex":16,"speaker":"COSETTE","original":"Et je prie","ipa":"/e ʒə pʁi/","zh":"我祈祷","en":"And I pray","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-18-017","lineIndex":17,"speaker":"COSETTE","original":"Pour qu'il vienne dans ma vie.","ipa":"/puʁ kil vjɛn dɑ̃ ma vi/","zh":"让他走进我的生活。","en":"For him to come into my life.","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-18-018","lineIndex":18,"speaker":"JEAN VAL-JEAN","original":"Ma Cosette.","ipa":"/ma kozɛt/","zh":"我的珂赛特。","en":"My Cosette.","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-18-019","lineIndex":19,"speaker":"JEAN VAL-JEAN","original":"Tu rêves d'un autre monde","ipa":"/ty ʁɛv dœ̃n otʁ mɔ̃d/","zh":"你梦想着另一个世界","en":"You dream of another world","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-18-020","lineIndex":20,"speaker":"JEAN VAL-JEAN","original":"Où t'entraînent tes pensées vagabondes.","ipa":"/u tɑ̃tʁɛn te pɑ̃se vaɡabɔ̃d/","zh":"你的游荡思想带你去哪里。","en":"Where your wandering thoughts take you.","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-18-021","lineIndex":21,"speaker":"JEAN VAL-JEAN","original":"Tu dois faire souvent des rêves de voyage","ipa":"/ty dwa fɛʁ suvɑ̃ de ʁɛv də vwajaʒ/","zh":"你一定经常有旅行的梦想","en":"You must often have travel dreams","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-18-022","lineIndex":22,"speaker":"JEAN VAL-JEAN","original":"Comme une colombe mise en cage.","ipa":"/kɔm yn kolɔ̃b miz ɑ̃ kaʒ/","zh":"就像笼中的鸽子一样。","en":"Like a caged dove.","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-18-023","lineIndex":23,"speaker":"JEAN VAL-JEAN","original":"Es-tu lassée d'avoir, ma fille","ipa":"/ɛty lase davwaʁ ma fij/","zh":"我的女儿，你是否厌倦了","en":"Are you tired, my daughter","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-18-024","lineIndex":24,"speaker":"JEAN VAL-JEAN","original":"Ton vieux père pour seule compagnie?","ipa":"/tɔ̃ vjø pɛʁ puʁ sœl kɔ̃pani/","zh":"只有年迈的父亲陪伴在身边？","en":"of having only your old father for company?","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-18-025","lineIndex":25,"speaker":"COSETTE","original":"Je ne sais rien de moi, de l'enfant que j'étais.","ipa":"/ʒə nə sɛ ʁjɛ̃ də mwa də lɑ̃fɑ̃ kə ʒetɛ/","zh":"我对自己一无所知，也不知道自己曾是什么样的孩子。","en":"I know nothing of myself, of the child I used to be.","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-18-026","lineIndex":26,"speaker":"COSETTE","original":"Je vous questionne parfois","ipa":"/ʒə vu kɛstjɔn paʁfwa/","zh":"有时我会问你","en":"I question you sometimes","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-18-027","lineIndex":27,"speaker":"COSETTE","original":"Vous n'en parlez jamais.","ipa":"/vu nɑ̃ paʁle ʒamɛ/","zh":"你从不谈论它。","en":"You never talk about it.","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-18-028","lineIndex":28,"speaker":"COSETTE","original":"Je ne sais rien de vous, si peu de votre vie.","ipa":"/ʒə nə sɛ ʁjɛ̃ də vu si pø də votʁ vi/","zh":"我对你一无所知，对你的生活也知之甚少。","en":"I know nothing about you, so little about your life.","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-18-029","lineIndex":29,"speaker":"COSETTE","original":"Mon père, n'avez-vous pas confiance en votre fille?","ipa":"/mɔ̃ pɛʁ navevu pa kɔ̃fjɑ̃s ɑ̃ votʁ fij/","zh":"爸爸，你不相信你的女儿吗？","en":"Father, don't you trust your daughter?","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-18-030","lineIndex":30,"speaker":"COSETTE","original":"Si sombre en votre cœur","ipa":"/si sɔ̃bʁ ɑ̃ votʁ kœʁ/","zh":"您心里有那么多阴霾","en":"So dark in your heart","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-18-031","lineIndex":31,"speaker":"COSETTE","original":"Vos secrets me font peur!","ipa":"/vo səkʁɛ mə fɔ̃ pœʁ/","zh":"你的秘密让我害怕！","en":"Your secrets scare me!","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-18-032","lineIndex":32,"speaker":"COSETTE","original":"Dans ma vie","ipa":"/dɑ̃ ma vi/","zh":"在我的生活中","en":"In my life","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-18-033","lineIndex":33,"speaker":"COSETTE","original":"Je ne manque de rien;","ipa":"/ʒə nə mɑ̃k də ʁjɛ̃/","zh":"我什么都不缺；","en":"I lack nothing;","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-18-034","lineIndex":34,"speaker":"COSETTE","original":"Vous êtes bon, vous êtes tendre, vous m'aimez.","ipa":"/vuz ɛt bɔ̃ vuz ɛt tɑ̃dʁ vu mɛme/","zh":"你很好，你很温柔，你爱我。","en":"You are good, you are tender, you love me.","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-18-035","lineIndex":35,"speaker":"COSETTE","original":"Mais papa, cher papa","ipa":"/mɛ papa ʃɛʁ papa/","zh":"但是爸爸，亲爱的爸爸","en":"But dad, dear dad","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-18-036","lineIndex":36,"speaker":"COSETTE","original":"Dans vos yeux, je suis toujours l'enfant perdue dans la forêt.","ipa":"/dɑ̃ voz jø ʒə sɥi tuʒuʁ lɑ̃fɑ̃ pɛʁdy dɑ̃ la foʁɛ/","zh":"在你眼里，我依然是那个迷失在森林里的孩子。","en":"In your eyes, I am still the child lost in the forest.","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-18-037","lineIndex":37,"speaker":"JEAN VAL-JEAN","original":"Plus un mot, plus un mot","ipa":"/plyz œ̃ mo plyz œ̃ mo/","zh":"一言不发，一言不发","en":"Not a word, not a word","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-18-038","lineIndex":38,"speaker":"JEAN VAL-JEAN","original":"C'est le passé qui est mort.","ipa":"/sɛ lə pase ki ɛ mɔʁ/","zh":"死去的是过去。","en":"It is the past that is dead.","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-18-039","lineIndex":39,"speaker":"JEAN VAL-JEAN","original":"Aujourd'hui, ces mots-la font trop mal, ils crient trop fort.","ipa":"/oʒuʁdɥi se mola fɔ̃ tʁo mal il kʁi tʁo fɔʁ/","zh":"如今这些字眼太伤人，喊得太响。","en":"Today, those words hurt too much; they cry too loudly.","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-18-040","lineIndex":40,"speaker":"COSETTE","original":"Dans ma vie","ipa":"/dɑ̃ ma vi/","zh":"在我的生活中","en":"In my life","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-18-041","lineIndex":41,"speaker":"COSETTE","original":"Je ne suis plus une enfant et j'attends le bonheur moi aussi","ipa":"/ʒə nə sɥi plyz yn ɑ̃fɑ̃ e ʒatɑ̃ lə bɔnœʁ mwa osi/","zh":"我不再是孩子，我也在等待幸福。","en":"I am no longer a child, and I too await happiness.","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-18-042","lineIndex":42,"speaker":"COSETTE","original":"Le bonheur dans ma vie!","ipa":"/lə bɔnœʁ dɑ̃ ma vi/","zh":"我的生活幸福快乐！","en":"Happiness in my life!","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-18-043","lineIndex":43,"speaker":"JEAN VAL-JEAN","original":"Le bonheur","ipa":"/lə bɔnœʁ/","zh":"幸福","en":"Happiness","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-18-044","lineIndex":44,"speaker":"JEAN VAL-JEAN","original":"C'est un cadeau de Dieu à chacun","ipa":"/sɛt œ̃ kado də djø a ʃakœ̃/","zh":"这是上帝给每个人的礼物","en":"It is a gift from God to everyone","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-18-045","lineIndex":45,"speaker":"JEAN VAL-JEAN","original":"à son heure, à son heure.","ipa":"/a sɔ̃n œʁ a sɔ̃n œʁ/","zh":"在各自该来的时候，在各自该来的时候。","en":"in its own time, in its own time.","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-18-046","lineIndex":46,"speaker":"MARIUS","original":"Dans ma vie","ipa":"/dɑ̃ ma vi/","zh":"在我的生活中","en":"In my life","note":"","sourceLineIndex":46},{"id":"les-miserables-cityprod-2017-18-047","lineIndex":47,"speaker":"MARIUS","original":"Je vois celle que Dieu prit, quand il a fait les anges, pour modèle.","ipa":"/ʒə vwa sɛl kə djø pʁi kɑ̃t il a fɛ lez ɑ̃ʒ puʁ modɛl/","zh":"我看见一个女孩，上帝造天使时曾以她为范本。","en":"I see the one God took as a model when he made the angels.","note":"","sourceLineIndex":47},{"id":"les-miserables-cityprod-2017-18-048","lineIndex":48,"speaker":"MARIUS","original":"Elle est là, devant moi","ipa":"/ɛl ɛ la dəvɑ̃ mwa/","zh":"她就在那里，就在我面前","en":"She is there, in front of me","note":"","sourceLineIndex":48},{"id":"les-miserables-cityprod-2017-18-049","lineIndex":49,"speaker":"MARIUS","original":"Ma princesse au jardin, une rose à la main, irréelle.","ipa":"/ma pʁɛ̃sɛs o ʒaʁdɛ̃ yn ʁɔz a la mɛ̃ iʁeɛl/","zh":"我花园里的公主，手持玫瑰，如梦似幻。","en":"My princess in the garden, a rose in her hand, unreal.","note":"","sourceLineIndex":49},{"id":"les-miserables-cityprod-2017-18-050","lineIndex":50,"speaker":"MARIUS","original":"Éponine, tu es la fée qui nous réunit","ipa":"/eponin ty ɛ la fe ki nu ʁeyni/","zh":"艾潘妮，你是让我们走到一起的仙女。","en":"Éponine, you are the fairy who brings us together","note":"","sourceLineIndex":50},{"id":"les-miserables-cityprod-2017-18-051","lineIndex":51,"speaker":"MARIUS","original":"Et je prie qu'un bonheur comme le mien advienne dans ta vie.","ipa":"/e ʒə pʁi kœ̃ bɔnœʁ kɔm lə mjɛ̃ advjɛn dɑ̃ ta vi/","zh":"我祈祷像我一样的幸福降临到你的生活中。","en":"And I pray that happiness like mine comes to your life.","note":"","sourceLineIndex":51},{"id":"les-miserables-cityprod-2017-18-052","lineIndex":52,"speaker":"MARIUS","original":"Le bon Dieu quelquefois est un grand magicien.","ipa":"/lə bɔ̃ djø kɛlkəfwaz ɛt œ̃ ɡʁɑ̃ maʒisjɛ̃/","zh":"仁慈的主有时也是一位伟大的魔术师。","en":"The good Lord is sometimes a great magician.","note":"","sourceLineIndex":52},{"id":"les-miserables-cityprod-2017-18-053","lineIndex":53,"speaker":"ÉPONINE","original":"Chaque joie dans son cœur met une flèche dans le mien.","ipa":"/ʃak ʒwa dɑ̃ sɔ̃ kœʁ mɛt yn flɛʃ dɑ̃ lə mjɛ̃/","zh":"他心里的每一份喜悦，都像一支箭射进我心里。","en":"Every joy in his heart puts an arrow in mine.","note":"","sourceLineIndex":53},{"id":"les-miserables-cityprod-2017-18-054","lineIndex":54,"speaker":"ÉPONINE","original":"Dans ma vie","ipa":"/dɑ̃ ma vi/","zh":"在我的生活中","en":"In my life","note":"","sourceLineIndex":54},{"id":"les-miserables-cityprod-2017-18-055","lineIndex":55,"speaker":"ÉPONINE","original":"Il n'y aura jamais personne d'autre que lui.","ipa":"/il ni oʁa ʒamɛ pɛʁsɔn dotʁ kə lɥi/","zh":"除了他之外，永远不会有任何人。","en":"There will never be anyone other than him.","note":"","sourceLineIndex":55},{"id":"les-miserables-cityprod-2017-18-056","lineIndex":56,"speaker":"ÉPONINE","original":"S'il voulait je serais toute à lui.","ipa":"/sil vulɛ ʒə səʁɛ tut a lɥi/","zh":"如果他愿意，我就完全属于他了。","en":"If he wanted I would be all his.","note":"","sourceLineIndex":56},{"id":"les-miserables-cityprod-2017-18-057","lineIndex":57,"speaker":"MARIUS&ÉPONINE","original":"Dans ma vie","ipa":"/dɑ̃ ma vi/","zh":"在我的生活中","en":"In my life","note":"","sourceLineIndex":57},{"id":"les-miserables-cityprod-2017-18-058","lineIndex":58,"speaker":"MARIUS&ÉPONINE","original":"il y a quelqu'un qui compte dans ma vie.","ipa":"/il i a kɛlkœ̃ ki kɔ̃t dɑ̃ ma vi/","zh":"有一个人在我的生活中很重要。","en":"there is someone who matters in my life.","note":"","sourceLineIndex":58},{"id":"les-miserables-cityprod-2017-18-059","lineIndex":59,"speaker":"MARIUS","original":"Là, enfin!","ipa":"/la ɑ̃fɛ̃/","zh":"终于到了！","en":"There, finally!","note":"","sourceLineIndex":59},{"id":"les-miserables-cityprod-2017-18-060","lineIndex":60,"speaker":"ÉPONINE","original":"Là, en vain!","ipa":"/la ɑ̃ vɛ̃/","zh":"在那里，徒劳！","en":"There, in vain!","note":"","sourceLineIndex":60}],"sourceOrder":18,"displayOrder":17},{"order":19,"id":"19-le-c-ur-au-bonheur","title":"Le cœur au bonheur","titleZh":"幸福之心","lines":[{"id":"les-miserables-cityprod-2017-19-001","lineIndex":1,"speaker":"COSETTE","original":"Le cœur au bonheur","ipa":"/lə kœʁ o bɔnœʁ/","zh":"心怀幸福","en":"The heart of happiness","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-19-002","lineIndex":2,"speaker":"COSETTE","original":"J'espère et j'ai peur","ipa":"/ʒɛspɛʁ e ʒe pœʁ/","zh":"我既期待又害怕","en":"I hope and I fear","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-19-003","lineIndex":3,"speaker":"COSETTE","original":"Que ces mots fassent mon malheur","ipa":"/kə se mo fas mɔ̃ malœʁ/","zh":"这些话会不会反倒带给我不幸","en":"that these words might bring me unhappiness","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-19-004","lineIndex":4,"speaker":"COSETTE","original":"Et qu'elle me dise","ipa":"/e kɛl mə diz/","zh":"她会不会这样对我说","en":"and that she might tell me","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-19-005","lineIndex":5,"speaker":"COSETTE","original":"Je n'connais même pas votre nom","ipa":"/ʒə nkɔnɛ mɛm pa votʁ nɔ̃/","zh":"“我连您的名字都不知道。”","en":"“I don't even know your name.”","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-19-006","lineIndex":6,"speaker":"COSETTE","original":"Mon Dieu, pardon","ipa":"/mɔ̃ djø paʁdɔ̃/","zh":"天哪，请原谅我","en":"My God, forgive me","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-19-007","lineIndex":7,"speaker":"COSETTE","original":"Excusez ma sottise","ipa":"/ɛkskyze ma sɔtiz/","zh":"请原谅我的傻气。","en":"Excuse my foolishness.","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-19-008","lineIndex":8,"speaker":"COSETTE","original":"Le cœur au bonheur","ipa":"/lə kœʁ o bɔnœʁ/","zh":"幸福满怀","en":"A heart full of happiness","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-19-009","lineIndex":9,"speaker":"COSETTE","original":"J'attendais un prince","ipa":"/ʒatɑ̃dɛz œ̃ pʁɛ̃s/","zh":"我一直在等待一位王子","en":"I was waiting for a prince","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-19-010","lineIndex":10,"speaker":"MARIUS PONTMERCY","original":"Je m'appelle Marius Pontmercy","ipa":"/ʒə mapɛl maʁjys pɔ̃mɛʁsi/","zh":"我的名字是马吕斯·庞梅西","en":"My name is Marius Pontmercy","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-19-011","lineIndex":11,"speaker":"COSETTE","original":"Et moi, Cosette","ipa":"/e mwa kozɛt/","zh":"而我叫珂赛特","en":"And me, Cosette","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-19-012","lineIndex":12,"speaker":"MARIUS PONTMERCY","original":"Je vous aie vu au Luxembourg","ipa":"/ʒə vuz ɛ vy o lyksɑ̃buʁ/","zh":"我曾在卢森堡公园见过您。","en":"I saw you in Luxembourg.","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-19-013","lineIndex":13,"speaker":"COSETTE","original":"Prince d'amour","ipa":"/pʁɛ̃s damuʁ/","zh":"爱情王子","en":"Prince of love","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-19-014","lineIndex":14,"speaker":"MARIUS PONTMERCY","original":"Te voilà, comme en rêve","ipa":"/tə vwala kɔm ɑ̃ ʁɛv/","zh":"你在这里，就像在梦中一样","en":"Here you are, like in a dream","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-19-015","lineIndex":15,"speaker":"MARIUS PONTMERCY","original":"Les anges, quelquefois","ipa":"/lez ɑ̃ʒ kɛlkəfwa/","zh":"天使有时","en":"Angels sometimes","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-19-016","lineIndex":16,"speaker":"MARIUS PONTMERCY","original":"Se rencontrent sur terre","ipa":"/sə ʁɑ̃kɔ̃tʁ syʁ tɛʁ/","zh":"也会在人间相遇。","en":"meet on earth.","note":"","sourceLineIndex":16}],"sourceOrder":19,"displayOrder":18},{"order":20,"id":"20-le-casse-de-la-rue-plumet","title":"Le casse de la rue plumet","titleZh":"普吕梅街的抢劫","lines":[{"id":"les-miserables-cityprod-2017-20-001","lineIndex":1,"speaker":"","original":"Voilà son terrier","ipa":"/vwala sɔ̃ tɛʁje/","zh":"这是他的洞穴","en":"This is his burrow","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-20-002","lineIndex":2,"speaker":"","original":"Il est discret en affaires;","ipa":"/il ɛ diskʁɛ ɑ̃n afɛʁ/","zh":"他做事谨慎；","en":"He is discreet in business;","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-20-003","lineIndex":3,"speaker":"","original":"Le vieux renard sort jamais","ipa":"/lə vjø ʁənaʁ sɔʁ ʒamɛ/","zh":"老狐狸始终不出来","en":"The old fox never comes out","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-20-004","lineIndex":4,"speaker":"","original":"Depuis qu'il a revu Javert.","ipa":"/dəpɥi kil a ʁəvy ʒavɛʁ/","zh":"自从他又见过沙威之后。","en":"Since he saw Javert again.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-20-005","lineIndex":5,"speaker":"","original":"Je flaire la galette.","ipa":"/ʒə flɛʁ la ɡalɛt/","zh":"我闻到钱味了。","en":"I smell money.","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-20-006","lineIndex":6,"speaker":"","original":"Y a de ça dix berges","ipa":"/i a də sa di bɛʁʒ/","zh":"十年前","en":"Ten years ago","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-20-007","lineIndex":7,"speaker":"","original":"Y nous a raflé Cosette","ipa":"/i nuz a ʁafle kozɛt/","zh":"他把珂赛特从我们身边抢走了","en":"Cosette was snatched away from us","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-20-008","lineIndex":8,"speaker":"","original":"Pour quelques thunes, pour des miettes.","ipa":"/puʁ kɛlkə tyn puʁ de mjɛt/","zh":"为了几块钱，为了些残羹冷炙。","en":"For a few bucks, for crumbs.","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-20-009","lineIndex":9,"speaker":"","original":"Cette fois, je viens refaire cueillette Mais pas pour des prunes!","ipa":"/sɛt fwa ʒə vjɛ̃ ʁəfɛʁ kœjɛt mɛ pa puʁ de pʁyn/","zh":"这回我来收回旧账可不是为了这点小钱！","en":"This time, I have come to collect again but not for peanuts!","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-20-011","lineIndex":10,"speaker":"","original":"Nous on s'en cogne","ipa":"/nuz ɔ̃ sɑ̃ kɔɲ/","zh":"我们才不管","en":"We don't give a damn","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-20-012","lineIndex":11,"speaker":"","original":"De tes combines;","ipa":"/də te kɔ̃bin/","zh":"你的计划；","en":"Of your schemes;","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-20-013","lineIndex":12,"speaker":"","original":"Je veux ma part Et je me débine.","ipa":"/ʒə vø ma paʁ e ʒə mə debin/","zh":"我想要我的份额然后我就走人。","en":"I want my share and then I'm gone.","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-20-015","lineIndex":13,"speaker":"","original":"Ben, ferme ta poire","ipa":"/bɛn fɛʁm ta pwaʁ/","zh":"好吧，闭嘴","en":"Well, shut up","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-20-016","lineIndex":14,"speaker":"","original":"File-moi ta pogne.","ipa":"/filmwa ta pɔɲ/","zh":"把手给我。","en":"Give me your hand.","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-20-017","lineIndex":15,"speaker":"","original":"Qu'est-ce que c'est que ça?","ipa":"/kɛskə sɛ kə sa/","zh":"这是什么？","en":"What is this?","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-20-018","lineIndex":16,"speaker":"","original":"Qui est cette drôlesse?","ipa":"/ki ɛ sɛt dʁolɛs/","zh":"这小妞是谁？","en":"Who's this girl?","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-20-019","lineIndex":17,"speaker":"","original":"C'est ta fille Éponine;","ipa":"/sɛ ta fij eponin/","zh":"这是你的女儿艾潘妮；","en":"It’s your daughter Éponine;","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-20-020","lineIndex":18,"speaker":"","original":"Tu reconnais pas ta gosse","ipa":"/ty ʁəkɔnɛ pa ta ɡɔs/","zh":"你连自己的闺女都不认识了？","en":"You don't recognize your kid","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-20-021","lineIndex":19,"speaker":"","original":"Qui traîne ses fesses après toi.","ipa":"/ki tʁɛn se fɛsz apʁɛ twa/","zh":"还跟在你屁股后头转。","en":"who's always trailing after you.","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-20-022","lineIndex":20,"speaker":"","original":"Éponine, rentre chez nous;","ipa":"/eponin ʁɑ̃tʁ ʃe nu/","zh":"艾潘妮，回家吧；","en":"Éponine, come home;","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-20-023","lineIndex":21,"speaker":"","original":"Y'a pas besoin d'une greluche Faut que des gars pour ce turbin là.","ipa":"/ja pa bəzwɛ̃ dyn ɡʁəlyʃ fo kə de ɡa puʁ sə tyʁbɛ̃ la/","zh":"这活儿用不着带个姑娘碍事干这活儿只要男人。","en":"We don't need a girl getting in the way this job is for men.","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-20-025","lineIndex":22,"speaker":"","original":"Je connais cette taule.","ipa":"/ʒə kɔnɛ sɛt tol/","zh":"我熟悉这栋房子。","en":"I know this place.","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-20-026","lineIndex":23,"speaker":"","original":"Ici, y'a pas d'affure pour vous","ipa":"/isi ja pa dafyʁ puʁ vu/","zh":"这儿对你们没什么油水","en":"There's nothing here in it for you","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-20-027","lineIndex":24,"speaker":"","original":"Juste le vieux schnock et la môme Pas d'oseille et pas de cailloux.","ipa":"/ʒyst lə vjø ʃnɔk e la moːm pa dozɛj e pa də kaju/","zh":"只有老头子和孩子没钱，也没值钱货。","en":"Just the old geezer and the kid no cash and no valuables.","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-20-029","lineIndex":25,"speaker":"","original":"De quoi je me mêle?","ipa":"/də kwa ʒə mə mɛl/","zh":"关你什么事？","en":"What am I getting involved in?","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-20-030","lineIndex":26,"speaker":"","original":"De quoi tu causes?","ipa":"/də kwa ty koz/","zh":"你在说什么？","en":"What are you talking about?","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-20-031","lineIndex":27,"speaker":"","original":"Détale fillette Ou je t'allonge une torgnole!","ipa":"/detal fijɛt u ʒə talɔ̃ʒ yn tɔʁnjɔl/","zh":"快滚，小丫头不然赏你一耳光！","en":"Get lost, little girl or I'll give you a slap!","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-20-033","lineIndex":28,"speaker":"","original":"Elle flanche, la caille!","ipa":"/ɛl flɑ̃ʃ la kaj/","zh":"她怕了，这小妞！","en":"She's cracking, the little bird!","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-20-034","lineIndex":29,"speaker":"","original":"Sont toutes les mêmes!","ipa":"/sɔ̃ tut le mɛm/","zh":"都是一样的！","en":"Are all the same!","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-20-035","lineIndex":30,"speaker":"","original":"Dégage Ponine","ipa":"/deɡaʒ ponin/","zh":"滚开，波妮。","en":"Get out, Ponine.","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-20-036","lineIndex":31,"speaker":"","original":"Ou je te mets le blair de traviole!","ipa":"/u ʒə tə mɛ lə blɛʁ də tʁavjɔl/","zh":"不然我把你鼻子揍歪！","en":"Or I'll smash your nose crooked!","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-20-037","lineIndex":32,"speaker":"","original":"Je vais crier","ipa":"/ʒə vɛ kʁie/","zh":"我要尖叫","en":"I'm going to scream","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-20-038","lineIndex":33,"speaker":"","original":"Je vais les prévenir, je vous jure!","ipa":"/ʒə vɛ le pʁevniʁ ʒə vu ʒyʁ/","zh":"我会警告他们，我发誓！","en":"I will warn them, I swear!","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-20-039","lineIndex":34,"speaker":"","original":"Un petit cri, Ponine et tu vas t'en souvenir.","ipa":"/œ̃ pəti kʁi ponin e ty va tɑ̃ suvniʁ/","zh":"你敢喊一声，波妮，我就让你记一辈子。","en":"One little cry, Ponine, and you'll remember it.","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-20-040","lineIndex":35,"speaker":"","original":"Je me régale.","ipa":"/ʒə mə ʁeɡal/","zh":"我很享受。","en":"I'm enjoying it.","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-20-041","lineIndex":36,"speaker":"","original":"Ah! Quel délice quand on bosse","ipa":"/a kɛl delis kɑ̃t ɔ̃ bɔs/","zh":"啊，干活时看见这一幕，真痛快","en":"Ah! What a delight when you work","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-20-042","lineIndex":37,"speaker":"","original":"De voir une chienne et son dabe","ipa":"/də vwaʁ yn ʃjɛn e sɔ̃ dab/","zh":"看一条“母狗”和她的男人","en":"to see a bitch and her man","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-20-043","lineIndex":38,"speaker":"","original":"Se disputer le même os.","ipa":"/sə dispyte lə mɛm ɔs/","zh":"为同一块骨头而战。","en":"Fighting over the same bone.","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-20-044","lineIndex":39,"speaker":"","original":"L'ouvre pas ou je tabasse!","ipa":"/luvʁ pa u ʒə tabas/","zh":"闭嘴，不然我揍你！","en":"Don't open your mouth or I'll beat you!","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-20-045","lineIndex":40,"speaker":"","original":"J'ai dit que je vais crier;","ipa":"/ʒe di kə ʒə vɛ kʁie/","zh":"我说我要尖叫；","en":"I said I'm going to scream;","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-20-046","lineIndex":41,"speaker":"","original":"Pour sûr, je vais crier. Aaaaaaah!","ipa":"/puʁ syʁ ʒə vɛ kʁie aaaaaaa/","zh":"我当然要喊。啊—！","en":"For sure, I will scream. Aaaaaaah!","note":"","sourceLineIndex":46},{"id":"les-miserables-cityprod-2017-20-047","lineIndex":42,"speaker":"","original":"Attends ma fille, attends que je te coince!","ipa":"/atɑ̃ ma fij atɑ̃ kə ʒə tə kwɛ̃s/","zh":"等着，小妞，等我逮住你！","en":"Wait, girl, wait till I corner you!","note":"","sourceLineIndex":47},{"id":"les-miserables-cityprod-2017-20-048","lineIndex":43,"speaker":"","original":"Tu vas brailler, jusqu'à que ça grince.","ipa":"/ty va bʁaje ʒyska kə sa ɡʁɛ̃s/","zh":"你会嚎到嗓子都哑！","en":"You'll howl till it squeaks!","note":"","sourceLineIndex":48},{"id":"les-miserables-cityprod-2017-20-049","lineIndex":44,"speaker":"","original":"Vite, on s'enterre! Vite grouillez-vous!","ipa":"/vit ɔ̃ sɑ̃tɛʁ vit ɡʁujevu/","zh":"快，躲起来！快动起来！","en":"Quick, let's hide! Move it!","note":"","sourceLineIndex":49},{"id":"les-miserables-cityprod-2017-20-050","lineIndex":45,"speaker":"","original":"Laissez-la moi; tous aux égouts!","ipa":"/lɛsela mwa tus oz eɡu/","zh":"把她留给我；其他人都钻下水道！","en":"Leave her to me; everyone else, into the sewers!","note":"","sourceLineIndex":50},{"id":"les-miserables-cityprod-2017-20-051","lineIndex":46,"speaker":"","original":"Merci Ponine, ils ont eu peur!","ipa":"/mɛʁsi ponin ilz ɔ̃t y pœʁ/","zh":"谢谢波妮，他们很害怕！","en":"Thanks Ponine, they were scared!","note":"","sourceLineIndex":51},{"id":"les-miserables-cityprod-2017-20-052","lineIndex":47,"speaker":"","original":"Tu m'as sauvé! Une fois de plus.","ipa":"/ty ma sove yn fwa də ply/","zh":"你又救了我一次！","en":"You saved me! Once again.","note":"","sourceLineIndex":52},{"id":"les-miserables-cityprod-2017-20-053","lineIndex":48,"speaker":"","original":"Ma chère Cosette, c'est Éponine L'amie fidèle qui t'a trouvée.","ipa":"/ma ʃɛʁ kozɛt sɛt eponin lami fidɛl ki ta tʁuve/","zh":"亲爱的珂赛特，是我，艾潘妮那个找到你的忠实朋友。","en":"My dear Cosette, it's Éponine the faithful friend who found you.","note":"","sourceLineIndex":53},{"id":"les-miserables-cityprod-2017-20-055","lineIndex":49,"speaker":"","original":"Quelqu'un arrive, je disparais","ipa":"/kɛlkœ̃ aʁiv ʒə dispaʁɛ/","zh":"有人来我就消失","en":"Someone comes, I disappear","note":"","sourceLineIndex":55},{"id":"les-miserables-cityprod-2017-20-056","lineIndex":50,"speaker":"","original":"Quelqu'un arrive!","ipa":"/kɛlkœ̃ aʁiv/","zh":"有人来了！","en":"Someone is coming!","note":"","sourceLineIndex":56}],"sourceOrder":20,"displayOrder":19},{"order":21,"id":"21-le-grand-jour","title":"Le grand jour","titleZh":"重要的一天","lines":[{"id":"les-miserables-cityprod-2017-21-001","lineIndex":1,"speaker":"","original":"Le grand jour","ipa":"/lə ɡʁɑ̃ ʒuʁ/","zh":"这个大日子","en":"The big day","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-21-002","lineIndex":2,"speaker":"","original":"Une autre vie, une autre destinée","ipa":"/yn otʁ vi yn otʁ dɛstine/","zh":"另一种生活，另一种命运","en":"Another life, another destiny","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-21-003","lineIndex":3,"speaker":"","original":"Délivrés d'avoir à fuir à perpétuité.","ipa":"/delivʁe davwaʁ a fyiʁ a pɛʁpetɥite/","zh":"免于终生逃亡。","en":"Freed from having to flee for life.","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-21-004","lineIndex":4,"speaker":"","original":"Mais au jour du jugement ultime","ipa":"/mɛz o ʒuʁ dy ʒyʒmɑ̃ yltim/","zh":"但在最后审判的那一天","en":"But on the day of final judgment","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-21-005","lineIndex":5,"speaker":"","original":"Chaque homme doit révéler ses crimes","ipa":"/ʃak ɔm dwa ʁevele se kʁim/","zh":"每个人都必须揭露自己的罪行","en":"Every man must reveal his crimes","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-21-006","lineIndex":6,"speaker":"","original":"Au grand jour.","ipa":"/o ɡʁɑ̃ ʒuʁ/","zh":"光天化日之下。","en":"In broad daylight.","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-21-007","lineIndex":7,"speaker":"","original":"Demain, je ne la verrai plus","ipa":"/dəmɛ̃ ʒə nə la vɛʁe ply/","zh":"明天我就见不到她了","en":"Tomorrow I won't see her anymore","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-21-008","lineIndex":8,"speaker":"","original":"Mon sang se glace dans mes veines.","ipa":"/mɔ̃ sɑ̃ sə ɡlas dɑ̃ me vɛn/","zh":"我的血液仿佛在血管中凝固。","en":"My blood freezes in my veins.","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-21-009","lineIndex":9,"speaker":"","original":"Le grand jour","ipa":"/lə ɡʁɑ̃ ʒuʁ/","zh":"这个大日子","en":"The big day","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-21-010","lineIndex":10,"speaker":"","original":"Demain je ne te verrai plus","ipa":"/dəmɛ̃ ʒə nə tə vɛʁe ply/","zh":"明天我就见不到你了","en":"Tomorrow I won't see you anymore","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-21-011","lineIndex":11,"speaker":"","original":"C'est comme la foudre que l'on m'assène.","ipa":"/sɛ kɔm la fudʁ kə lɔ̃ masɛn/","zh":"就像闪电击中我一样。","en":"It's like lightning being struck at me.","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-21-012","lineIndex":12,"speaker":"","original":"Demain seule dans mon histoire","ipa":"/dəmɛ̃ sœl dɑ̃ mɔ̃n istwaʁ/","zh":"明天，我将独自留在自己的故事里","en":"Tomorrow alone in my story","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-21-013","lineIndex":13,"speaker":"","original":"Vais-je te perdre à tout jamais?","ipa":"/vɛʒ tə pɛʁdʁ a tu ʒamɛ/","zh":"我会永远失去你吗？","en":"Will I lose you forever?","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-21-014","lineIndex":14,"speaker":"","original":"Un grand jour perdu sans le voir.","ipa":"/œ̃ ɡʁɑ̃ ʒuʁ pɛʁdy sɑ̃ lə vwaʁ/","zh":"若见不到他，这个大日子也将失去意义。","en":"A great day wasted without seeing him.","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-21-015","lineIndex":15,"speaker":"","original":"Quand ma vie commence à peine.","ipa":"/kɑ̃ ma vi kɔmɑ̃s a pɛn/","zh":"当我的人生刚刚开始的时候。","en":"When my life is just beginning.","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-21-016","lineIndex":16,"speaker":"","original":"Un peu plus seule chaque soir","ipa":"/œ̃ pø ply sœl ʃak swaʁ/","zh":"每个夜晚都更孤独一些","en":"A little more alone every evening","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-21-017","lineIndex":17,"speaker":"","original":"Et je jure d'être fidèle.","ipa":"/e ʒə ʒyʁ dɛtʁ fidɛl/","zh":"我发誓要忠诚。","en":"And I swear to be faithful.","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-21-018","lineIndex":18,"speaker":"","original":"Je l'évoque dans ma mémoire.","ipa":"/ʒə levok dɑ̃ ma memwaʁ/","zh":"我只能在记忆里唤回他的身影。","en":"I recall it in my memory.","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-21-019","lineIndex":19,"speaker":"","original":"Le grand jour est pour demain","ipa":"/lə ɡʁɑ̃ ʒuʁ ɛ puʁ dəmɛ̃/","zh":"明天就是大日子了","en":"The big day is tomorrow","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-21-020","lineIndex":20,"speaker":"","original":"Dois-je aller là où elle va?","ipa":"/dwaʒ ale la u ɛl va/","zh":"我应该去她去的地方吗？","en":"Should I go where she goes?","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-21-021","lineIndex":21,"speaker":"","original":"Demain sur la barricade.","ipa":"/dəmɛ̃ syʁ la baʁikad/","zh":"明天去街垒。","en":"Tomorrow on the barricade.","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-21-022","lineIndex":22,"speaker":"","original":"Ou suivre mes frères au combat?","ipa":"/u sɥivʁ me fʁɛʁz o kɔ̃ba/","zh":"还是跟随我的兄弟一起战斗？","en":"Or follow my brothers into battle?","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-21-023","lineIndex":23,"speaker":"","original":"Le grand jour se lève enfin","ipa":"/lə ɡʁɑ̃ ʒuʁ sə lɛv ɑ̃fɛ̃/","zh":"大日子终于破晓","en":"The big day finally dawns","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-21-024","lineIndex":24,"speaker":"","original":"Comment faire? Ai-je bien le droit?","ipa":"/kɔmɑ̃ fɛʁ ɛʒ bjɛ̃ lə dʁwa/","zh":"怎么做呢？我有权利吗？","en":"How to do it? Do I have the right?","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-21-025","lineIndex":25,"speaker":"","original":"Et les droits de l'homme s'écrivent.","ipa":"/e le dʁwa də lɔm sekʁiv/","zh":"人权的篇章正在写下。","en":"And human rights are being written.","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-21-026","lineIndex":26,"speaker":"","original":"Amis, c'est l'heure, Demain arrive.","ipa":"/ami sɛ lœʁ dəmɛ̃ aʁiv/","zh":"朋友们，是时候了，明天即将到来。","en":"Friends, it's time, Tomorrow is coming.","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-21-027","lineIndex":27,"speaker":"","original":"Le grand jour.","ipa":"/lə ɡʁɑ̃ ʒuʁ/","zh":"大日子。","en":"The big day.","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-21-028","lineIndex":28,"speaker":"","original":"Leur émeute en culottes courtes","ipa":"/lœʁ emøt ɑ̃ kylɔt kuʁt/","zh":"这群乳臭未干的暴徒闹事","en":"Their childish little riot","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-21-029","lineIndex":29,"speaker":"","original":"Je la suivrai dans leurs rangs;","ipa":"/ʒə la sɥivʁe dɑ̃ lœʁ ʁɑ̃/","zh":"我会混进他们的行列","en":"I will follow it into their ranks;","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-21-030","lineIndex":30,"speaker":"","original":"Je les pousserai sans qu'ils s'en doutent À s'éclabousser de leur sang.","ipa":"/ʒə le pusʁe sɑ̃ kil sɑ̃ dutt a seklabuse də lœʁ sɑ̃/","zh":"在他们毫不知情时推着他们让他们溅自己一身血。","en":"I will push them on without their knowing until they are splashed with their own blood.","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-21-032","lineIndex":31,"speaker":"","original":"Le grand jour","ipa":"/lə ɡʁɑ̃ ʒuʁ/","zh":"这个大日子","en":"The big day","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-21-033","lineIndex":32,"speaker":"","original":"Y vont au casse-pipe, on attend que ça fume;","ipa":"/i vɔ̃t o kaspip ɔ̃n atɑ̃ kə sa fym/","zh":"他们去送死，我们等着那边打起来；","en":"They are going to the slaughter; we wait for the smoke to rise.","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-21-034","lineIndex":33,"speaker":"","original":"Quand y z'ont du plomb dans l'aile, nous on les plume:","ipa":"/kɑ̃t i zɔ̃ dy plɔ̃ dɑ̃ lɛl nuz ɔ̃ le plym/","zh":"等他们中弹折翼，我们就把他们搜刮干净：","en":"When they have lead in their wings, we pluck them clean:","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-21-035","lineIndex":34,"speaker":"","original":"Un bijou ici, un petit sou en face.","ipa":"/œ̃ biʒu isi œ̃ pəti su ɑ̃ fas/","zh":"这里一件首饰，那里几枚小钱。","en":"A gem here, a little penny opposite.","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-21-036","lineIndex":35,"speaker":"","original":"Y a plus qu'à attendre l'ouverture de la chasse.","ipa":"/i a ply ka atɑ̃dʁ luvɛʁtyʁ də la ʃas/","zh":"我们所要做的就是等待狩猎开始。","en":"All we have to do is wait for the hunt to open.","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-21-037","lineIndex":36,"speaker":"","original":"Le grand jour patriotique","ipa":"/lə ɡʁɑ̃ ʒuʁ patʁiotik/","zh":"伟大的爱国日","en":"The great patriotic day","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-21-038","lineIndex":37,"speaker":"","original":"Le progrès reprend sa marche;","ipa":"/lə pʁɔɡʁɛ ʁəpʁɑ̃ sa maʁʃ/","zh":"进步继续前进；","en":"Progress resumes its march;","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-21-039","lineIndex":38,"speaker":"","original":"Combattant de l'avenir","ipa":"/kɔ̃batɑ̃ də lavniʁ/","zh":"未来的战士","en":"Fighter of the future","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-21-040","lineIndex":39,"speaker":"","original":"Resurgi de son linceul","ipa":"/ʁəzyʁʒi də sɔ̃ lɛ̃sœl/","zh":"从他的裹尸布中复活","en":"Resurrected from his shroud","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-21-041","lineIndex":40,"speaker":"","original":"Par l'espérance magnifique","ipa":"/paʁ lɛspeʁɑ̃s maɲifik/","zh":"因着伟大的希望","en":"By magnificent hope","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-21-042","lineIndex":41,"speaker":"","original":"D'un nouveau monde à construire.","ipa":"/dœ̃ nuvo mɔ̃d a kɔ̃stʁyiʁ/","zh":"一个新的世界等待建立。","en":"A new world to build.","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-21-043","lineIndex":42,"speaker":"","original":"À la volonté du peuple.","ipa":"/a la volɔ̃te dy pøpl/","zh":"为了人民的意志。","en":"To the will of the people.","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-21-044","lineIndex":43,"speaker":"","original":"Ma place est là, auprès de toi.","ipa":"/ma plas ɛ la opʁɛ də twa/","zh":"我的位置就在这里，和你在一起。","en":"My place is here, with you.","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-21-045","lineIndex":44,"speaker":"","original":"Le grand jour.","ipa":"/lə ɡʁɑ̃ ʒuʁ/","zh":"大日子。","en":"The big day.","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-21-046","lineIndex":45,"speaker":"","original":"Demain je ne te verrai plus","ipa":"/dəmɛ̃ ʒə nə tə vɛʁe ply/","zh":"明天我就见不到你了","en":"Tomorrow I won't see you anymore","note":"","sourceLineIndex":46},{"id":"les-miserables-cityprod-2017-21-047","lineIndex":46,"speaker":"","original":"Demain seule dans mon histoire","ipa":"/dəmɛ̃ sœl dɑ̃ mɔ̃n istwaʁ/","zh":"明天，我将独自留在自己的故事里","en":"Tomorrow alone in my story","note":"","sourceLineIndex":47},{"id":"les-miserables-cityprod-2017-21-048","lineIndex":47,"speaker":"","original":"Mon sang se glace dans mes veines.","ipa":"/mɔ̃ sɑ̃ sə ɡlas dɑ̃ me vɛn/","zh":"我的血液仿佛在血管中凝固。","en":"My blood freezes in my veins.","note":"","sourceLineIndex":48},{"id":"les-miserables-cityprod-2017-21-049","lineIndex":48,"speaker":"","original":"Avec les héros du peuple","ipa":"/avɛk le eʁo dy pøpl/","zh":"与人民英雄一起","en":"With the heroes of the people","note":"","sourceLineIndex":49},{"id":"les-miserables-cityprod-2017-21-050","lineIndex":49,"speaker":"","original":"Avec ces nouveaux stratèges;","ipa":"/avɛk se nuvo stʁatɛʒ/","zh":"跟着这些新来的军师","en":"With these new strategists;","note":"","sourceLineIndex":50},{"id":"les-miserables-cityprod-2017-21-051","lineIndex":50,"speaker":"","original":"Instruit de leurs petits secrets","ipa":"/ɛ̃stʁyi də lœʁ pəti səkʁɛ/","zh":"了解了他们的小秘密","en":"Learned about their little secrets","note":"","sourceLineIndex":51},{"id":"les-miserables-cityprod-2017-21-052","lineIndex":51,"speaker":"","original":"Je refermerai le piège.","ipa":"/ʒə ʁəfɛʁməʁe lə pjɛʒ/","zh":"我会重新收紧陷阱。","en":"I will close the trap.","note":"","sourceLineIndex":52},{"id":"les-miserables-cityprod-2017-21-053","lineIndex":52,"speaker":"","original":"Y vont au casse-pipe, on attend que ça fume;","ipa":"/i vɔ̃t o kaspip ɔ̃n atɑ̃ kə sa fym/","zh":"他们正往送命处去，我们等着战火冒起；","en":"They go to the pipebreaker, we wait for it to smoke;","note":"","sourceLineIndex":53},{"id":"les-miserables-cityprod-2017-21-054","lineIndex":53,"speaker":"","original":"Après qu'y s'étripent on leur ôte les plumes.","ipa":"/apʁɛ ki setʁipt ɔ̃ lœʁ ot le plym/","zh":"等他们自相残杀完，我们就去搜刮。","en":"After they gut each other, we pluck them.","note":"","sourceLineIndex":54},{"id":"les-miserables-cityprod-2017-21-055","lineIndex":54,"speaker":"","original":"Le grand jour","ipa":"/lə ɡʁɑ̃ ʒuʁ/","zh":"大日子","en":"The big day","note":"","sourceLineIndex":55},{"id":"les-miserables-cityprod-2017-21-056","lineIndex":55,"speaker":"","original":"Demain je ne te verrai plus","ipa":"/dəmɛ̃ ʒə nə tə vɛʁe ply/","zh":"明天我就见不到你了","en":"Tomorrow I won't see you anymore","note":"","sourceLineIndex":56},{"id":"les-miserables-cityprod-2017-21-057","lineIndex":56,"speaker":"","original":"Demain tout seule dans le noir.","ipa":"/dəmɛ̃ tu sœl dɑ̃ lə nwaʁ/","zh":"明天，独自一人在黑暗中。","en":"Tomorrow all alone in the dark.","note":"","sourceLineIndex":57},{"id":"les-miserables-cityprod-2017-21-058","lineIndex":57,"speaker":"","original":"C'est comme la foudre que l'on m'assène.","ipa":"/sɛ kɔm la fudʁ kə lɔ̃ masɛn/","zh":"就像闪电击中我一样。","en":"It's like lightning being struck at me.","note":"","sourceLineIndex":58},{"id":"les-miserables-cityprod-2017-21-059","lineIndex":58,"speaker":"","original":"Leur émeute en culottes courtes","ipa":"/lœʁ emøt ɑ̃ kylɔt kuʁt/","zh":"那帮乳臭未干的暴徒闹事","en":"Their riot in short pants","note":"","sourceLineIndex":59},{"id":"les-miserables-cityprod-2017-21-060","lineIndex":59,"speaker":"","original":"Je la suivrai dans leurs rangs;","ipa":"/ʒə la sɥivʁe dɑ̃ lœʁ ʁɑ̃/","zh":"我会混进他们的行列；","en":"I will follow her into their ranks;","note":"","sourceLineIndex":60},{"id":"les-miserables-cityprod-2017-21-061","lineIndex":60,"speaker":"","original":"Je les tousserai sans qu'ils s'en doutent...","ipa":"/ʒə le tusʁe sɑ̃ kil sɑ̃ dut/","zh":"我会暗中把他们推向死地……","en":"I'll push them without them knowing it...","note":"","sourceLineIndex":61},{"id":"les-miserables-cityprod-2017-21-062","lineIndex":61,"speaker":"","original":"Demain c'est le jugement dernier.","ipa":"/dəmɛ̃ sɛ lə ʒyʒmɑ̃ dɛʁnje/","zh":"明天就是最后的审判了。","en":"Tomorrow is the last judgment.","note":"","sourceLineIndex":62},{"id":"les-miserables-cityprod-2017-21-063","lineIndex":62,"speaker":"","original":"Y vont au casse-pipe, on attend que ça fume;","ipa":"/i vɔ̃t o kaspip ɔ̃n atɑ̃ kə sa fym/","zh":"他们正往送命处去，我们等着战火冒起；","en":"They go to the pipebreaker, we wait for it to smoke;","note":"","sourceLineIndex":63},{"id":"les-miserables-cityprod-2017-21-064","lineIndex":63,"speaker":"","original":"Quand y z'ont du plomb dans l'aile, nous on les plume.","ipa":"/kɑ̃t i zɔ̃ dy plɔ̃ dɑ̃ lɛl nuz ɔ̃ le plym/","zh":"等他们中弹折翼，我们就把他们搜刮干净。","en":"When there is lead in the wing, we pluck them.","note":"","sourceLineIndex":64},{"id":"les-miserables-cityprod-2017-21-065","lineIndex":64,"speaker":"","original":"Demain, nous partons sans regret;","ipa":"/dəmɛ̃ nu paʁtɔ̃ sɑ̃ ʁəɡʁɛ/","zh":"明天我们无怨无悔地离开；","en":"Tomorrow we leave without regret;","note":"","sourceLineIndex":65},{"id":"les-miserables-cityprod-2017-21-066","lineIndex":65,"speaker":"","original":"Demain c'est le jugement dernier.","ipa":"/dəmɛ̃ sɛ lə ʒyʒmɑ̃ dɛʁnje/","zh":"明天就是最后的审判了。","en":"Tomorrow is the last judgment.","note":"","sourceLineIndex":66},{"id":"les-miserables-cityprod-2017-21-067","lineIndex":66,"speaker":"","original":"Demain, nous saurons si Dieu vient","ipa":"/dəmɛ̃ nu soʁɔ̃ si djø vjɛ̃/","zh":"明天我们就会知道上帝是否会来","en":"Tomorrow we will know if God is coming","note":"","sourceLineIndex":67},{"id":"les-miserables-cityprod-2017-21-068","lineIndex":67,"speaker":"","original":"Annoncer enfin son retour.","ipa":"/anɔ̃se ɑ̃fɛ̃ sɔ̃ ʁətuʁ/","zh":"终于宣布回归。","en":"Finally announce his return.","note":"","sourceLineIndex":68},{"id":"les-miserables-cityprod-2017-21-069","lineIndex":68,"speaker":"","original":"C'est enfin","ipa":"/sɛt ɑ̃fɛ̃/","zh":"终于","en":"It is finally","note":"","sourceLineIndex":69},{"id":"les-miserables-cityprod-2017-21-070","lineIndex":69,"speaker":"","original":"C'est demain le grand jour!","ipa":"/sɛ dəmɛ̃ lə ɡʁɑ̃ ʒuʁ/","zh":"明天是个大日子！","en":"Tomorrow is the big day!","note":"","sourceLineIndex":70}],"sourceOrder":21,"displayOrder":20},{"order":22,"id":"22-la-premiere-barricade","title":"La première barricade","titleZh":"第一道街垒","lines":[{"id":"les-miserables-cityprod-2017-22-001","lineIndex":1,"speaker":"","original":"Dans cette rue, sur ces pierres montons notre barricade","ipa":"/dɑ̃ sɛt ʁy syʁ se pjɛʁ mɔ̃tɔ̃ notʁ baʁikad/","zh":"在这条街上，在这些石头上，让我们建造我们的路障","en":"In this street, on these stones let's build our barricade","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-22-002","lineIndex":2,"speaker":"","original":"Sur les flancs du café qui vit nos algarades","ipa":"/syʁ le flɑ̃ dy kafe ki vi noz alɡaʁad/","zh":"在那间见证过我们争执的咖啡馆两侧","en":"Alongside the café that saw our quarrels","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-22-003","lineIndex":3,"speaker":"","original":"Le cœur à l'ouvrage et chaque homme à sa place","ipa":"/lə kœʁ a luvʁaʒ e ʃak ɔm a sa plas/","zh":"齐心干活，各人各就各位。","en":"Put your heart into it, every man in his place.","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-22-004","lineIndex":4,"speaker":"","original":"Attendez j'ai besoin d'un rapport sur les forces d'en face","ipa":"/atɑ̃de ʒe bəzwɛ̃ dœ̃ ʁapɔʁ syʁ le fɔʁs dɑ̃ fas/","zh":"等等，我需要一份敌方兵力报告。","en":"Wait, I need a report on the opposing forces.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-22-005","lineIndex":5,"speaker":"","original":"Confiez-moi cette mission je les connais","ipa":"/kɔ̃fjemwa sɛt misjɔ̃ ʒə le kɔnɛ/","zh":"把这个使命交给我，我认识他们","en":"Entrust me with this mission, I know them","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-22-006","lineIndex":6,"speaker":"","original":"J'étais soldat dans leurs rangs","ipa":"/ʒetɛ sɔlda dɑ̃ lœʁ ʁɑ̃/","zh":"我是他们队伍中的一名士兵","en":"I was a soldier in their ranks","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-22-007","lineIndex":7,"speaker":"","original":"Bon soldat, en mon temps","ipa":"/bɔ̃ sɔlda ɑ̃ mɔ̃ tɑ̃/","zh":"在我那个时代，好战士","en":"Good soldier, in my time","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-22-008","lineIndex":8,"speaker":"","original":"La rue prend le pouvoir","ipa":"/la ʁy pʁɑ̃ lə puvwaʁ/","zh":"街道夺取权力","en":"The street takes power","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-22-009","lineIndex":9,"speaker":"","original":"Copains, je bois","ipa":"/kopɛ̃ ʒə bwa/","zh":"伙计们，我喝一杯。","en":"Friends, I'm drinking.","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-22-010","lineIndex":10,"speaker":"","original":"Tant qu'y a du vin","ipa":"/tɑ̃ ki a dy vɛ̃/","zh":"只要有酒","en":"As long as there is wine","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-22-011","lineIndex":11,"speaker":"","original":"Y a de l'espoir!","ipa":"/i a də lɛspwaʁ/","zh":"有希望！","en":"There is hope!","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-22-012","lineIndex":12,"speaker":"","original":"Ils feront leur devoir!","ipa":"/il fəʁɔ̃ lœʁ dəvwaʁ/","zh":"他们会尽自己的职责！","en":"They will do their duty!","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-22-013","lineIndex":13,"speaker":"","original":"Hé! Là! Petit, que fais-tu là?","ipa":"/e la pəti kə fɛty la/","zh":"嘿！那里！小家伙，你在这里做什么？","en":"Hey! There! Little one, what are you doing here?","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-22-014","lineIndex":14,"speaker":"","original":"Non! Éponine, à quoi tu joues?","ipa":"/nɔ̃ eponin a kwa ty ʒw/","zh":"不！艾潘妮，你在玩什么？","en":"No! Éponine, what are you playing?","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-22-015","lineIndex":15,"speaker":"","original":"Soyez pas fâché contre moi!","ipa":"/swaje pa faʃe kɔ̃tʁ mwa/","zh":"别生我的气！","en":"Don't be mad at me!","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-22-016","lineIndex":16,"speaker":"","original":"Je voulais être plus près de vous","ipa":"/ʒə vulɛz ɛtʁ ply pʁɛ də vu/","zh":"我想离你更近一些","en":"I wanted to be closer to you","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-22-017","lineIndex":17,"speaker":"","original":"Va-t'en Ponine, je suis sérieux","ipa":"/vatɑ̃ ponin ʒə sɥi seʁjø/","zh":"走开，波妮，我是认真的","en":"Go away Ponine, I'm serious","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-22-018","lineIndex":18,"speaker":"","original":"Avant que la meute se déchaîne","ipa":"/avɑ̃ kə la møt sə deʃɛn/","zh":"在狼群疯狂之前","en":"Before the pack goes wild","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-22-019","lineIndex":19,"speaker":"","original":"Si vous êtes si inquiet pour moi C'est que je compte un peu quand même","ipa":"/si vuz ɛt si ɛ̃kjɛ puʁ mwa sɛ kə ʒə kɔ̃t œ̃ pø kɑ̃ mɛm/","zh":"如果您这么担心我那说明我终究还算有一点分量。","en":"If you are so worried about me it means I still count for something.","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-22-021","lineIndex":20,"speaker":"","original":"Si je peux toujours compter sur toi","ipa":"/si ʒə pø tuʒuʁ kɔ̃te syʁ twa/","zh":"如果我能永远依靠你","en":"If I can always count on you","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-22-022","lineIndex":21,"speaker":"","original":"Si tu veux bien m'aider encore","ipa":"/si ty vø bjɛ̃ mɛde ɑ̃kɔʁ/","zh":"如果你想再次帮助我","en":"If you would like to help me again","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-22-023","lineIndex":22,"speaker":"","original":"Cours porter cette lettre à Cosette","ipa":"/kuʁ pɔʁte sɛt lɛtʁ a kozɛt/","zh":"跑去把这封信交给珂赛特","en":"Run and take this letter to Cosette","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-22-024","lineIndex":23,"speaker":"","original":"Et prie pour qu'elle soit encore là","ipa":"/e pʁi puʁ kɛl swa ɑ̃kɔʁ la/","zh":"并祈祷她还在这里","en":"And pray she's still here","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-22-025","lineIndex":24,"speaker":"","original":"Tu ne vois rien!","ipa":"/ty nə vwa ʁjɛ̃/","zh":"你什么也看不见！","en":"You don't see anything!","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-22-026","lineIndex":25,"speaker":"","original":"Tu n'entends pas!","ipa":"/ty nɑ̃tɑ̃ pa/","zh":"你没听见！","en":"You don't hear!","note":"","sourceLineIndex":26}],"sourceOrder":22,"displayOrder":21},{"order":23,"id":"23-mon-histoire","title":"Mon histoire","titleZh":"我的故事","lines":[{"id":"les-miserables-cityprod-2017-23-001","lineIndex":1,"speaker":"","original":"Je suis toute seule encore une fois","ipa":"/ʒə sɥi tut sœl ɑ̃kɔʁ yn fwa/","zh":"我又一次孤身一人。","en":"I'm all alone once again.","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-23-002","lineIndex":2,"speaker":"","original":"Sans un ami, sans rien à faire","ipa":"/sɑ̃z œ̃n ami sɑ̃ ʁjɛ̃n a fɛʁ/","zh":"没有朋友，无事可做","en":"Without a friend, without anything to do","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-23-003","lineIndex":3,"speaker":"","original":"Je suis pas pressée de retrouver","ipa":"/ʒə sɥi pa pʁɛse də ʁətʁuve/","zh":"我并不急于寻找","en":"I'm in no hurry to find","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-23-004","lineIndex":4,"speaker":"","original":"Ma solitude et ma misère","ipa":"/ma solityd e ma mizɛʁ/","zh":"我的孤独和我的痛苦","en":"My loneliness and my misery","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-23-005","lineIndex":5,"speaker":"","original":"J'attends que vienne le soir Pour l'évoquer dans ma mémoire","ipa":"/ʒatɑ̃ kə vjɛn lə swaʁ puʁ levoke dɑ̃ ma memwaʁ/","zh":"我等待傍晚的到来好在回忆里把他唤回。","en":"I wait for the evening to come to summon him back in my memory.","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-23-007","lineIndex":6,"speaker":"","original":"Je marche seule et chaque nuit","ipa":"/ʒə maʁʃ sœl e ʃak nɥi/","zh":"我独自行走每个夜晚","en":"I walk alone and every night","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-23-008","lineIndex":7,"speaker":"","original":"Les rues de la ville m'appartiennent","ipa":"/le ʁy də la vil mapaʁtjɛn/","zh":"城市的街道是我的","en":"The city streets belong to me","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-23-009","lineIndex":8,"speaker":"","original":"Toutes mes pensées s'envolent vers lui","ipa":"/tut me pɑ̃se sɑ̃vol vɛʁ lɥi/","zh":"我所有的思绪都飞向他","en":"All my thoughts fly to him","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-23-010","lineIndex":9,"speaker":"","original":"Et je mets ma vie dans la sienne","ipa":"/e ʒə mɛ ma vi dɑ̃ la sjɛn/","zh":"我把自己的生命交托给他的生命。","en":"And I place my life in his.","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-23-011","lineIndex":10,"speaker":"","original":"Paris dort; dans le noir","ipa":"/paʁi dɔʁ dɑ̃ lə nwaʁ/","zh":"巴黎正在睡觉；在黑暗中","en":"Paris is sleeping; in the dark","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-23-012","lineIndex":11,"speaker":"","original":"Je peux m'inventer mon histoire","ipa":"/ʒə pø mɛ̃vɑ̃te mɔ̃n istwaʁ/","zh":"我可以发明我的故事","en":"I can invent my story","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-23-013","lineIndex":12,"speaker":"","original":"Mon histoire","ipa":"/mɔ̃n istwaʁ/","zh":"我的故事","en":"My story","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-23-014","lineIndex":13,"speaker":"","original":"C'est un rêve qui commence","ipa":"/sɛt œ̃ ʁɛv ki kɔmɑ̃s/","zh":"这是一个梦想的开始","en":"It's a dream that begins","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-23-015","lineIndex":14,"speaker":"","original":"Dans les pages","ipa":"/dɑ̃ le paʒ/","zh":"在页面中","en":"In the pages","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-23-016","lineIndex":15,"speaker":"","original":"D'un conte de mon enfance","ipa":"/dœ̃ kɔ̃t də mɔ̃n ɑ̃fɑ̃s/","zh":"来自我小时候的一个故事","en":"From a tale from my childhood","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-23-017","lineIndex":16,"speaker":"","original":"Les yeux fermés","ipa":"/lez jø fɛʁme/","zh":"闭着眼睛","en":"Eyes closed","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-23-018","lineIndex":17,"speaker":"","original":"Mon prince enfin m'enlace","ipa":"/mɔ̃ pʁɛ̃s ɑ̃fɛ̃ mɑ̃las/","zh":"我的王子终于拥抱我了","en":"My prince finally embraces me","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-23-019","lineIndex":18,"speaker":"","original":"Et je prie pour que jamais Son étreinte ne se défasse","ipa":"/e ʒə pʁi puʁ kə ʒamɛ sɔ̃n etʁɛ̃t nə sə defas/","zh":"我祈祷永远不要愿他的拥抱永不松开。","en":"And I pray that never may his embrace never come undone.","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-23-021","lineIndex":19,"speaker":"","original":"Avec lui","ipa":"/avɛk lɥi/","zh":"和他一起","en":"With him","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-23-022","lineIndex":20,"speaker":"","original":"Je ne suis plus la même","ipa":"/ʒə nə sɥi ply la mɛm/","zh":"我不再是原来的我","en":"I am no longer the same","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-23-023","lineIndex":21,"speaker":"","original":"J'aime la pluie","ipa":"/ʒɛm la plɥi/","zh":"我喜欢下雨","en":"I like the rain","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-23-024","lineIndex":22,"speaker":"","original":"Et quand on se promène","ipa":"/e kɑ̃t ɔ̃ sə pʁomɛn/","zh":"当我们一起散步","en":"and when we walk together","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-23-025","lineIndex":23,"speaker":"","original":"Nos deux ombres","ipa":"/no døz ɔ̃bʁ/","zh":"我们的两个影子","en":"Our two shadows","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-23-026","lineIndex":24,"speaker":"","original":"Comme deux géants qui s'aiment","ipa":"/kɔm dø ʒeɑ̃ ki sɛm/","zh":"就像两个彼此相爱的巨人","en":"Like two giants who love each other","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-23-027","lineIndex":25,"speaker":"","original":"S'allongent à nos pieds Et vont se mirer dans la Seine","ipa":"/salɔ̃ʒt a no pjez e vɔ̃ sə miʁe dɑ̃ la sɛn/","zh":"躺在我们的脚下倒映在塞纳河中。","en":"Lie at our feet and are reflected in the Seine.","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-23-029","lineIndex":26,"speaker":"","original":"Je sais bien que j'ai tout inventé","ipa":"/ʒə sɛ bjɛ̃ kə ʒe tut ɛ̃vɑ̃te/","zh":"我知道这一切都是我编造的","en":"I know I made it all up","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-23-030","lineIndex":27,"speaker":"","original":"Je sais bien qu'il n'est jamais à mes côtés","ipa":"/ʒə sɛ bjɛ̃ kil nɛ ʒamɛz a me kote/","zh":"我知道他从来没有在我身边","en":"I know he's never by my side","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-23-031","lineIndex":28,"speaker":"","original":"Et pourtant, je continue à croire","ipa":"/e puʁtɑ̃ ʒə kɔ̃tiny a kʁwaʁ/","zh":"但我仍然相信","en":"And yet I continue to believe","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-23-032","lineIndex":29,"speaker":"","original":"Qu'avec lui, j'écris mon histoire","ipa":"/kavɛk lɥi ʒekʁi mɔ̃n istwaʁ/","zh":"和他一起，我写下我的故事","en":"That with him, I write my story","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-23-033","lineIndex":30,"speaker":"","original":"Oui, je l'aime","ipa":"/wi ʒə lɛm/","zh":"是的，我爱他。","en":"Yes, I love him.","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-23-034","lineIndex":31,"speaker":"","original":"Mais, comme les nuits sont courtes!","ipa":"/mɛ kɔm le nɥi sɔ̃ kuʁt/","zh":"但夜晚是多么短暂啊！","en":"But how short the nights are!","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-23-035","lineIndex":32,"speaker":"","original":"Au matin, il a repris sa route","ipa":"/o matɛ̃ il a ʁəpʁi sa ʁut/","zh":"早上，他继续赶路","en":"In the morning, he resumed his journey","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-23-036","lineIndex":33,"speaker":"","original":"Et le monde","ipa":"/e lə mɔ̃d/","zh":"还有世界","en":"And the world","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-23-037","lineIndex":34,"speaker":"","original":"Redevenu le même","ipa":"/ʁədəvny lə mɛm/","zh":"再次变得一样","en":"Become the same again","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-23-038","lineIndex":35,"speaker":"","original":"A perdu ses couleurs","ipa":"/a pɛʁdy se kulœʁ/","zh":"已经失去了颜色","en":"Has lost its colors","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-23-039","lineIndex":36,"speaker":"","original":"Et l'arc-en-ciel son diadème","ipa":"/e laʁkɑ̃sjɛl sɔ̃ djadɛm/","zh":"彩虹是它的王冠","en":"And the rainbow its diadem","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-23-040","lineIndex":37,"speaker":"","original":"Oui, je l'aime","ipa":"/wi ʒə lɛm/","zh":"是的，我爱他。","en":"Yes, I love him.","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-23-041","lineIndex":38,"speaker":"","original":"Mais je suis seule au monde","ipa":"/mɛ ʒə sɥi sœl o mɔ̃d/","zh":"但世界上只有我一个人","en":"But I'm alone in the world","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-23-042","lineIndex":39,"speaker":"","original":"Toute ma vie j'ai attendu une ombre","ipa":"/tut ma vi ʒe atɑ̃dy yn ɔ̃bʁ/","zh":"我一生都在等待一个身影。","en":"All my life I have waited for a shadow.","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-23-043","lineIndex":40,"speaker":"","original":"Mon histoire","ipa":"/mɔ̃n istwaʁ/","zh":"我的故事","en":"My story","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-23-044","lineIndex":41,"speaker":"","original":"Est une coquille vide","ipa":"/ɛt yn kokij vid/","zh":"是一个空壳","en":"Is an empty shell","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-23-045","lineIndex":42,"speaker":"","original":"Un rêve plein de douceur Dont je n'ai jamais eu ma part","ipa":"/œ̃ ʁɛv plɛ̃ də dusœʁ dɔ̃ ʒə ne ʒamɛz y ma paʁ/","zh":"一个充满甜蜜的梦而我从未分得其中的一份。","en":"A dream full of sweetness of which I have never had my share.","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-23-047","lineIndex":43,"speaker":"","original":"Et l'aime, oui je l'aime","ipa":"/e lɛm wi ʒə lɛm/","zh":"可我爱他，是的，我爱他。","en":"And I love him, yes, I love him.","note":"","sourceLineIndex":47},{"id":"les-miserables-cityprod-2017-23-048","lineIndex":44,"speaker":"","original":"Oui je l'aime","ipa":"/wi ʒə lɛm/","zh":"是的，我爱他。","en":"Yes, I love him.","note":"","sourceLineIndex":48},{"id":"les-miserables-cityprod-2017-23-049","lineIndex":45,"speaker":"","original":"Toute seule dans mon histoire","ipa":"/tut sœl dɑ̃ mɔ̃n istwaʁ/","zh":"独自在我的故事里","en":"All alone in my story","note":"","sourceLineIndex":49}],"sourceOrder":23,"displayOrder":22},{"order":24,"id":"24-sur-la-barricade","title":"Sur la barricade","titleZh":"在路障上","lines":[{"id":"les-miserables-cityprod-2017-24-001","lineIndex":1,"speaker":"","original":"Jurons de tenir jusqu'au bout cette barricade","ipa":"/ʒyʁɔ̃ də təniʁ ʒysko bu sɛt baʁikad/","zh":"让我们发誓要守住这个路障直到最后","en":"Let's swear to hold this barricade until the end","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-24-002","lineIndex":2,"speaker":"","original":"Leurs légions de mercenaires trouveront à qui parler","ipa":"/lœʁ leʒjɔ̃ də mɛʁsənɛʁ tʁuvʁɔ̃t a ki paʁle/","zh":"他们的雇佣兵军团会知道该跟谁较量。","en":"Their legions of mercenaries will find someone to talk to","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-24-003","lineIndex":3,"speaker":"","original":"Ils n'ont que des ordres nous avons la foi","ipa":"/il nɔ̃ kə dez ɔʁdʁ nuz avɔ̃ la fwa/","zh":"他们只有命令，我们有信心","en":"They only have orders we have faith","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-24-004","lineIndex":4,"speaker":"","original":"Donnons-leur une leçon qu'ils n'oublieront pas","ipa":"/dɔnɔ̃lœʁ yn ləsɔ̃ kil nubliʁɔ̃ pa/","zh":"让我们给他们一个他们不会忘记的教训","en":"Let's teach them a lesson they won't forget","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-24-005","lineIndex":5,"speaker":"","original":"C'est l'heure de vérité!","ipa":"/sɛ lœʁ də veʁite/","zh":"这是关键时刻！","en":"It's the moment of truth!","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-24-006","lineIndex":6,"speaker":"","original":"Et s'il faut mourir pour défendre la cause","ipa":"/e sil fo muʁiʁ puʁ defɑ̃dʁ la koz/","zh":"若必须为捍卫事业而死","en":"And if you have to die to defend the cause","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-24-007","lineIndex":7,"speaker":"","original":"Au plus fort de la bataille je serai là","ipa":"/o ply fɔʁ də la bataj ʒə səʁe la/","zh":"在战斗最激烈的时候我会在那里","en":"At the height of the battle I will be there","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-24-008","lineIndex":8,"speaker":"","original":"Oui, qu'ils viennent si ils l'osent on y sera!","ipa":"/wi kil vjɛn si il lozt ɔ̃n i səʁa/","zh":"是的，只要他们敢来就让他们来，我们就在那里！","en":"Yes, let them come if they dare, we will be there!","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-24-009","lineIndex":9,"speaker":"","original":"Vous à la barricade, écoutez bien","ipa":"/vuz a la baʁikad ekute bjɛ̃/","zh":"路障上的人，仔细听着：","en":"You at the barricade, listen carefully","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-24-010","lineIndex":10,"speaker":"","original":"Nul ne viendra vous aider à combattre","ipa":"/nyl nə vjɛ̃dʁa vuz ɛde a kɔ̃batʁ/","zh":"没有人会来帮你战斗","en":"No one will come to help you fight","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-24-011","lineIndex":11,"speaker":"","original":"Vous êtes tous seuls il faut choisir","ipa":"/vuz ɛt tus sœlz il fo ʃwaziʁ/","zh":"你们孤立无援，必须作出选择：","en":"You are all alone, you have to choose","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-24-012","lineIndex":12,"speaker":"","original":"Se rendre ou bien mourir!","ipa":"/sə ʁɑ̃dʁ u bjɛ̃ muʁiʁ/","zh":"要么投降，要么死！","en":"Surrender or die!","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-24-013","lineIndex":13,"speaker":"","original":"Merde aux oiseaux de malheur","ipa":"/mɛʁd oz wazo də malœʁ/","zh":"该死的厄运之鸟","en":"Damn the birds of doom","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-24-014","lineIndex":14,"speaker":"","original":"Ils ont peur du peuple en armes!","ipa":"/ilz ɔ̃ pœʁ dy pøpl ɑ̃n aʁm/","zh":"他们害怕武装起来的人民！","en":"They are afraid of the armed people!","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-24-015","lineIndex":15,"speaker":"","original":"Merde aux sbires et aux menteurs","ipa":"/mɛʁd o zbiʁz e o mɑ̃tœʁ/","zh":"该死的追随者和骗子","en":"Damn the henchmen and the liars","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-24-016","lineIndex":16,"speaker":"","original":"Ils verront le peuple vainqueur!","ipa":"/il vɛʁɔ̃ lə pøpl vɛ̃kœʁ/","zh":"他们将看到人民的胜利！","en":"They will see the people victorious!","note":"","sourceLineIndex":16}],"sourceOrder":24,"displayOrder":23},{"order":25,"id":"25-je-sais-ce-qui-se-trame","title":"Je sais ce qui se trame","titleZh":"我知道发生了什么事","lines":[{"id":"les-miserables-cityprod-2017-25-001","lineIndex":1,"speaker":"","original":"Écoutez-moi","ipa":"/ekutemwa/","zh":"听我说","en":"Listen to me","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-25-002","lineIndex":2,"speaker":"","original":"J'ai flairé leurs tanières","ipa":"/ʒe flɛʁe lœʁ tanjɛʁ/","zh":"我已摸清他们的巢穴","en":"I smelled their dens","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-25-003","lineIndex":3,"speaker":"","original":"J'ai infiltré leurs lignes","ipa":"/ʒə ɛ̃filtʁe lœʁ linj/","zh":"还潜入过他们的阵线","en":"I infiltrated their lines","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-25-004","lineIndex":4,"speaker":"","original":"Compté leurs effectifs","ipa":"/kɔ̃te lœʁz efɛktif/","zh":"数了一下他们的人数","en":"Counted their numbers","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-25-005","lineIndex":5,"speaker":"","original":"Vu leurs stocks d'explosifs","ipa":"/vy lœʁ stɔk dɛksplozif/","zh":"看过他们的炸药储备。","en":"Considering their stocks of explosives","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-25-006","lineIndex":6,"speaker":"","original":"Je vous préviens","ipa":"/ʒə vu pʁevjɛ̃/","zh":"我警告你","en":"I warn you","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-25-007","lineIndex":7,"speaker":"","original":"Ils ont des hommes en nombre","ipa":"/ilz ɔ̃ dez ɔmz ɑ̃ nɔ̃bʁ/","zh":"他们兵力充足","en":"They have many men","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-25-008","lineIndex":8,"speaker":"","original":"Le danger est réel","ipa":"/lə dɑ̃ʒe ɛ ʁeɛl/","zh":"危险是真实存在的","en":"The danger is real","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-25-009","lineIndex":9,"speaker":"","original":"Il faudra jouer serré","ipa":"/il fodʁa ʒwe sɛʁe/","zh":"你必须打得很紧","en":"You will have to play tight","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-25-010","lineIndex":10,"speaker":"","original":"Pour les impressionner","ipa":"/puʁ lez ɛ̃pʁɛsjɔne/","zh":"给他们留下深刻印象","en":"To impress them","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-25-011","lineIndex":11,"speaker":"","original":"Confiance","ipa":"/kɔ̃fjɑ̃s/","zh":"信任","en":"Trust","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-25-012","lineIndex":12,"speaker":"","original":"Si on sait quels sont leurs mouvements on fausse leur jeu","ipa":"/si ɔ̃ sɛ kɛl sɔ̃ lœʁ muvmɑ̃z ɔ̃ fos lœʁ ʒø/","zh":"如果我们知道他们的动作，我们就会扭曲他们的游戏","en":"If we know what their movements are we distort their game","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-25-013","lineIndex":13,"speaker":"","original":"Nous avons l'idéal qu'ils n'ont pas pour contrer leur puissance de feu","ipa":"/nuz avɔ̃ lideal kil nɔ̃ pa puʁ kɔ̃tʁe lœʁ pɥisɑ̃s də fø/","zh":"我们的理想是他们不必对抗他们的火力","en":"We have the ideal that they don't have to counter their firepower","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-25-014","lineIndex":14,"speaker":"","original":"Oui, je sais ce qui se trame","ipa":"/wi ʒə sɛ sə ki sə tʁam/","zh":"是的，我知道发生了什么事","en":"Yes, I know what's going on","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-25-015","lineIndex":15,"speaker":"","original":"Il n'y aura pas d'attaque cette nuit","ipa":"/il ni oʁa pa datak sɛt nɥi/","zh":"今晚不会有袭击","en":"There will be no attack tonight","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-25-016","lineIndex":16,"speaker":"","original":"Mais ils vont nous affamer","ipa":"/mɛz il vɔ̃ nuz afame/","zh":"但他们会让我们挨饿","en":"But they will starve us","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-25-017","lineIndex":17,"speaker":"","original":"Pour nous tenir à leur merci","ipa":"/puʁ nu təniʁ a lœʁ mɛʁsi/","zh":"让我们受他们的摆布","en":"To keep us at their mercy","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-25-018","lineIndex":18,"speaker":"","original":"Puis nous prendre en tenaille","ipa":"/pɥi nu pʁɑ̃dʁ ɑ̃ tənaj/","zh":"然后把我们夹在钳子里","en":"Then take us in pincers","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-25-019","lineIndex":19,"speaker":"","original":"En une seule bataille","ipa":"/ɑ̃n yn sœl bataj/","zh":"在一场战斗中","en":"In a single battle","note":"","sourceLineIndex":19}],"sourceOrder":25,"displayOrder":24},{"order":26,"id":"26-c-est-la-faute-a","title":"C'est la faute à...","titleZh":"这是...的错","lines":[{"id":"les-miserables-cityprod-2017-26-001","lineIndex":1,"speaker":"","original":"Menteur!","ipa":"/mɑ̃tœʁ/","zh":"骗子！","en":"Liar!","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-26-002","lineIndex":2,"speaker":"","original":"Cher inspecteur Javert je te fais mes salutations","ipa":"/ʃɛʁ ɛ̃spɛktœʁ ʒavɛʁ ʒə tə fɛ me salytasjɔ̃/","zh":"亲爱的沙威督察，我向您致以问候","en":"Dear Inspector Javert, I send you my greetings","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-26-003","lineIndex":3,"speaker":"","original":"Je suis petit peut-être mais j'ai oublié d'être con!","ipa":"/ʒə sɥi pəti pøtɛtʁ mɛ ʒe ublie dɛtʁ kɔ̃/","zh":"我个子小，可没傻到那份上！","en":"I may be small, but I am not that stupid!","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-26-004","lineIndex":4,"speaker":"","original":"Tu te crois le plus mariole mais faut que t'entraves une bonne fois","ipa":"/ty tə kʁwa lə ply maʁjɔl mɛ fo kə tɑ̃tʁavz yn bɔn fwa/","zh":"你自以为最聪明，可你得好好明白一回","en":"You think you're the cleverest, but you need to understand once and for all","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-26-005","lineIndex":5,"speaker":"","original":"Qu'on peut se faire piéger par un plus minot que soi","ipa":"/kɔ̃ pø sə fɛʁ pjeʒe paʁ œ̃ ply mino kə swa/","zh":"人也会栽在比自己更小的小鬼手里。","en":"that you can be trapped by a kid smaller than yourself.","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-26-006","lineIndex":6,"speaker":"","original":"Je suis tombé par terre","ipa":"/ʒə sɥi tɔ̃be paʁ tɛʁ/","zh":"我摔倒在地","en":"I fell to the ground","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-26-007","lineIndex":7,"speaker":"","original":"C'est la faute à Voltaire","ipa":"/sɛ la fot a vɔltɛʁ/","zh":"都是伏尔泰的错","en":"It's Voltaire's fault","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-26-008","lineIndex":8,"speaker":"","original":"Le nez dans le ruisseau","ipa":"/lə ne dɑ̃ lə ʁyiso/","zh":"脸栽进了水沟","en":"My nose in the gutter","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-26-009","lineIndex":9,"speaker":"","original":"C'est la faute à Rousseau","ipa":"/sɛ la fot a ʁuso/","zh":"都是卢梭的错","en":"It's Rousseau's fault","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-26-010","lineIndex":10,"speaker":"","original":"Les gamins de Paname Ont pas le temps d'être des gniards Nous on va au pétard","ipa":"/le ɡamɛ̃ də panam ɔ̃ pa lə tɑ̃ dɛtʁ de ɲjaʁ nuz ɔ̃ va o petaʁ/","zh":"巴黎的小孩们没空当没出息的小鬼我们可是要上真战场。","en":"The kids from Paris don't have time to be little brats we're heading into the fight.","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-26-013","lineIndex":11,"speaker":"","original":"Et si ça vous épate","ipa":"/e si sa vuz epat/","zh":"如果它让你大吃一惊","en":"And if it blows your mind","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-26-014","lineIndex":12,"speaker":"","original":"Relisez donc l'histoire","ipa":"/ʁəlize dɔ̃k listwaʁ/","zh":"所以重读这个故事","en":"So reread the story","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-26-015","lineIndex":13,"speaker":"","original":"De David et Goliath!","ipa":"/də david e ɡɔlja/","zh":"来自大卫和歌利亚！","en":"From David and Goliath!","note":"","sourceLineIndex":15}],"sourceOrder":26,"displayOrder":25},{"order":27,"id":"27-la-premiere-attaque","title":"La première attaque","titleZh":"第一次攻击","lines":[{"id":"les-miserables-cityprod-2017-27-001","lineIndex":1,"speaker":"","original":"Un peloton de sapeurs","ipa":"/œ̃ pəlotɔ̃ də sapœʁ/","zh":"一排工兵","en":"A platoon of sappers","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-27-002","lineIndex":2,"speaker":"","original":"S'avance vers la barricade!","ipa":"/savɑ̃s vɛʁ la baʁikad/","zh":"向路障移动！","en":"Move towards the barricade!","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-27-003","lineIndex":3,"speaker":"","original":"Avec des renforts!","ipa":"/avɛk de ʁɑ̃fɔʁ/","zh":"有援军！","en":"With reinforcements!","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-27-004","lineIndex":4,"speaker":"","original":"Au moins cinquante hommes!","ipa":"/o mwɛ̃ sɛ̃kɑ̃t ɔm/","zh":"至少有五十人！","en":"At least fifty men!","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-27-005","lineIndex":5,"speaker":"","original":"Feu!","ipa":"/fø/","zh":"火！","en":"Fire!","note":"","sourceLineIndex":5}],"sourceOrder":27,"displayOrder":26},{"order":28,"id":"28-un-peu-de-sang-qui-pleure","title":"Un peu de sang qui pleure","titleZh":"一滴哭泣的血","lines":[{"id":"les-miserables-cityprod-2017-28-001","lineIndex":1,"speaker":"","original":"Ce n'est rien, monsieur Marius","ipa":"/sə nɛ ʁjɛ̃ məsjø maʁjys/","zh":"没什么，马吕斯先生","en":"It's nothing, Mr. Marius","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-28-002","lineIndex":2,"speaker":"","original":"Je ne sens plus la douleur","ipa":"/ʒə nə sɑ̃ ply la dulœʁ/","zh":"我不再感到疼痛了","en":"I don't feel the pain anymore","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-28-003","lineIndex":3,"speaker":"","original":"Un peu de sang qui pleure","ipa":"/œ̃ pø də sɑ̃ ki plœʁ/","zh":"一滴仿佛在哭泣的血。","en":"A little blood that weeps.","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-28-004","lineIndex":4,"speaker":"","original":"Quelques gouttes de pluie","ipa":"/kɛlkə ɡut də plɥi/","zh":"几滴雨","en":"A few drops of rain","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-28-005","lineIndex":5,"speaker":"","original":"C'est vous!","ipa":"/sɛ vu/","zh":"是你！","en":"It's you!","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-28-006","lineIndex":6,"speaker":"","original":"C'est tout ce qui compte pour moi","ipa":"/sɛ tu sə ki kɔ̃t puʁ mwa/","zh":"这对我来说才是最重要的","en":"That's all that matters to me","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-28-007","lineIndex":7,"speaker":"","original":"Vous me protégerez","ipa":"/vu mə pʁoteʒʁe/","zh":"你会保护我","en":"You will protect me","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-28-008","lineIndex":8,"speaker":"","original":"Blottie sur votre cœur","ipa":"/blɔti syʁ votʁ kœʁ/","zh":"依偎在你的心上","en":"Nestled on your heart","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-28-009","lineIndex":9,"speaker":"","original":"La pluie fera pousser les fleurs","ipa":"/la plɥi fəʁa puse le flœʁ/","zh":"雨会让花儿生长","en":"The rain will make the flowers grow","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-28-010","lineIndex":10,"speaker":"","original":"Mais tu vas vivre, Ponine","ipa":"/mɛ ty va vivʁ ponin/","zh":"但你会活下去，波妮","en":"But you will live, Ponine","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-28-011","lineIndex":11,"speaker":"","original":"Regarde-moi","ipa":"/ʁəɡaʁdmwa/","zh":"看着我","en":"Look at me","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-28-012","lineIndex":12,"speaker":"","original":"L'amour saura refermer","ipa":"/lamuʁ soʁa ʁəfɛʁme/","zh":"爱才会懂得关闭","en":"Love will know how to close","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-28-013","lineIndex":13,"speaker":"","original":"Ta blessure","ipa":"/ta blɛsyʁ/","zh":"你的伤口","en":"Your wound","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-28-014","lineIndex":14,"speaker":"","original":"Abritez-moi, réchauffez-moi","ipa":"/abʁitemwa ʁeʃofemwa/","zh":"庇护我，温暖我","en":"Shelter me, warm me","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-28-015","lineIndex":15,"speaker":"","original":"Je vais mieux dans vos bras","ipa":"/ʒə vɛ mjø dɑ̃ vo bʁa/","zh":"我在你怀里感觉好多了","en":"I feel better in your arms","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-28-016","lineIndex":16,"speaker":"","original":"Tu vivras jusqu'à cent ans","ipa":"/ty vivʁa ʒyska sɑ̃ ɑ̃/","zh":"你会活到一百岁","en":"You will live to be a hundred years old","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-28-017","lineIndex":17,"speaker":"","original":"Si tu me laisses t'apprendre","ipa":"/si ty mə lɛs tapʁɑ̃dʁ/","zh":"如果你让我教你","en":"If you let me teach you","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-28-018","lineIndex":18,"speaker":"","original":"Si tu veux bien m'entendre...","ipa":"/si ty vø bjɛ̃ mɑ̃tɑ̃dʁ/","zh":"如果你想听我说...","en":"If you would like to hear me...","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-28-019","lineIndex":19,"speaker":"","original":"Dernières gouttes de pluie","ipa":"/dɛʁnjɛʁ ɡut də plɥi/","zh":"最后一滴雨","en":"Last drops of rain","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-28-020","lineIndex":20,"speaker":"","original":"Vous êtes le printemps qui revient","ipa":"/vuz ɛt lə pʁɛ̃tɑ̃ ki ʁəvjɛ̃/","zh":"你是归来的春天","en":"You are the spring that returns","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-28-021","lineIndex":21,"speaker":"","original":"Vous me protégerez","ipa":"/vu mə pʁoteʒʁe/","zh":"你会保护我","en":"You will protect me","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-28-022","lineIndex":22,"speaker":"","original":"Très fort serrée, tout près","ipa":"/tʁɛ fɔʁ sɛʁe tu pʁɛ/","zh":"非常紧，非常接近","en":"Very tight, very close","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-28-023","lineIndex":23,"speaker":"","original":"Dormir entre vos bras, enfin","ipa":"/dɔʁmiʁ ɑ̃tʁ vo bʁa ɑ̃fɛ̃/","zh":"终于可以睡在你怀里了","en":"To sleep in your arms, finally","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-28-024","lineIndex":24,"speaker":"","original":"Que soit bénie la pluie Qui vous ramène","ipa":"/kə swa beni la plyi ki vu ʁamɛn/","zh":"愿这场雨得到祝福因为它把您带回我身边。","en":"Blessed be the rain that brings you back to me.","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-28-026","lineIndex":25,"speaker":"","original":"Je me sens bien","ipa":"/ʒə mə sɑ̃ bjɛ̃/","zh":"我感觉很好","en":"I feel good","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-28-027","lineIndex":26,"speaker":"","original":"Mais d'où vient cette lumière?","ipa":"/mɛ du vjɛ̃ sɛt lymjɛʁ/","zh":"但这光从哪里来呢？","en":"But where does this light come from?","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-28-028","lineIndex":27,"speaker":"","original":"Un souffle à peine qui nous sépare","ipa":"/œ̃ sufl a pɛn ki nu sepaʁ/","zh":"我们之间只有一个呼吸的距离","en":"Barely a breath separates us","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-28-029","lineIndex":28,"speaker":"","original":"Il n'était pas trop tard","ipa":"/il netɛ pa tʁo taʁ/","zh":"还不算太晚","en":"It wasn't too late","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-28-030","lineIndex":29,"speaker":"","original":"Non, ce n'est rien, monsieur","ipa":"/nɔ̃ sə nɛ ʁjɛ̃ məsjø/","zh":"不，没什么，先生","en":"No, it's nothing, sir","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-28-031","lineIndex":30,"speaker":"","original":"Dors en paix, chère Éponine","ipa":"/dɔʁz ɑ̃ pɛ ʃɛʁ eponin/","zh":"安息吧，亲爱的艾潘妮","en":"Sleep in peace, dear Éponine","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-28-032","lineIndex":31,"speaker":"","original":"Je ne sens plus la douleur","ipa":"/ʒə nə sɑ̃ ply la dulœʁ/","zh":"我不再感到疼痛了","en":"I don't feel the pain anymore","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-28-033","lineIndex":32,"speaker":"","original":"Tu ne sens plus la douleur","ipa":"/ty nə sɑ̃ ply la dulœʁ/","zh":"你不再感到疼痛","en":"You don't feel the pain anymore","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-28-034","lineIndex":33,"speaker":"","original":"Un peu de sang qui pleure","ipa":"/œ̃ pø də sɑ̃ ki plœʁ/","zh":"一滴仿佛在哭泣的血。","en":"A little blood that weeps.","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-28-035","lineIndex":34,"speaker":"","original":"Un peu de sang qui pleure","ipa":"/œ̃ pø də sɑ̃ ki plœʁ/","zh":"一滴仿佛在哭泣的血。","en":"A little blood that weeps.","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-28-036","lineIndex":35,"speaker":"","original":"Quelques gouttes de pluie","ipa":"/kɛlkə ɡut də plɥi/","zh":"几滴雨","en":"A few drops of rain","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-28-037","lineIndex":36,"speaker":"","original":"Quelques gouttes de pluie","ipa":"/kɛlkə ɡut də plɥi/","zh":"几滴雨","en":"A few drops of rain","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-28-038","lineIndex":37,"speaker":"","original":"C'est moi","ipa":"/sɛ mwa/","zh":"是我","en":"It's me","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-28-039","lineIndex":38,"speaker":"","original":"C'est tout ce qui compte pour moi","ipa":"/sɛ tu sə ki kɔ̃t puʁ mwa/","zh":"这对我来说才是最重要的","en":"That's all that matters to me","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-28-040","lineIndex":39,"speaker":"","original":"Vous me protégerez","ipa":"/vu mə pʁoteʒʁe/","zh":"你会保护我","en":"You will protect me","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-28-041","lineIndex":40,"speaker":"MARIUS","original":"J'attendrai là","ipa":"/ʒatɑ̃dʁe la/","zh":"我会在那里等","en":"I will wait there","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-28-042","lineIndex":41,"speaker":"MARIUS","original":"Blottie sur votre cœur","ipa":"/blɔti syʁ votʁ kœʁ/","zh":"依偎在你的心上","en":"Nestled on your heart","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-28-043","lineIndex":42,"speaker":"MARIUS","original":"Que tu t'endormes","ipa":"/kə ty tɑ̃dɔʁm/","zh":"等你睡着了","en":"That you fall asleep","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-28-044","lineIndex":43,"speaker":"MARIUS","original":"La pluie","ipa":"/la plɥi/","zh":"雨","en":"The rain","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-28-045","lineIndex":44,"speaker":"MARIUS","original":"La pluie","ipa":"/la plɥi/","zh":"雨","en":"The rain","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-28-046","lineIndex":45,"speaker":"MARIUS","original":"Fera pousser...","ipa":"/fəʁa puse/","zh":"会成长...","en":"Will grow...","note":"","sourceLineIndex":46},{"id":"les-miserables-cityprod-2017-28-047","lineIndex":46,"speaker":"MARIUS","original":"Fera pousser... Les fleurs.","ipa":"/fəʁa puse le flœʁ/","zh":"会长出……花。","en":"Will grow... Flowers.","note":"","sourceLineIndex":47}],"sourceOrder":28,"displayOrder":27},{"order":29,"id":"29-souviens-toi-des-jours-passes","title":"Souviens toi des jours passés","titleZh":"记住过去的日子","lines":[{"id":"les-miserables-cityprod-2017-29-001","lineIndex":1,"speaker":"","original":"Souviens-toi des jours passés","ipa":"/suvjɛ̃twa de ʒuʁ pase/","zh":"记住过去的日子","en":"Remember days gone by","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-29-002","lineIndex":2,"speaker":"","original":"Des chansons qu'on a chantées","ipa":"/de ʃɑ̃sɔ̃ kɔ̃n a ʃɑ̃te/","zh":"我们唱过的歌","en":"Songs that we sang","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-29-003","lineIndex":3,"speaker":"","original":"Des printemps d'amour","ipa":"/de pʁɛ̃tɑ̃ damuʁ/","zh":"恋爱的春日","en":"springs of love","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-29-004","lineIndex":4,"speaker":"","original":"Et des filles en fleur Qui nous ont ouvert Leur lit et leur cœur","ipa":"/e de fijz ɑ̃ flœʁ ki nuz ɔ̃t uvɛʁ lœʁ li e lœʁ kœʁ/","zh":"还有那些如花盛放的姑娘向我们敞开了她们的床与心。","en":"and girls in bloom who opened to us their beds and their hearts.","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-29-007","lineIndex":5,"speaker":"","original":"Buvons tous à leur santé","ipa":"/byvɔ̃ tus a lœʁ sɑ̃te/","zh":"让我们为她们干杯。","en":"Let us all drink to their health.","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-29-008","lineIndex":6,"speaker":"","original":"Souviens-toi des jours passés","ipa":"/suvjɛ̃twa de ʒuʁ pase/","zh":"记住过去的日子","en":"Remember days gone by","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-29-009","lineIndex":7,"speaker":"","original":"N'aie pas peur quand l'heure viendra","ipa":"/nɛ pa pœʁ kɑ̃ lœʁ vjɛ̃dʁa/","zh":"时机成熟时不要害怕","en":"Don't be afraid when the time comes","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-29-010","lineIndex":8,"speaker":"","original":"La vie dure si peu et elle ne vaut rien","ipa":"/la vi dyʁ si pø e ɛl nə vo ʁjɛ̃/","zh":"人生短得很，也不值什么。","en":"Life is so short, and worth nothing.","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-29-011","lineIndex":9,"speaker":"","original":"Je la brûle au feu d'un bon verre de vin","ipa":"/ʒə la bʁyl o fø dœ̃ bɔ̃ vɛʁ də vɛ̃/","zh":"我就把它烧进一杯好酒的火焰里。","en":"I burn it in the fire of a good glass of wine.","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-29-012","lineIndex":10,"speaker":"","original":"Et ta mort ne sert à rien","ipa":"/e ta mɔʁ nə sɛʁ a ʁjɛ̃/","zh":"而你的死也毫无意义","en":"And your death is useless","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-29-013","lineIndex":11,"speaker":"","original":"Souviens-toi","ipa":"/suvjɛ̃twa/","zh":"记住","en":"Remember","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-29-014","lineIndex":12,"speaker":"","original":"Des jours","ipa":"/de ʒuʁ/","zh":"那些日子","en":"the days","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-29-015","lineIndex":13,"speaker":"","original":"Passés","ipa":"/pase/","zh":"已经过去","en":"gone by","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-29-016","lineIndex":14,"speaker":"","original":"Des folies","ipa":"/de foli/","zh":"那些疯狂事","en":"the follies","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-29-017","lineIndex":15,"speaker":"","original":"Qu'on a","ipa":"/kɔ̃n a/","zh":"我们曾","en":"that we","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-29-018","lineIndex":16,"speaker":"","original":"Osées","ipa":"/oze/","zh":"大胆做过。","en":"dared to do.","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-29-019","lineIndex":17,"speaker":"","original":"Souviens-toi","ipa":"/suvjɛ̃twa/","zh":"记住","en":"Remember","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-29-020","lineIndex":18,"speaker":"","original":"Des jours","ipa":"/de ʒuʁ/","zh":"那些日子","en":"the days","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-29-021","lineIndex":19,"speaker":"","original":"Passés","ipa":"/pase/","zh":"已经过去","en":"gone by","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-29-022","lineIndex":20,"speaker":"","original":"Des folies","ipa":"/de foli/","zh":"那些疯狂事","en":"the follies","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-29-023","lineIndex":21,"speaker":"","original":"Qu'on a","ipa":"/kɔ̃n a/","zh":"我们曾","en":"that we","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-29-024","lineIndex":22,"speaker":"","original":"Osées","ipa":"/oze/","zh":"大胆做过。","en":"dared to do.","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-29-025","lineIndex":23,"speaker":"","original":"Que ne meure jamais l'amitié sincère","ipa":"/kə nə mœʁ ʒamɛ lamitje sɛ̃sɛʁ/","zh":"愿真挚的友谊永不消逝","en":"May sincere friendship never die","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-29-026","lineIndex":24,"speaker":"","original":"Ce vin d'amitié qui coule en nos verres","ipa":"/sə vɛ̃ damitje ki kul ɑ̃ no vɛʁ/","zh":"这友谊之酒流入我们的杯中","en":"This wine of friendship that flows into our glasses","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-29-027","lineIndex":25,"speaker":"","original":"Je le bois","ipa":"/ʒə lə bwa/","zh":"我喝它","en":"I drink it","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-29-028","lineIndex":26,"speaker":"","original":"À ta Santé","ipa":"/a ta sɑ̃te/","zh":"敬你的健康。","en":"To your health.","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-29-030","lineIndex":27,"speaker":"","original":"Je le bois","ipa":"/ʒə lə bwa/","zh":"我喝它","en":"I drink it","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-29-031","lineIndex":28,"speaker":"","original":"À ta Santé","ipa":"/a ta sɑ̃te/","zh":"敬你的健康。","en":"To your health.","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-29-033","lineIndex":29,"speaker":"","original":"J'attends comme la délivrance La balle qui m'est destinée","ipa":"/ʒatɑ̃ kɔm la delivʁɑ̃s la bal ki mɛ dɛstine/","zh":"我等待它，如同等待解脱那颗注定射向我的子弹。","en":"I await, as a deliverance the bullet meant for me.","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-29-035","lineIndex":30,"speaker":"","original":"Ma vie sans Cosette","ipa":"/ma vi sɑ̃ kozɛt/","zh":"我的生活没有珂赛特","en":"My life without Cosette","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-29-036","lineIndex":31,"speaker":"","original":"Ne veut plus rien dire","ipa":"/nə vø ply ʁjɛ̃ diʁ/","zh":"已经没有任何意义了","en":"Doesn't mean anything anymore","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-29-037","lineIndex":32,"speaker":"","original":"Pleureras-tu, Cosette","ipa":"/pløʁʁaty kozɛt/","zh":"你会哭吗，珂赛特","en":"Will you cry, Cosette","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-29-038","lineIndex":33,"speaker":"","original":"S'il me faut mourir?","ipa":"/sil mə fo muʁiʁ/","zh":"如果我必须死？","en":"If I have to die?","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-29-039","lineIndex":34,"speaker":"","original":"Pleureras-tu, Cosette","ipa":"/pløʁʁaty kozɛt/","zh":"你会哭吗，珂赛特","en":"Will you cry, Cosette","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-29-040","lineIndex":35,"speaker":"","original":"Pour moi","ipa":"/puʁ mwa/","zh":"对我来说","en":"For me","note":"","sourceLineIndex":40}],"sourceOrder":29,"displayOrder":28},{"order":30,"id":"30-comme-un-homme","title":"Comme un homme","titleZh":"像个男人一样","lines":[{"id":"les-miserables-cityprod-2017-30-001","lineIndex":1,"speaker":"","original":"Dieu du ciel, notre Père","ipa":"/djø dy sjɛl notʁ pɛʁ/","zh":"天上的神，我们的父","en":"God of heaven, our Father","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-30-002","lineIndex":2,"speaker":"","original":"Je t'implore d'écouter ma prière","ipa":"/ʒə tɛ̃plɔʁ dekute ma pʁiɛʁ/","zh":"我恳求你聆听我的祈祷","en":"I implore you to hear my prayer","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-30-003","lineIndex":3,"speaker":"","original":"Il est jeune, il a peur","ipa":"/il ɛ ʒøn il a pœʁ/","zh":"他还年轻，他害怕","en":"He's young, he's scared","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-30-004","lineIndex":4,"speaker":"","original":"Laisse éclore une fleur","ipa":"/lɛs eklɔʁ yn flœʁ/","zh":"让一朵花绽放","en":"Let a flower bloom","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-30-005","lineIndex":5,"speaker":"","original":"Laisse-le vivre, comme un homme","ipa":"/lɛslə vivʁ kɔm œ̃n ɔm/","zh":"让他像个男人一样生活","en":"Let him live, like a man","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-30-006","lineIndex":6,"speaker":"","original":"Comme un homme","ipa":"/kɔm œ̃n ɔm/","zh":"像个男人一样","en":"Like a man","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-30-007","lineIndex":7,"speaker":"","original":"Il est le fils que j'aurais eu","ipa":"/il ɛ lə fis kə ʒoʁɛz y/","zh":"他是我想要的儿子","en":"He is the son I would have had","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-30-008","lineIndex":8,"speaker":"","original":"Si tu m'avais donné un fils","ipa":"/si ty mavɛ dɔne œ̃ fis/","zh":"如果你给了我一个儿子","en":"If you had given me a son","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-30-009","lineIndex":9,"speaker":"","original":"Les êtres meurent, un à un","ipa":"/lez ɛtʁ mœʁ œ̃n a œ̃/","zh":"众生一一死去","en":"Beings die, one by one","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-30-010","lineIndex":10,"speaker":"","original":"Je sens mon cœur qui s'éteint","ipa":"/ʒə sɑ̃ mɔ̃ kœʁ ki setɛ̃/","zh":"我感觉我的心正在死去","en":"I feel my heart dying","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-30-011","lineIndex":11,"speaker":"","original":"J'ai fait mon temps, et je t'attends","ipa":"/ʒe fɛ mɔ̃ tɑ̃ e ʒə tatɑ̃/","zh":"我已经完成了我的时间，我正在等你","en":"I've done my time, and I'm waiting for you","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-30-012","lineIndex":12,"speaker":"","original":"Mais qu'il vive, et qu'il chante","ipa":"/mɛ kil viv e kil ʃɑ̃t/","zh":"但让他活着，让他唱歌","en":"But let him live, and let him sing","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-30-013","lineIndex":13,"speaker":"","original":"Il est jeune, c'est encore un enfant","ipa":"/il ɛ ʒøn sɛt ɑ̃kɔʁ œ̃n ɑ̃fɑ̃/","zh":"他还年轻，他还是个孩子","en":"He's young, he's still a child","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-30-014","lineIndex":14,"speaker":"","original":"Toi qui donnes, toi qui prends","ipa":"/twa ki dɔn twa ki pʁɑ̃/","zh":"给予的你，索取的你","en":"You who give, you who take","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-30-015","lineIndex":15,"speaker":"","original":"Laisse-le rire et aimer","ipa":"/lɛslə ʁiʁ e ɛme/","zh":"让他笑，让他爱","en":"Let him laugh and love","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-30-016","lineIndex":16,"speaker":"","original":"Que je meure et qu'il vive","ipa":"/kə ʒə mœʁ e kil viv/","zh":"我死了，他还活着","en":"That I die and he lives","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-30-017","lineIndex":17,"speaker":"","original":"Laisse-le vivre, comme un homme","ipa":"/lɛslə vivʁ kɔm œ̃n ɔm/","zh":"让他像个男人一样生活","en":"Let him live, like a man","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-30-018","lineIndex":18,"speaker":"","original":"Comme un homme","ipa":"/kɔm œ̃n ɔm/","zh":"像个男人一样","en":"Like a man","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-30-019","lineIndex":19,"speaker":"","original":"Comme un homme","ipa":"/kɔm œ̃n ɔm/","zh":"像个男人一样","en":"Like a man","note":"","sourceLineIndex":19}],"sourceOrder":30,"displayOrder":29},{"order":31,"id":"31-fureurs-cannibales","title":"Fureurs cannibales","titleZh":"食人般的狂怒","lines":[{"id":"les-miserables-cityprod-2017-31-001","lineIndex":1,"speaker":"","original":"Un petit gramme d'or est caché sous une dent","ipa":"/œ̃ pəti ɡʁam dɔʁ ɛ kaʃe suz yn dɑ̃/","zh":"牙齿下面藏着一小克黄金","en":"A small gram of gold is hidden under a tooth","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-31-002","lineIndex":2,"speaker":"","original":"Excusez mon prince vous becterez plus rien maintenant","ipa":"/ɛkskyze mɔ̃ pʁɛ̃s vu bɛktəʁe ply ʁjɛ̃ mɛ̃tnɑ̃/","zh":"对不起，王子殿下，您现在再也吃不了东西了。","en":"Excuse me, my prince, you will not eat another thing now.","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-31-003","lineIndex":3,"speaker":"","original":"Faites une fleur à un vivant un joujou de plus","ipa":"/fɛtz yn flœʁ a œ̃ vivɑ̃ œ̃ ʒuʒu də ply/","zh":"为活着的人再做一朵花一个玩具","en":"Make a flower for a living person one more toy","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-31-004","lineIndex":4,"speaker":"","original":"Un nouveau venu au milieu des rats d'égouts","ipa":"/œ̃ nuvo vəny o miljø de ʁa deɡu/","zh":"下水道老鼠中的新人","en":"A newcomer among the sewer rats","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-31-005","lineIndex":5,"speaker":"","original":"À l'aise entre rongeurs","ipa":"/a lɛz ɑ̃tʁ ʁɔ̃ʒœʁ/","zh":"在啮齿类动物中感到舒适","en":"Comfortable among rodents","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-31-006","lineIndex":6,"speaker":"","original":"On s'habitue même à l'odeur","ipa":"/ɔ̃ sabity mɛm a lodœʁ/","zh":"你甚至习惯了这种气味","en":"You even get used to the smell","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-31-007","lineIndex":7,"speaker":"","original":"Il faut bien que quelqu'un fasse le ménage","ipa":"/il fo bjɛ̃ kə kɛlkœ̃ fas lə menaʒ/","zh":"必须有人做清洁工作","en":"Someone has to do the cleaning","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-31-008","lineIndex":8,"speaker":"","original":"Et débarrasse les rues de déchets inutiles","ipa":"/e debaʁas le ʁy də deʃɛz inytil/","zh":"清除街道上不必要的废物","en":"And rid the streets of unnecessary waste","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-31-009","lineIndex":9,"speaker":"","original":"Il faut bien que quelqu'un se dévoue pour le ramassage","ipa":"/il fo bjɛ̃ kə kɛlkœ̃ sə devu puʁ lə ʁamasaʒ/","zh":"必须有人专门去拾取它。","en":"Someone has to be dedicated to picking it up.","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-31-010","lineIndex":10,"speaker":"","original":"Des ordures de la ville","ipa":"/dez ɔʁdyʁ də la vil/","zh":"城市垃圾","en":"City garbage","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-31-011","lineIndex":11,"speaker":"","original":"Oh! Le bel anneau trop gros pour son doigt","ipa":"/ɔ lə bɛl ano tʁo ɡʁo puʁ sɔ̃ dwa/","zh":"哦，多漂亮的戒指，手指戴不上了。","en":"Oh! A fine ring, too big for your finger.","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-31-012","lineIndex":12,"speaker":"","original":"Vous auriez pas voulu qu'il noircisse sur votre squelette","ipa":"/vuz oʁje pa vuly kil nwaʁsis syʁ votʁ skəlɛt/","zh":"您也不愿它在您的骸骨上发黑吧。","en":"You would not want it to blacken on your skeleton.","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-31-013","lineIndex":13,"speaker":"","original":"Que votre volonté soit faite!","ipa":"/kə votʁ volɔ̃te swa fɛt/","zh":"让你的意志得以实现！","en":"Let your will be done!","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-31-014","lineIndex":14,"speaker":"","original":"Un oignon de gousset","ipa":"/œ̃n onjɔ̃ də ɡusɛ/","zh":"一块怀表","en":"A pocket watch","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-31-015","lineIndex":15,"speaker":"","original":"Hop! C'est confisqué","ipa":"/ɔp sɛ kɔ̃fiske/","zh":"跳！被没收了","en":"Hop! It's confiscated","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-31-016","lineIndex":16,"speaker":"","original":"Ton horloge ne bat plus mais ta tocante a la vie dure","ipa":"/tɔ̃n ɔʁlɔʒ nə ba ply mɛ ta tokɑ̃t a la vi dyʁ/","zh":"你的心不跳了，可这块表还挺耐用。","en":"Your clock no longer beats, but your watch hangs on.","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-31-017","lineIndex":17,"speaker":"","original":"Son tic-tac lui continue","ipa":"/sɔ̃ tiktak lɥi kɔ̃tiny/","zh":"它的滴答声还在响。","en":"Its ticking goes on.","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-31-018","lineIndex":18,"speaker":"","original":"Il faut bien que quelqu'un fasse leur toilette","ipa":"/il fo bjɛ̃ kə kɛlkœ̃ fas lœʁ twalɛt/","zh":"必须有人清理它们","en":"Someone has to clean them","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-31-019","lineIndex":19,"speaker":"","original":"Avant que la petite récolte disparaisse dans la boue","ipa":"/avɑ̃ kə la pətit ʁekɔlt dispaʁɛs dɑ̃ la bu/","zh":"在小小的收获消失在泥土中之前","en":"Before the little harvest disappears into the mud","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-31-020","lineIndex":20,"speaker":"","original":"Il faut bien que quelqu'un fasse la collecte","ipa":"/il fo bjɛ̃ kə kɛlkœ̃ fas la kɔlɛkt/","zh":"必须有人来收集","en":"Someone has to collect","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-31-021","lineIndex":21,"speaker":"","original":"Dans le sang qui refoule par les égouts","ipa":"/dɑ̃ lə sɑ̃ ki ʁəful paʁ lez eɡu/","zh":"在从下水道倒涌的血里","en":"in the blood backing up through the sewers","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-31-022","lineIndex":22,"speaker":"","original":"Enflammés de fureurs cannibales","ipa":"/ɑ̃flame də fyʁœʁ kanibal/","zh":"燃起食人般的狂怒","en":"inflamed with cannibal fury","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-31-023","lineIndex":23,"speaker":"","original":"Les mecs tuent pour un os dans la rue","ipa":"/le mɛk ty puʁ œ̃n ɔs dɑ̃ la ʁy/","zh":"人们在街上为了一根骨头而杀人","en":"Guys kill for a bone in the street","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-31-024","lineIndex":24,"speaker":"","original":"Et dieu au paradis nous regarde faire Parce qu'il est mort comme le zigue à mes pieds","ipa":"/e djø o paʁadi nu ʁəɡaʁd fɛʁ paʁskil ɛ mɔʁ kɔm lə ziɡ a me pje/","zh":"天上的上帝看着我们这样做因为他死得跟我脚边这家伙一样。","en":"And god in heaven watches us do it because he died like the guy at my feet.","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-31-026","lineIndex":25,"speaker":"","original":"Je lève les chasses pour le chercher au ciel","ipa":"/ʒə lɛv le ʃas puʁ lə ʃɛʁʃe o sjɛl/","zh":"我抬眼去天上找他","en":"I raise my eyes to look for him in the sky","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-31-027","lineIndex":26,"speaker":"","original":"Mais y a que la lune qui passe","ipa":"/mɛz i a kə la lyn ki pas/","zh":"但只有月亮经过","en":"But only the moon passes","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-31-028","lineIndex":27,"speaker":"","original":"La sale lune qui grimace","ipa":"/la sal lyn ki ɡʁimas/","zh":"肮脏的月亮做着鬼脸","en":"The dirty moon that grimaces","note":"","sourceLineIndex":28}],"sourceOrder":31,"displayOrder":30},{"order":32,"id":"32-le-suicide-de-javert","title":"Le suicide de Javert","titleZh":"沙威的自杀","lines":[{"id":"les-miserables-cityprod-2017-32-001","lineIndex":1,"speaker":"","original":"C'est toi Javert!","ipa":"/sɛ twa ʒavɛʁ/","zh":"是你沙威！","en":"It’s you Javert!","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-32-002","lineIndex":2,"speaker":"","original":"Tu n'as pas attendu longtemps","ipa":"/ty na paz atɑ̃dy lɔ̃tɑ̃/","zh":"你并没有等太久","en":"You didn't wait long","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-32-003","lineIndex":3,"speaker":"","original":"Fidèle serviteur de l'ordre à son poste","ipa":"/fidɛl sɛʁvitœʁ də lɔʁdʁ a sɔ̃ pɔst/","zh":"忠于秩序、坚守岗位的仆人。","en":"Faithful servant of order at his post.","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-32-004","lineIndex":4,"speaker":"","original":"Cet homme est innocent","ipa":"/sɛt ɔm ɛt inosɑ̃/","zh":"这个人是无辜的","en":"This man is innocent","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-32-005","lineIndex":5,"speaker":"","original":"Il a besoin d'un docteur","ipa":"/il a bəzwɛ̃ dœ̃ dɔktœʁ/","zh":"他需要一个医生","en":"He needs a doctor","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-32-006","lineIndex":6,"speaker":"","original":"Je t'ai prévenu je ne céderai pas","ipa":"/ʒə te pʁevny ʒə nə sedəʁe pa/","zh":"我警告过你我不会屈服","en":"I warned you I won't give in","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-32-007","lineIndex":7,"speaker":"","original":"Non, je t'arrête","ipa":"/nɔ̃ ʒə taʁɛt/","zh":"不，我阻止你","en":"No, I'm stopping you","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-32-008","lineIndex":8,"speaker":"","original":"Une petite heure et je me rends","ipa":"/yn pətit œʁ e ʒə mə ʁɑ̃/","zh":"一个小时，我投降","en":"An hour and I surrender","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-32-009","lineIndex":9,"speaker":"","original":"Je viens régler ma dette","ipa":"/ʒə vjɛ̃ ʁeɡle ma dɛt/","zh":"我是来还债的","en":"I have come to settle my debt","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-32-010","lineIndex":10,"speaker":"","original":"Toujours les hors-la-loi","ipa":"/tuʒuʁ le ɔʁlalwa/","zh":"永远是不法之徒","en":"Always the outlaws","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-32-011","lineIndex":11,"speaker":"","original":"Qui parlent de justice!","ipa":"/ki paʁl də ʒystis/","zh":"谁讲正义！","en":"Who speak of justice!","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-32-012","lineIndex":12,"speaker":"","original":"Vite, son temps est compté","ipa":"/vit sɔ̃ tɑ̃ ɛ kɔ̃te/","zh":"很快，他的时间就不多了","en":"Quickly, his time is running out","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-32-013","lineIndex":13,"speaker":"","original":"Pitié Javert","ipa":"/pitje ʒavɛʁ/","zh":"可怜沙威","en":"Pity Javert","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-32-014","lineIndex":14,"speaker":"","original":"Vite pendant qu'il respire","ipa":"/vit pɑ̃dɑ̃ kil ʁɛspiʁ/","zh":"当他呼吸的时候很快","en":"Quickly while he breathes","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-32-015","lineIndex":15,"speaker":"","original":"Pitié Javert","ipa":"/pitje ʒavɛʁ/","zh":"可怜沙威","en":"Pity Javert","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-32-016","lineIndex":16,"speaker":"","original":"Cet enfant va mourir","ipa":"/sɛt ɑ̃fɑ̃ va muʁiʁ/","zh":"这孩子快要死了","en":"This child is going to die","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-32-017","lineIndex":17,"speaker":"","original":"Prends-le Valjean","ipa":"/pʁɑ̃lə valʒɑ̃/","zh":"冉阿让接受吧","en":"Take it Valjean","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-32-018","lineIndex":18,"speaker":"","original":"Avant que je ne regrette","ipa":"/avɑ̃ kə ʒə nə ʁəɡʁɛt/","zh":"在我后悔之前","en":"Before I regret","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-32-019","lineIndex":19,"speaker":"","original":"Et surtout reviens","ipa":"/e syʁtu ʁəvjɛ̃/","zh":"最重要的是回来","en":"And above all come back","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-32-020","lineIndex":20,"speaker":"","original":"24-601","ipa":"/vɛ̃tkatʁ sisɑ̃ œ̃/","zh":"24-601","en":"24-601","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-32-021","lineIndex":21,"speaker":"","original":"Qui est cet homme? Quelle sorte de diable est-il donc","ipa":"/ki ɛ sɛt ɔm kɛl sɔʁt də djabl ɛtil dɔ̃k/","zh":"这个人是谁？他到底是个什么样的恶魔呢？","en":"Who is this man? What kind of devil is he?","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-32-022","lineIndex":22,"speaker":"","original":"Pour laisser repartir libre l'homme qui l'a mis en prison?","ipa":"/puʁ lɛse ʁəpaʁtiʁ libʁ lɔm ki la mi ɑ̃ pʁizɔ̃/","zh":"让那个把他关进监狱的人获释？","en":"To let the man who put him in prison go free?","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-32-023","lineIndex":23,"speaker":"","original":"Il tenait entre ses mains tous le fils de mon destin","ipa":"/il tənɛt ɑ̃tʁ se mɛ̃ tus lə fis də mɔ̃ dɛstɛ̃/","zh":"他把我命运的丝线全握在手中","en":"He held every thread of my destiny in his hands","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-32-024","lineIndex":24,"speaker":"","original":"Et d'un seul geste il pouvait changer le sien!","ipa":"/e dœ̃ sœl ʒɛst il puvɛ ʃɑ̃ʒe lə sjɛ̃/","zh":"只需一个动作，就能改写他自己的命运！","en":"and with one gesture he could change his own!","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-32-025","lineIndex":25,"speaker":"","original":"Il eût suffi d'un seul coup de couteau","ipa":"/il y syfi dœ̃ sœl ku də kuto/","zh":"他只需刺我一刀","en":"It would have taken just one stab of the knife","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-32-026","lineIndex":26,"speaker":"","original":"Mais c'est ma vie qu'il m'a offert en cadeau","ipa":"/mɛ sɛ ma vi kil ma ɔfɛʁ ɑ̃ kado/","zh":"却把我的性命当作礼物还给了我。","en":"But it's my life that he gave me as a gift","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-32-027","lineIndex":27,"speaker":"","original":"Un policier ne doit rien au voleur","ipa":"/œ̃ polisje nə dwa ʁjɛ̃n o volœʁ/","zh":"警察不欠小偷任何东西","en":"A police officer owes nothing to the thief","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-32-028","lineIndex":28,"speaker":"","original":"Un policier ne cède pas au chantage","ipa":"/œ̃ polisje nə sɛd paz o ʃɑ̃taʒ/","zh":"警察不会屈服于勒索","en":"A police officer does not give in to blackmail","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-32-029","lineIndex":29,"speaker":"","original":"Je suis la loi que personne ne bafoue","ipa":"/ʒə sɥi la lwa kə pɛʁsɔn nə bafu/","zh":"我是无人藐视的法律","en":"I am the law that no one flouts","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-32-030","lineIndex":30,"speaker":"","original":"Et je lui crache sa pitié au visage","ipa":"/e ʒə lɥi kʁaʃ sa pitje o vizaʒ/","zh":"我把他的怜悯吐在他脸上","en":"And I spit his pity in his face","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-32-031","lineIndex":31,"speaker":"","original":"Noir ou blanc, hors la loi ou dedans","ipa":"/nwaʁ u blɑ̃ ɔʁ la lwa u dədɑ̃/","zh":"黑或白，法外或法内","en":"Black or white, outside the law or inside","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-32-032","lineIndex":32,"speaker":"","original":"Noir ou blanc, c'est Javert ou Valjean","ipa":"/nwaʁ u blɑ̃ sɛ ʒavɛʁ u valʒɑ̃/","zh":"黑或白，是沙威还是冉阿让","en":"Black or white, it's Javert or Valjean","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-32-033","lineIndex":33,"speaker":"","original":"Comment puis-je permettre à cet homme de me souiller de sa bonté","ipa":"/kɔmɑ̃ pɥiʒ pɛʁmɛtʁ a sɛt ɔm də mə suje də sa bɔ̃te/","zh":"我怎能容许他用自己的善意来玷污我？","en":"How can I allow this man to defile me with his goodness","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-32-034","lineIndex":34,"speaker":"","original":"Cet homme que j'ai suivi à la trace je lui dois ma vie et ma liberté","ipa":"/sɛt ɔm kə ʒe sɥivi a la tʁas ʒə lɥi dwa ma vi e ma libɛʁte/","zh":"我一路追捕的这个人，我欠他生命与自由。","en":"This man I tracked down—I owe him my life and my freedom.","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-32-035","lineIndex":35,"speaker":"","original":"J'aurais dû périr de sa main sans un remords","ipa":"/ʒoʁɛ dy peʁiʁ də sa mɛ̃ sɑ̃z œ̃ ʁəmɔʁ/","zh":"我本该死在他手上，毫无悔意。","en":"I should have died by his hand without a single remorse","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-32-036","lineIndex":36,"speaker":"","original":"Je serais mort comme un soldat ce soir j'ai honte de vivre encore","ipa":"/ʒə səʁɛ mɔʁ kɔm œ̃ sɔlda sə swaʁ ʒe ɔ̃t də vivʁ ɑ̃kɔʁ/","zh":"那样我会像士兵般死去；今晚，我却羞于仍然活着。","en":"I would have died like a soldier tonight I'm ashamed to still live","note":"","sourceLineIndex":36},{"id":"les-miserables-cityprod-2017-32-037","lineIndex":37,"speaker":"","original":"Est-ce qu'une âme se rachète? Est-ce qu'un homme peut changer?","ipa":"/ɛs kyn am sə ʁaʃɛt ɛs kœ̃n ɔm pø ʃɑ̃ʒe/","zh":"灵魂可以被救赎吗？男人能改变吗？","en":"Can a soul be redeemed? Can a man change?","note":"","sourceLineIndex":37},{"id":"les-miserables-cityprod-2017-32-038","lineIndex":38,"speaker":"","original":"Peut-on laver ses crimes? Faut-il lui pardonner?","ipa":"/pøtɔ̃ lave se kʁim fotil lɥi paʁdɔne/","zh":"我们能洗清我们的罪行吗？我们应该原谅他吗？","en":"Can we clean up our crimes? Should we forgive him?","note":"","sourceLineIndex":38},{"id":"les-miserables-cityprod-2017-32-039","lineIndex":39,"speaker":"","original":"Faut-il qu'après toutes ces années je laisse le doute ronger ma vie?","ipa":"/fotil kapʁɛ tut sez ane ʒə lɛs lə dut ʁɔ̃ʒe ma vi/","zh":"这么多年过去了，我应该让怀疑吞噬我的生活吗？","en":"Should I let doubt eat away at my life after all these years?","note":"","sourceLineIndex":39},{"id":"les-miserables-cityprod-2017-32-040","lineIndex":40,"speaker":"","original":"J'étais de glace, je me vois fondre il n'est qu'une justice et je l'ai servie","ipa":"/ʒetɛ də ɡlas ʒə mə vwa fɔ̃dʁ il nɛ kyn ʒystis e ʒə le sɛʁvi/","zh":"我原是冰，如今却看着自己融化；世上只有一种正义，而我曾为它效力。","en":"I was made of ice, I see myself melting, there is only one justice and I served it","note":"","sourceLineIndex":40},{"id":"les-miserables-cityprod-2017-32-041","lineIndex":41,"speaker":"","original":"Qu'il vienne du ciel ou de l'enfer il ne sait pas","ipa":"/kil vjɛn dy sjɛl u də lɑ̃fɛʁ il nə sɛ pa/","zh":"无论他来自天堂还是地狱，他都不知道","en":"Whether he comes from heaven or hell, he does not know","note":"","sourceLineIndex":41},{"id":"les-miserables-cityprod-2017-32-042","lineIndex":42,"speaker":"","original":"Qu'en me rendant ma vie, ce soir il s'est enfin vengé de moi","ipa":"/kɑ̃ mə ʁɑ̃dɑ̃ ma vi sə swaʁ il sɛt ɑ̃fɛ̃ vɑ̃ʒe də mwa/","zh":"今晚他把我的命还给我，终于向我报了仇","en":"That by giving me back my life, tonight he finally took revenge on me","note":"","sourceLineIndex":42},{"id":"les-miserables-cityprod-2017-32-043","lineIndex":43,"speaker":"","original":"Je le tiens mais il m'échappe les étoiles rient dans le noir","ipa":"/ʒə lə tjɛ̃ mɛz il meʃap lez etwal ʁi dɑ̃ lə nwaʁ/","zh":"我以为抓住了它，它却从我手中溜走；星星在黑暗里发笑。","en":"I hold it but it escapes me the stars laugh in the dark","note":"","sourceLineIndex":43},{"id":"les-miserables-cityprod-2017-32-044","lineIndex":44,"speaker":"","original":"Elles se moquent de la victoire sur moi des forces du mal","ipa":"/ɛl sə mok də la viktwaʁ syʁ mwa de fɔʁs dy mal/","zh":"它们嘲笑邪恶势力对我的胜利。","en":"They mock the victory of the forces of evil over me.","note":"","sourceLineIndex":44},{"id":"les-miserables-cityprod-2017-32-045","lineIndex":45,"speaker":"","original":"Je préfère quitter ce monde qui tolère les Jean Valjean","ipa":"/ʒə pʁefɛʁ kite sə mɔ̃d ki tolɛʁ le ʒɑ̃ valʒɑ̃/","zh":"我宁愿离开这个容得下冉阿让之流的世界。","en":"I prefer to leave this world which tolerates Jean Valjeans","note":"","sourceLineIndex":45},{"id":"les-miserables-cityprod-2017-32-046","lineIndex":46,"speaker":"","original":"Toute ma vie fut une erreur je la retourne au néant","ipa":"/tut ma vi fy yn ɛʁœʁ ʒə la ʁətuʁn o neɑ̃/","zh":"我的一生都是错误；我把它归还给虚无。","en":"My whole life was a mistake I return it to nothingness","note":"","sourceLineIndex":46}],"sourceOrder":32,"displayOrder":31},{"order":33,"id":"33-tourne-tourne","title":"Tourne, tourne","titleZh":"转啊，转啊","lines":[{"id":"les-miserables-cityprod-2017-33-001","lineIndex":1,"speaker":"","original":"Ils sont partis la fleur au fusil","ipa":"/il sɔ̃ paʁti la flœʁ o fyzi/","zh":"他们怀着理想、扛枪而去。","en":"They left with flowers in their guns.","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-33-002","lineIndex":2,"speaker":"","original":"Faire une barricade qui n'aura duré qu'une nuit","ipa":"/fɛʁ yn baʁikad ki noʁa dyʁe kyn nɥi/","zh":"去筑一座只撑过一夜的路障。","en":"Make a barricade that only lasted one night","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-33-003","lineIndex":3,"speaker":"","original":"Ils sont tombés morts sur le pavé","ipa":"/il sɔ̃ tɔ̃be mɔʁ syʁ lə pave/","zh":"他们倒毙在石板路上。","en":"They fell dead on the pavement","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-33-004","lineIndex":4,"speaker":"","original":"Ces enfants qu'une mère embrassait","ipa":"/sez ɑ̃fɑ̃ kyn mɛʁ ɑ̃bʁasɛ/","zh":"这些被母亲亲吻过的孩子","en":"These children that a mother kissed","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-33-005","lineIndex":5,"speaker":"","original":"Avant qu'ils s'endorment","ipa":"/avɑ̃ kil sɑ̃dɔʁm/","zh":"在他们入睡之前","en":"Before they fall asleep","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-33-006","lineIndex":6,"speaker":"","original":"Ces héros d'un peuple sans uniforme","ipa":"/se eʁo dœ̃ pøpl sɑ̃z ynifɔʁm/","zh":"这些没有制服的人民的英雄","en":"These heroes of a people without uniform","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-33-007","lineIndex":7,"speaker":"","original":"Ils sont partis","ipa":"/il sɔ̃ paʁti/","zh":"他们离开了","en":"They left","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-33-008","lineIndex":8,"speaker":"","original":"Gonflés d'idéal Armés de pavés qui orneront leurs pierres tombales","ipa":"/ɡɔ̃fle dideal aʁme də pave ki ɔʁnəʁɔ̃ lœʁ pjɛʁ tɔ̃bal/","zh":"满怀理想手持终会装点他们墓碑的铺路石。","en":"Filled with ideals armed with paving stones that will adorn their tombstones.","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-33-010","lineIndex":9,"speaker":"","original":"Ils sont partis comme des écoliers","ipa":"/il sɔ̃ paʁti kɔm dez ekolje/","zh":"他们像学生般出发","en":"They left like schoolchildren","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-33-011","lineIndex":10,"speaker":"","original":"Qui savaient à peine comment on se sert de ses armes","ipa":"/ki savɛt a pɛn kɔmɑ̃ ɔ̃ sə sɛʁ də sez aʁm/","zh":"几乎不懂得怎样使用手中的武器。","en":"Who barely knew how to use their weapons","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-33-012","lineIndex":11,"speaker":"","original":"Ils ne laissent que des familles en larmes","ipa":"/il nə lɛs kə de famijz ɑ̃ laʁm/","zh":"他们只让家人流泪","en":"They only leave families in tears","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-33-013","lineIndex":12,"speaker":"","original":"Rien n'a changé","ipa":"/ʁiɛ̃ na ʃɑ̃ʒe/","zh":"一切都没有改变","en":"Nothing has changed","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-33-014","lineIndex":13,"speaker":"","original":"Rien ne changera","ipa":"/ʁiɛ̃ nə ʃɑ̃ʒʁa/","zh":"一切都不会改变","en":"Nothing will change","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-33-015","lineIndex":14,"speaker":"","original":"Chaque année qui passe un gamin de plus sur les bras","ipa":"/ʃak ane ki pas œ̃ ɡamɛ̃ də ply syʁ le bʁa/","zh":"每过一年，手里又多一个孩子要养。","en":"Each year brings one more child to carry.","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-33-016","lineIndex":15,"speaker":"","original":"Garde tes pleurs ta rage et tes doutes","ipa":"/ɡaʁd te plœʁ ta ʁaʒ e te dut/","zh":"收起你的眼泪、愤怒和疑问","en":"Keep your tears, rage, and doubts","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-33-017","lineIndex":16,"speaker":"","original":"Garde tes prières puisque personne là-haut n'écoute","ipa":"/ɡaʁd te pʁiɛʁ pɥiskə pɛʁsɔn lao nekut/","zh":"把祈祷也留着吧，因为天上无人聆听。","en":"Keep your prayers since no one up there is listening","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-33-018","lineIndex":17,"speaker":"","original":"Tourne, tourne, tourne et tourne toujours du même côté","ipa":"/tuʁn tuʁn tuʁn e tuʁn tuʒuʁ dy mɛm kote/","zh":"转啊，转啊，始终朝同一个方向转","en":"Turn, turn, turn and turn always in the same direction","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-33-019","lineIndex":18,"speaker":"","original":"Tourne, tourne, tourne du même coté","ipa":"/tuʁn tuʁn tuʁn dy mɛm kote/","zh":"转啊，转啊，转个不停。","en":"Turn, turn, turn the same way","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-33-020","lineIndex":19,"speaker":"","original":"C'est les mêmes qui gagnent et les mêmes qui sont écrasés","ipa":"/sɛ le mɛm ki ɡanjt e le mɛm ki sɔ̃t ekʁaze/","zh":"赢的总是那一群人，被碾碎的也总是另一群人。","en":"It's the same people who win and the same people who are crushed","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-33-021","lineIndex":20,"speaker":"","original":"Rien n'a changé, rien ne change jamais","ipa":"/ʁiɛ̃ na ʃɑ̃ʒe ʁiɛ̃ nə ʃɑ̃ʒ ʒamɛ/","zh":"一切从未改变，也永远不会改变。","en":"Nothing has changed, nothing ever changes","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-33-022","lineIndex":21,"speaker":"","original":"Le manège qui tourne en rond, toujours d'un seul côté","ipa":"/lə manɛʒ ki tuʁn ɑ̃ ʁɔ̃ tuʒuʁ dœ̃ sœl kote/","zh":"旋转木马兜着圈子，永远朝同一边转。","en":"The merry-go-round that goes around in circles, always on one side","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-33-023","lineIndex":22,"speaker":"","original":"Tourne et tourne, toujours du même coté.","ipa":"/tuʁn e tuʁn tuʒuʁ dy mɛm kote/","zh":"转啊转，始终在同一侧。","en":"Turn and turn, always on the same side.","note":"","sourceLineIndex":23}],"sourceOrder":33,"displayOrder":32},{"order":34,"id":"34-seul-devant-ces-tables-vides","title":"Seul devant ces tables vides","titleZh":"独自在这些空桌子前","lines":[{"id":"les-miserables-cityprod-2017-34-001","lineIndex":1,"speaker":"","original":"Il est un deuil que je porte","ipa":"/il ɛt œ̃ dœj kə ʒə pɔʁt/","zh":"有一份哀伤我始终背负。","en":"There is a grief I carry.","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-34-002","lineIndex":2,"speaker":"","original":"Lourd au cœur comme un secret","ipa":"/luʁ o kœʁ kɔm œ̃ səkʁɛ/","zh":"像一个秘密般压在心头。","en":"Heavy in the heart like a secret","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-34-003","lineIndex":3,"speaker":"","original":"Seul devant ces tables vides Qu'ils ne reverront jamais","ipa":"/sœl dəvɑ̃ se tabl vid kil nə ʁəvɛʁɔ̃ ʒamɛ/","zh":"独自面对这些空桌子他们从此再也见不到。","en":"Alone in front of these empty tables that they will never see again.","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-34-005","lineIndex":4,"speaker":"","original":"On partait changer le monde","ipa":"/ɔ̃ paʁtɛ ʃɑ̃ʒe lə mɔ̃d/","zh":"我们曾出发去改变世界","en":"We were going to change the world","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-34-006","lineIndex":5,"speaker":"","original":"On rêvait d'égalité","ipa":"/ɔ̃ ʁɛvɛ deɡalite/","zh":"我们梦想平等","en":"We dreamed of equality","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-34-007","lineIndex":6,"speaker":"","original":"Et d'un matin de lumière Qui ne s'est jamais levé","ipa":"/e dœ̃ matɛ̃ də lymjɛʁ ki nə sɛ ʒamɛ ləve/","zh":"和一个充满光明的早晨却从未升起。","en":"And a morning of light that never rose.","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-34-009","lineIndex":7,"speaker":"","original":"De la table sous la fenêtre","ipa":"/də la tabl su la fənɛtʁ/","zh":"从窗边那张桌子旁","en":"From the table beneath the window","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-34-010","lineIndex":8,"speaker":"","original":"Habités d'un fol espoir","ipa":"/abite dœ̃ fɔl ɛspwaʁ/","zh":"充满疯狂的希望","en":"Filled with mad hope","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-34-011","lineIndex":9,"speaker":"","original":"Des enfants ont pris les armes","ipa":"/dez ɑ̃fɑ̃z ɔ̃ pʁi lez aʁm/","zh":"孩子们拿起武器","en":"Children took up arms","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-34-012","lineIndex":10,"speaker":"","original":"Je les entends encore","ipa":"/ʒə lez ɑ̃tɑ̃z ɑ̃kɔʁ/","zh":"我仍然听到他们的声音","en":"I still hear them","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-34-013","lineIndex":11,"speaker":"","original":"Ces mots brûlants qu'ils ont chantés","ipa":"/se mo bʁylɑ̃ kilz ɔ̃ ʃɑ̃te/","zh":"他们唱出这些燃烧的歌词","en":"These burning words they sang","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-34-014","lineIndex":12,"speaker":"","original":"Furent leurs dernières volontés","ipa":"/fyʁ lœʁ dɛʁnjɛʁ volɔ̃te/","zh":"是他们最后的愿望","en":"Were their last wishes","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-34-015","lineIndex":13,"speaker":"","original":"Sur la barricade déserte, à l'aube","ipa":"/syʁ la baʁikad dezɛʁt a lob/","zh":"黎明时分，在荒无人烟的街垒上","en":"On the deserted barricade, at dawn","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-34-016","lineIndex":14,"speaker":"","original":"Oh! Mes amis, pardonnez-moi","ipa":"/ɔ mez ami paʁdɔnemwa/","zh":"哦！朋友们请原谅我","en":"Oh! My friends, forgive me","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-34-017","lineIndex":15,"speaker":"","original":"D'être là, de vivre encore","ipa":"/dɛtʁ la də vivʁ ɑ̃kɔʁ/","zh":"原谅我还在这里，仍然活着。","en":"for being here, for still being alive.","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-34-018","lineIndex":16,"speaker":"","original":"Il est des deuils que l'on garde","ipa":"/il ɛ de dœj kə lɔ̃ ɡaʁd/","zh":"有些哀伤，人会永远留着","en":"There are mournings that we keep","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-34-019","lineIndex":17,"speaker":"","original":"Quand tous les chagrins sont morts","ipa":"/kɑ̃ tu le ʃaɡʁɛ̃ sɔ̃ mɔʁ/","zh":"当所有的悲伤都消逝","en":"When all the sorrows are dead","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-34-020","lineIndex":18,"speaker":"","original":"Et je vois passer vos ombres","ipa":"/e ʒə vwa pase voz ɔ̃bʁ/","zh":"我看见你们的身影掠过","en":"And I see your shadows pass","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-34-021","lineIndex":19,"speaker":"","original":"Et je pleure nos joies perdues","ipa":"/e ʒə plœʁ no ʒwa pɛʁdy/","zh":"我哀悼我们失去的欢乐","en":"And I mourn our lost joys","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-34-022","lineIndex":20,"speaker":"","original":"Seul devant ces tables vides","ipa":"/sœl dəvɑ̃ se tabl vid/","zh":"独自一人在这些空桌子前","en":"Alone in front of these empty tables","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-34-023","lineIndex":21,"speaker":"","original":"Que vous ne reverrez plus","ipa":"/kə vu nə ʁəvɛʁe ply/","zh":"你们将再也见不到的。","en":"That you will never see again","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-34-024","lineIndex":22,"speaker":"","original":"Oh! Mes amis, je voudrais croire","ipa":"/ɔ mez ami ʒə vudʁɛ kʁwaʁ/","zh":"哦！我的朋友们，我愿意相信","en":"Oh! My friends, I would like to believe","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-34-025","lineIndex":23,"speaker":"","original":"Que vous n'êtes pas morts en vain","ipa":"/kə vu nɛt pa mɔʁz ɑ̃ vɛ̃/","zh":"你没有白白死去","en":"That you did not die in vain","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-34-026","lineIndex":24,"speaker":"","original":"Seul devant ces tables vides","ipa":"/sœl dəvɑ̃ se tabl vid/","zh":"独自一人在这些空桌子前","en":"Alone in front of these empty tables","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-34-027","lineIndex":25,"speaker":"","original":"Je ne suis plus sur de rien.","ipa":"/ʒə nə sɥi ply syʁ də ʁjɛ̃/","zh":"我不再确定任何事情了。","en":"I'm not sure of anything anymore.","note":"","sourceLineIndex":27}],"sourceOrder":34,"displayOrder":33},{"order":35,"id":"35-sonnez-sonnez","title":"Sonnez, sonnez","titleZh":"铃声，铃声","lines":[{"id":"les-miserables-cityprod-2017-35-001","lineIndex":1,"speaker":"","original":"Sonnez, sonnez, annoncez la nouvelle","ipa":"/sɔne sɔne anɔ̃se la nuvɛl/","zh":"敲响吧，敲响吧，宣布这喜讯","en":"Ring, ring, announce the news","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-35-002","lineIndex":2,"speaker":"","original":"Carillonnez tout autour de la terre","ipa":"/kaʁijɔne tut otuʁ də la tɛʁ/","zh":"让钟声响遍大地。","en":"Chime all around the earth","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-35-003","lineIndex":3,"speaker":"","original":"Chantez, chantez qu'un bonheur éternel","ipa":"/ʃɑ̃te ʃɑ̃te kœ̃ bɔnœʁ etɛʁnɛl/","zh":"歌唱吧，歌唱永恒的幸福","en":"Sing, sing of eternal happiness","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-35-004","lineIndex":4,"speaker":"","original":"Les accompagne durant leur vie entière","ipa":"/lez akɔ̃paɲ dyʁɑ̃ lœʁ vi ɑ̃tjɛʁ/","zh":"陪伴他们一生","en":"Accompanies them throughout their entire life","note":"","sourceLineIndex":4}],"sourceOrder":35,"displayOrder":34},{"order":36,"id":"36-mendiants-a-la-fete","title":"Mendiants à la fête","titleZh":"宴会上的乞丐","lines":[{"id":"les-miserables-cityprod-2017-36-001","lineIndex":1,"speaker":"","original":"Allons ma biche","ipa":"/alɔ̃ ma biʃ/","zh":"来吧，宝贝","en":"Come on, darling","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-36-002","lineIndex":2,"speaker":"","original":"Remuez votre graisse","ipa":"/ʁəmye votʁ ɡʁɛs/","zh":"扭动你们的肥肉！","en":"Shake your fat!","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-36-003","lineIndex":3,"speaker":"","original":"Secouez vos miches","ipa":"/səkwe vo miʃ/","zh":"摇晃你们的臀部","en":"Shake your buns","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-36-004","lineIndex":4,"speaker":"","original":"Un peu d'allégresse!","ipa":"/œ̃ pø daleɡʁɛs/","zh":"一点喜悦！","en":"A little joy!","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-36-005","lineIndex":5,"speaker":"","original":"Vise-moi ce beau linge","ipa":"/vizmwa sə bo lɛ̃ʒ/","zh":"瞧瞧这身漂亮衣裳","en":"Show me this beautiful linen","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-36-006","lineIndex":6,"speaker":"","original":"Pour un casse-dalle","ipa":"/puʁ œ̃ kasdal/","zh":"为了填饱肚子","en":"For a bite to eat","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-36-007","lineIndex":7,"speaker":"","original":"Un duc, un prince","ipa":"/œ̃ dyk œ̃ pʁɛ̃s/","zh":"一个公爵，一个王子","en":"A duke, a prince","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-36-008","lineIndex":8,"speaker":"","original":"Et une grosse pédale!","ipa":"/e yn ɡʁos pedal/","zh":"还有一个胖大的“娘娘腔”！","en":"And a big “queer”!","note":"唱段人以侮辱性俚语攻击他人，非页面立场。","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-36-009","lineIndex":9,"speaker":"","original":"Paris qui froufroute paris qui gaspille","ipa":"/paʁi ki fʁufʁut paʁi ki ɡaspij/","zh":"裙裾窸窣的巴黎，挥霍无度的巴黎","en":"Paris which rustles Paris which wastes","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-36-010","lineIndex":10,"speaker":"","original":"Et moi à tu et à toi avec tout ce qui brille","ipa":"/e mwa a ty e a twa avɛk tu sə ki bʁij/","zh":"我跟所有闪闪发亮的东西都不客气。","en":"And I am on familiar terms with everything that glitters.","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-36-011","lineIndex":11,"speaker":"","original":"Mendiants à la fête maîtres de la danse","ipa":"/mɑ̃djɑ̃z a la fɛt mɛtʁ də la dɑ̃s/","zh":"宴会上的乞丐，舞池里的主人。","en":"Beggars at the feast, masters of the dance.","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-36-012","lineIndex":12,"speaker":"","original":"La vie est choucarde du bon côté de la chance","ipa":"/la vi ɛ ʃukaʁd dy bɔ̃ kote də la ʃɑ̃s/","zh":"走运的时候，日子也挺快活。","en":"Life is on the good side of luck","note":"","sourceLineIndex":12},{"id":"les-miserables-cityprod-2017-36-013","lineIndex":13,"speaker":"","original":"Tous ces cul-bénis respectent la loi","ipa":"/tu se kybeni ʁɛspɛkt la lwa/","zh":"这帮假正经都遵守法律","en":"All these sanctimonious people respect the law","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-36-014","lineIndex":14,"speaker":"","original":"Oui mais la plupart sont aussi fauchés que moi","ipa":"/wi mɛ la plypaʁ sɔ̃t osi foʃe kə mwa/","zh":"是啊，但大多数人也和我一样穷。","en":"Yes, but most are as broke as me.","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-36-015","lineIndex":15,"speaker":"","original":"À l'église tous les dimanches","ipa":"/a leɡliz tu le dimɑ̃ʃ/","zh":"每个星期天都上教堂","en":"At church every Sunday","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-36-016","lineIndex":16,"speaker":"","original":"Priant Dieu pour ses bontés","ipa":"/pʁiɑ̃ djø puʁ se bɔ̃te/","zh":"祈求上帝赐福。","en":"Praying to God for his kindness","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-36-017","lineIndex":17,"speaker":"","original":"Nous on leur fait les poches c'est bien plus fastoche et c'est moins risqué","ipa":"/nuz ɔ̃ lœʁ fɛ le poʃ sɛ bjɛ̃ ply fastɔʃ e sɛ mwɛ̃ ʁiske/","zh":"我们掏他们的口袋，更轻松，风险也更小。","en":"We pick their pockets; it is much easier and less risky.","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-36-018","lineIndex":18,"speaker":"","original":"Guinchez mes pigeons pendant qu'on vous mate","ipa":"/ɡɛ̃ʃe me piʒɔ̃ pɑ̃dɑ̃ kɔ̃ vu mat/","zh":"跳吧，肥羊们，趁我们盯着你们看。","en":"Dance, my pigeons, while we watch you.","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-36-019","lineIndex":19,"speaker":"","original":"Nous on fait des plans pour vous casser les pattes!","ipa":"/nuz ɔ̃ fɛ de plɑ̃ puʁ vu kase le pat/","zh":"我们已经制定了打断你腿的计划！","en":"We have made plans to break your legs!","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-36-020","lineIndex":20,"speaker":"","original":"Maîtres du pays à qui tout profite","ipa":"/mɛtʁ dy pɛiz a ki tu pʁofit/","zh":"这个国家的主人，样样都占尽好处","en":"Masters of the country who benefit from everything","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-36-021","lineIndex":21,"speaker":"","original":"Les barricades tombent mais nous on ressuscite","ipa":"/le baʁikad tɔ̃b mɛ nuz ɔ̃ ʁesysit/","zh":"路障倒塌，但我们再次站起来","en":"The barricades fall but we rise again","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-36-022","lineIndex":22,"speaker":"","original":"On va où le vent nous mène","ipa":"/ɔ̃ va u lə vɑ̃ nu mɛn/","zh":"风把我们带到哪里，我们就去哪里。","en":"We go where the wind takes us","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-36-023","lineIndex":23,"speaker":"","original":"On flaire l'odeur de l'argent","ipa":"/ɔ̃ flɛʁ lodœʁ də laʁʒɑ̃/","zh":"我们闻到了金钱的味道","en":"We smell the smell of money","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-36-024","lineIndex":24,"speaker":"","original":"On sera riches comme Crésus, mes frères","ipa":"/ɔ̃ səʁa ʁiʃ kɔm kʁezy me fʁɛʁ/","zh":"我们会像克洛伊索斯一样富有，我的兄弟们","en":"We will be rich like Croesus, my brothers","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-36-025","lineIndex":25,"speaker":"","original":"C'est en enfer qu'on vous attend!","ipa":"/sɛt ɑ̃n ɑ̃fɛʁ kɔ̃ vuz atɑ̃/","zh":"我们在地狱等你！","en":"We're waiting for you in hell!","note":"","sourceLineIndex":25}],"sourceOrder":36,"displayOrder":35},{"order":37,"id":"37-c-est-pour-demain-final","title":"C'est pour demain (Final)","titleZh":"明天（最终）","lines":[{"id":"les-miserables-cityprod-2017-37-001","lineIndex":1,"speaker":"","original":"Je ne pars plus seul","ipa":"/ʒə nə paʁ ply sœl/","zh":"我不再独自离去。","en":"I no longer leave alone.","note":"","sourceLineIndex":1},{"id":"les-miserables-cityprod-2017-37-002","lineIndex":2,"speaker":"","original":"Je suis heureux","ipa":"/ʒə sɥiz øʁø/","zh":"我很高兴","en":"I am happy","note":"","sourceLineIndex":2},{"id":"les-miserables-cityprod-2017-37-003","lineIndex":3,"speaker":"","original":"J'ai revu ton sourire","ipa":"/ʒe ʁəvy tɔ̃ suʁiʁ/","zh":"我又看到了你的笑容","en":"I saw your smile again","note":"","sourceLineIndex":3},{"id":"les-miserables-cityprod-2017-37-004","lineIndex":4,"speaker":"","original":"Maintenant je peux mourir","ipa":"/mɛ̃tnɑ̃ ʒə pø muʁiʁ/","zh":"现在我可以死了","en":"Now I can die","note":"","sourceLineIndex":4},{"id":"les-miserables-cityprod-2017-37-005","lineIndex":5,"speaker":"","original":"Vous vivrez papa, vous allez vivre","ipa":"/vu vivʁe papa vuz ale vivʁ/","zh":"你会活着，爸爸，你会活着","en":"You will live daddy, you will live","note":"","sourceLineIndex":5},{"id":"les-miserables-cityprod-2017-37-006","lineIndex":6,"speaker":"","original":"Moi je veux que vous viviez, entendez-vous!","ipa":"/mwa ʒə vø kə vu vivje ɑ̃tɑ̃devu/","zh":"我要你活下去，你听到了吗！","en":"I want you to live, you hear!","note":"","sourceLineIndex":6},{"id":"les-miserables-cityprod-2017-37-007","lineIndex":7,"speaker":"","original":"Oui, Cosette défends-moi de mourir","ipa":"/wi kozɛt defɑ̃mwa də muʁiʁ/","zh":"是的，珂赛特，请阻止我死去","en":"Yes, Cosette, forbid me from dying","note":"","sourceLineIndex":7},{"id":"les-miserables-cityprod-2017-37-008","lineIndex":8,"speaker":"","original":"J'essaierai d'obéir","ipa":"/ʒesɛʁe dobeiʁ/","zh":"我会尽力服从","en":"I will try to obey","note":"","sourceLineIndex":8},{"id":"les-miserables-cityprod-2017-37-009","lineIndex":9,"speaker":"","original":"Sur cette page j'ai confessé mon âme","ipa":"/syʁ sɛt paʒ ʒe kɔ̃fɛse mɔ̃n am/","zh":"在这一页上我坦白了我的灵魂","en":"On this page I confessed my soul","note":"","sourceLineIndex":9},{"id":"les-miserables-cityprod-2017-37-010","lineIndex":10,"speaker":"","original":"Des secrets que tu voulais connaître","ipa":"/de səkʁɛ kə ty vulɛ kɔnɛtʁ/","zh":"你想知道的秘密","en":"Secrets you wanted to know","note":"","sourceLineIndex":10},{"id":"les-miserables-cityprod-2017-37-011","lineIndex":11,"speaker":"","original":"C'est l'histoire de celle qui t'a tant aimée Et qui t'a confiée à moi avant de disparaître","ipa":"/sɛ listwaʁ də sɛl ki ta tɑ̃t ɛme e ki ta kɔ̃fje a mwa avɑ̃ də dispaʁɛtʁ/","zh":"这是一个深爱你的人的故事她在消失前把你托付给了我。","en":"This is the story of the one who loved you so much and who entrusted you to me before disappearing.","note":"","sourceLineIndex":11},{"id":"les-miserables-cityprod-2017-37-013","lineIndex":12,"speaker":"","original":"Prends ma main délivrée de tes chaînes","ipa":"/pʁɑ̃ ma mɛ̃ delivʁe də te ʃɛn/","zh":"把我的手从你的锁链中解放出来","en":"Take my hand free from your chains","note":"","sourceLineIndex":13},{"id":"les-miserables-cityprod-2017-37-014","lineIndex":13,"speaker":"","original":"Qu'elle te guide vers le bonheur suprême","ipa":"/kɛl tə ɡid vɛʁ lə bɔnœʁ sypʁɛm/","zh":"愿她引导你走向至高无上的幸福","en":"May she guide you towards supreme happiness","note":"","sourceLineIndex":14},{"id":"les-miserables-cityprod-2017-37-015","lineIndex":14,"speaker":"","original":"Dieu tout-puissant pitié, pitié pour cet homme","ipa":"/djø tupɥisɑ̃ pitje pitje puʁ sɛt ɔm/","zh":"全能的神啊，怜悯这个人吧","en":"Almighty God, have mercy on this man","note":"","sourceLineIndex":15},{"id":"les-miserables-cityprod-2017-37-016","lineIndex":15,"speaker":"","original":"Pardonne-moi mes péchés et accueille-moi dans ton royaume","ipa":"/paʁdɔnmwa me peʃez e akœjmwa dɑ̃ tɔ̃ ʁwajom/","zh":"宽恕我的罪孽并欢迎我进入你的王国","en":"Forgive me my sins and welcome me into your kingdom","note":"","sourceLineIndex":16},{"id":"les-miserables-cityprod-2017-37-017","lineIndex":16,"speaker":"","original":"Prends ma main et viens vers sa lumière","ipa":"/pʁɑ̃ ma mɛ̃ e vjɛ̃ vɛʁ sa lymjɛʁ/","zh":"牵着我的手，走向祂的光芒。","en":"Take my hand and come toward His light.","note":"","sourceLineIndex":17},{"id":"les-miserables-cityprod-2017-37-018","lineIndex":17,"speaker":"","original":"Prends l'amour qui brille quand la vie s'éteint","ipa":"/pʁɑ̃ lamuʁ ki bʁij kɑ̃ la vi setɛ̃/","zh":"当生命消逝时，接受闪耀的爱","en":"Take the love that shines when life fades","note":"","sourceLineIndex":18},{"id":"les-miserables-cityprod-2017-37-019","lineIndex":18,"speaker":"","original":"Et garde en toi les mots de ta prière:","ipa":"/e ɡaʁd ɑ̃ twa le mo də ta pʁiɛʁ/","zh":"并把你的祈祷词记在心里：","en":"And keep within you the words of your prayer:","note":"","sourceLineIndex":19},{"id":"les-miserables-cityprod-2017-37-020","lineIndex":19,"speaker":"","original":"\"Qui aime son prochain est plus près de Dieu sur la terre\"","ipa":"/ki ɛm sɔ̃ pʁoʃɛ̃n ɛ ply pʁɛ də djø syʁ la tɛʁ/","zh":"“爱邻舍的人在地上离上帝更近”","en":"“He who loves his neighbor is closer to God on earth”","note":"","sourceLineIndex":20},{"id":"les-miserables-cityprod-2017-37-021","lineIndex":20,"speaker":"","original":"À la volonté du peuple dont on n'étouffe jamais la voix","ipa":"/a la volɔ̃te dy pøpl dɔ̃t ɔ̃ netuf ʒamɛ la vwa/","zh":"向着人民的意志—那声音从未被窒息。","en":"To the will of the people, whose voice is never stifled.","note":"","sourceLineIndex":21},{"id":"les-miserables-cityprod-2017-37-022","lineIndex":21,"speaker":"","original":"Et dont le chant renaît toujours et dont le chant renaît déjà","ipa":"/e dɔ̃ lə ʃɑ̃ ʁənɛ tuʒuʁz e dɔ̃ lə ʃɑ̃ ʁənɛ deʒa/","zh":"它的歌声总会重生，它的歌声此刻已经响起。","en":"Whose song is always reborn, whose song is already reborn.","note":"","sourceLineIndex":22},{"id":"les-miserables-cityprod-2017-37-023","lineIndex":22,"speaker":"","original":"Nous voulons que la lumière déchire le masque de la nuit","ipa":"/nu vulɔ̃ kə la lymjɛʁ deʃiʁ lə mask də la nɥi/","zh":"我们希望光能撕掉黑夜的面具","en":"We want the light to tear away the mask of night","note":"","sourceLineIndex":23},{"id":"les-miserables-cityprod-2017-37-024","lineIndex":23,"speaker":"","original":"Pour illuminer notre terre et changer la vie","ipa":"/puʁ ilymine notʁ tɛʁ e ʃɑ̃ʒe la vi/","zh":"照亮我们的土地，改变生活","en":"To illuminate our earth and change lives","note":"","sourceLineIndex":24},{"id":"les-miserables-cityprod-2017-37-025","lineIndex":24,"speaker":"","original":"Il viendra le jour glorieux où dans sa marche vers l'idéal","ipa":"/il vjɛ̃dʁa lə ʒuʁ ɡloʁjøz u dɑ̃ sa maʁʃ vɛʁ lideal/","zh":"终有光辉的一日，人类在迈向理想的途中","en":"The glorious day will come when, on its march toward the ideal","note":"","sourceLineIndex":25},{"id":"les-miserables-cityprod-2017-37-026","lineIndex":25,"speaker":"","original":"L'homme ira vers le progrès du mal au bien du faux au vrai","ipa":"/lɔm iʁa vɛʁ lə pʁɔɡʁɛ dy mal o bjɛ̃ dy foz o vʁɛ/","zh":"将从恶走向善，从伪走向真。","en":"humanity will move from evil to good, from falsehood to truth.","note":"","sourceLineIndex":26},{"id":"les-miserables-cityprod-2017-37-027","lineIndex":26,"speaker":"","original":"Un rêve peut mourir mais on n'enterre jamais l'avenir","ipa":"/œ̃ ʁɛv pø muʁiʁ mɛz ɔ̃ nɑ̃tɛʁ ʒamɛ lavniʁ/","zh":"梦想可能会死去，但未来永远埋葬不了。","en":"A dream can die but you never bury the future","note":"","sourceLineIndex":27},{"id":"les-miserables-cityprod-2017-37-028","lineIndex":27,"speaker":"","original":"Joignez-vous à la croisade de ceux qui croient au genre humain","ipa":"/ʒwanjevuz a la kʁwazad də sø ki kʁwat o ʒɑ̃ʁ ymɛ̃/","zh":"加入相信人性的人的行列","en":"Join the crusade of those who believe in humanity","note":"","sourceLineIndex":28},{"id":"les-miserables-cityprod-2017-37-029","lineIndex":28,"speaker":"","original":"Pour une seule barricade qui tombe cent autres se lèveront demain","ipa":"/puʁ yn sœl baʁikad ki tɔ̃b sɑ̃ otʁ sə lɛvʁɔ̃ dəmɛ̃/","zh":"一个路障倒塌，明天就会有一百个路障升起","en":"For a single barricade that falls, a hundred others will rise tomorrow","note":"","sourceLineIndex":29},{"id":"les-miserables-cityprod-2017-37-030","lineIndex":29,"speaker":"","original":"À la volonté du peuple un tambour chante dans le lointain","ipa":"/a la volɔ̃te dy pøpl œ̃ tɑ̃buʁ ʃɑ̃t dɑ̃ lə lwɛ̃tɛ̃/","zh":"为了人民的意志，远方传来鼓声。","en":"At the will of the people a drum sings in the distance","note":"","sourceLineIndex":30},{"id":"les-miserables-cityprod-2017-37-031","lineIndex":30,"speaker":"","original":"Il vient annoncer le grand jour et c'est pour demain","ipa":"/il vjɛ̃t anɔ̃se lə ɡʁɑ̃ ʒuʁ e sɛ puʁ dəmɛ̃/","zh":"他来宣布这个重要的日子，就在明天","en":"He comes to announce the big day and it's for tomorrow","note":"","sourceLineIndex":31},{"id":"les-miserables-cityprod-2017-37-032","lineIndex":31,"speaker":"","original":"Joignez-vous à la croisade de ceux qui croient au genre humain","ipa":"/ʒwanjevuz a la kʁwazad də sø ki kʁwat o ʒɑ̃ʁ ymɛ̃/","zh":"加入相信人性的人的行列","en":"Join the crusade of those who believe in humanity","note":"","sourceLineIndex":32},{"id":"les-miserables-cityprod-2017-37-033","lineIndex":32,"speaker":"","original":"Pour une seule barricade qui tombe cent autres se lèveront demain","ipa":"/puʁ yn sœl baʁikad ki tɔ̃b sɑ̃ otʁ sə lɛvʁɔ̃ dəmɛ̃/","zh":"一个路障倒塌，明天就会有一百个路障升起","en":"For a single barricade that falls, a hundred others will rise tomorrow","note":"","sourceLineIndex":33},{"id":"les-miserables-cityprod-2017-37-034","lineIndex":33,"speaker":"","original":"À la volonté du peuple un tambour chante dans le lointain","ipa":"/a la volɔ̃te dy pøpl œ̃ tɑ̃buʁ ʃɑ̃t dɑ̃ lə lwɛ̃tɛ̃/","zh":"为了人民的意志，远方传来鼓声。","en":"At the will of the people a drum sings in the distance","note":"","sourceLineIndex":34},{"id":"les-miserables-cityprod-2017-37-035","lineIndex":34,"speaker":"","original":"Il vient annoncer le grand jour et c'est pour demain","ipa":"/il vjɛ̃t anɔ̃se lə ɡʁɑ̃ ʒuʁ e sɛ puʁ dəmɛ̃/","zh":"他来宣布这个重要的日子，就在明天","en":"He comes to announce the big day and it's for tomorrow","note":"","sourceLineIndex":35},{"id":"les-miserables-cityprod-2017-37-036","lineIndex":35,"speaker":"","original":"C'est pour demain!","ipa":"/sɛ puʁ dəmɛ̃/","zh":"这是为了明天！","en":"It's for tomorrow!","note":"","sourceLineIndex":36}],"sourceOrder":37,"displayOrder":36}];
